GLOBAL_fp, GLOBAL_frel, GLOBAL_frp = GLOBAL_flyout:GetPoint()
eq(GLOBAL_fp, "TOPLEFT", "hanging from its own top left")
eq(GLOBAL_frel, GLOBAL_tlist, "off the type panel")
