        tostring(GLOBAL_flyout.rows[1].subTypeName))

GLOBAL_armourCount = table.getn(db:ItemSubClasses(2))
check(not GLOBAL_flyout.rows[GLOBAL_armourCount + 1]:IsShown(),
        "with the rows it does not need hidden rather than stale")

--[[ Ticking in the flyout is the same act as ticking in the panel. ]]--
db:ToggleType(nil, "Plate")
db:RefreshTypeSubList()
GLOBAL_plateRow = nil
for GLOBAL_i = 1, GLOBAL_armourCount do
    if GLOBAL_flyout.rows[GLOBAL_i].subTypeName == "Plate" then
        GLOBAL_plateRow = GLOBAL_flyout.rows[GLOBAL_i]
    end
end
check(GLOBAL_plateRow and GLOBAL_plateRow:GetChecked(), "a ticked subtype shows ticked")

db:ToggleType(nil, "Plate")
db:RefreshTypeSubList()
check(GLOBAL_plateRow and not GLOBAL_plateRow:GetChecked(), "and unticks again")

db:HideTypeSubList()
check(not GLOBAL_flyout:IsShown(), "and it closes")

db:ToggleType(nil, nil)

--[[ **An empty box with a filter set is a real question.** It used to answer
     the welcome screen, which is what made these feel like a second search term
     rather than a filter. ]]--
GLOBAL_f.search:SetText("")
db:RunBrowserSearch("")
eq(db.browserMode, "search", "an empty search with a filter still searches")
check(table.getn(db.browserItems) > 0, "and finds the things that match",
        table.getn(db.browserItems) .. " rows")

for GLOBAL_i = 1, table.getn(db.browserItems) do
    check((tonumber(db.browserItems[GLOBAL_i].quality) or 0) >= 3,
            "every row past the filter is at least rare")
end

db:ResetBrowserFilter(true)
check(not db:BrowserFilterActive(), "Reset puts every control back")

--[[ **A name that matches no item is tried as the thing that drops one.** ]]--
db:RunBrowserSearch("Rattlegore")
eq(db.browserSourceQuery, "Rattlegore", "a boss's name is understood as a boss too")

--[[ **Both answers, merged.** "Rattlegore" is also the first word of an item
     this boss drops, so the item search succeeds -- and a lookup that only ran
     when the item search came back empty would never fire here, which is
     precisely the case somebody asking about a boss cares about. ]]--
GLOBAL_got = filterIds(db.browserItems)
check(GLOBAL_got[1001], "the item whose name matched is in the list")
check(GLOBAL_got[1002], "and so is the rest of what that boss drops")

-- ---------------------------------------------------------------------------
-- and standing in a dungeon is itself a question
-- ---------------------------------------------------------------------------

