AtlasCFM = nil
db.knownInstances = nil

end

itemFilterTests()

-- 42. everything is reachable from the panel
--
-- The standing rule, asserted rather than trusted. Prat's whole shape was
-- behaviour that existed and a settings window that did not know about it, and
-- every action added here since has been one slash command away from the same
-- mistake.
-- ---------------------------------------------------------------------------

function panelReachTests()

context = "reachable: "

EquadisClassicOverhaulDB = nil
OB = boot("ROGUE", 3)

--[[ Every feature switched on, because a module's rows are only built while it
     is -- and a page nobody built cannot be swept for what is missing. ]]--
for id, m in pairs(OB.modules) do
    if m.feature then OB.profile.modulesEnabled[id] = true end
end

OB.BindSlots()
OB.TogglePanel()

--[[ **Every action the slash prompt offers has a control somewhere.**

     The list is short and hand-written on purpose. The point is to name the
     actions that exist, so adding one and forgetting the panel fails here
     rather than in somebody's session. ]]--
slashActions = {
    { "bind", "actionbars", "bind mode" },
    { "bars", "actionbars", "moving the bars" },
    { "select", "qol", "choosing items in your bags" },
    { "sell", "qol", "selling junk now" },
    { "roster", "roster", "reporting on known players" },
    { "trash", "qol", "the never-keep list" },
}

--[[ What each module's page can do. An action row is the only kind with a
     function behind it and no value, which is what makes it findable. ]]--
declaredActions = {}

for id, m in pairs(OB.modules) do
    declaredActions[id] = 0

    if m.options then
        for i = 1, table.getn(m.options) do
            if m.options[i][3] == "action" then
                declaredActions[id] = declaredActions[id] + 1
            end
        end
    end
end

unreachable = {}

for i = 1, table.getn(slashActions) do
    local entry = slashActions[i]
    local reached = (declaredActions[entry[2]] or 0) > 0

    --[[ The never-keep list is the one that is a *setting* rather than an
         action: the panel edits the string directly, which is better than a
         button, so a text row is what counts as reaching it. ]]--
    if entry[1] == "trash" then
        reached = false

        for j = 1, table.getn(OB.modules.qol.options) do
            if OB.modules.qol.options[j][2] == "@account:trash" then reached = true end
        end
    end

    if not reached then
        table.insert(unreachable, "/eq " .. entry[1] .. " (" .. entry[3] .. ")")
    end
end

eq(table.getn(unreachable), 0,
        "every action reachable by typing is reachable from the panel",
        table.concat(unreachable, ", "))

--[[ And the rows are really built rather than only declared. A row that throws
     during construction is dropped and the page carries on -- which is right,
     and means "declared" and "on screen" are two different claims. ]]--
builtActions = 0

for key, widget in pairs(OB.widgets) do
    if widget.kind == "action" then builtActions = builtActions + 1 end
end

check(builtActions >= 8, "and the action rows are built, not just declared",
        "built: " .. builtActions)

--[[ **An action is not a setting.** It has a key, which makes it look
     addressable, and there is nothing at the end of it -- so the slash prompt
     must not offer one and the self-test must not try to read one. ]]--
offered = {}

for id, index in pairs(OB.optionIndex.modules) do
    for key, w in pairs(index) do
        if w.kind == "action" then table.insert(offered, id .. " " .. key) end
    end
end

eq(table.getn(offered), 0, "and no action is offered as a typed option",
        table.concat(offered, ", "))

--[[ **The shared look goes only on pages that draw with it.**

     Texture, font, font size, outline and border are added to a subsystem's page
     from one place, so a new one cannot arrive with four of them and a
     differently worded fifth. That block used to go on *every* feature page --
     which put "Bar Texture" and "Border" on the chat page, five controls that do
     nothing on a module owning no bar and no border. Reported as exactly that.

     The flag is declared rather than inferred, and `renders` cannot stand in for
     it: nameplates, action bars and unit frames all say "none" because they draw
     into the client's own frames, and all three use the shared look. ]]--
--[[ **A module may also declare the rows itself, and that is not the fault this
     is looking for.**

     Tooltip does: `styled = false`, and its own `Bar Texture` and `Border` rows
     written out in its options, because its health bar needs a second font and
     its frame takes a background colour the shared block has no row for. It was
     being reported as an unstyled page carrying look controls, which is the
     opposite of what it is -- the controls are there *because* it draws with
     them, and the flag is off only to stop the shared block arriving on top of
     the rows it already has.

     So the question is whether the page ended up with a look control **nobody
     asked for**, which means checking the module's own option list before
     blaming the flag. ]]--
styledWithout, unstyledWith = {}, {}

function declaresOwnLook(m)
    for i = 1, table.getn(m.options or {}) do
        if m.options[i][2] == "texture" then return true end
    end
    return false
end

--[[ **`styled` names the parts, so "offered both" is the wrong question.**

     It used to be all or nothing, and a module that draws one line of text got
     Bar Texture and Border with it -- controls that change nothing on a page
     where everything else does. A module can now say which parts it uses:

         styled = { font = true, fontOutline = true }

     So the check is no longer "styled implies texture". It is that every part a
     module *claims* is on its page, and no part it does not claim is. ]]--
for id, m in pairs(OB.modules) do
    if m.feature and m.styled then
        local claims = m.styled

        --[[ `true` is still every part, which is what a bar-drawing subsystem
             wants and what most of them say. ]]--
        if claims == true then
            claims = { texture = true, font = true, fontSize = true,
                       fontOutline = true, border = true }
        end

        for key in pairs({ texture = true, font = true, fontSize = true,
                           fontOutline = true, border = true }) do
            local present = OB.widgets["module:" .. id .. ":" .. key] ~= nil

            if claims[key] and not present then
                table.insert(styledWithout, id .. ":" .. key)
            elseif not claims[key] and present and not declaresOwnLook(m) then
                table.insert(unstyledWith, id .. ":" .. key)
            end
        end
    elseif m.feature then
        local hasLook = OB.widgets["module:" .. id .. ":texture"] ~= nil

        if hasLook and not declaresOwnLook(m) then
            table.insert(unstyledWith, id)
        end
    end
end

eq(table.getn(unstyledWith), 0,
        "a subsystem that draws nothing styled is offered no texture or border",
        table.concat(unstyledWith, ", "))

eq(table.getn(styledWithout), 0, "and one that does is offered both",
        table.concat(styledWithout, ", "))

--[[ Named directly as well, because the two sweeps above would both pass on an
     addon where nothing was flagged at all. ]]--
check(OB.modules.damage.styled, "the damage meter draws with it")
check(OB.modules.nameplates.styled, "so do nameplates")
check(not OB.modules.chat.styled, "and chat does not")
check(not OB.modules.qol.styled, "nor does quality of life")

OB.TogglePanel()

end

panelReachTests()

-- 44. the rename
--
-- The addon was Equadis' OmniBars and its saved variables were named after it.
-- Renaming the addon renames the store, and a rename with nothing behind it is
-- somebody logging in to find every profile gone -- with the old data still in
-- the file, unreachable, looking exactly like a bug.
-- ---------------------------------------------------------------------------

function renameTests()

context = "rename: "

OB = boot("ROGUE", 3)

--[[ A store written under the old name, with things in it worth keeping.

     `LoadConfig` is called directly rather than through a boot, because the test
     harness clears the new-name store on every boot as part of starting clean --
     which is exactly the state this is about, and driving it through boot would
     be testing the harness rather than the adoption. ]]--
EquadisClassicOverhaulDB = nil
EquadisOmniBarsDB = {
    version = 0,
    profiles = { Default = { scale = 1.25 } },
    chars = {},
    migrated = {},
    roster = { Grimtusk = { class = "WARRIOR", level = 60 } },
    trash = "Broken Fang",
}

OB.adoptedOldSaves = nil
OB.LoadConfig()

check(EquadisClassicOverhaulDB ~= nil, "the new name has a store after loading")
eq(OB.profile.scale, 1.25, "and the old profile is in it")
eq(OB.roster["Grimtusk"].class, "WARRIOR", "along with what was known")
eq(OB.TrashList(), "Broken Fang", "and the list that destroys things")

--[[ **The same table, not a copy.** Copying would leave two stores that drift,
     and the one being written would not be the one anybody looked at. ]]--
check(EquadisClassicOverhaulDB == EquadisOmniBarsDB,
        "adopted by reference rather than copied")

--[[ **The old one is not deleted.** A saved variable the TOC no longer declares
     stops being written the moment the name changes, so it is already frozen --
     and leaving it means going back a version still works. A few kilobytes is
     the difference between a rename you can undo and one you cannot. ]]--
check(EquadisOmniBarsDB ~= nil, "and the old name is left where it was")

--[[ Said once, because somebody who has just watched an addon vanish from their
     list and a differently named one appear deserves telling. ]]--
eq(OB.adoptedOldSaves, true, "the adoption is announced")

--[[ **And it only happens when there is nothing under the new name.** A store
     already written by the new name is the current one, and adopting over it
     would throw away everything since the rename. ]]--
EquadisClassicOverhaulDB = {
    version = 0, profiles = { Default = { scale = 0.75 } }, chars = {}, migrated = {},
}
EquadisOmniBarsDB = {
    version = 0, profiles = { Default = { scale = 1.25 } }, chars = {}, migrated = {},
}

OB.adoptedOldSaves = nil
OB.LoadConfig()

eq(OB.profile.scale, 0.75, "an existing new store wins over the old one")
eq(OB.adoptedOldSaves, nil, "and nothing is announced")

EquadisOmniBarsDB = nil

end

renameTests()

-- 43. nameplates
--
-- A 1.12 nameplate cannot be asked for. There is no GetNamePlateForUnit, no
-- unit token and no event when one appears -- the client makes an unnamed frame,
-- parents it to WorldFrame and tells nobody. Everything here follows from that
-- one fact and none of it is how anybody would design it.
-- ---------------------------------------------------------------------------

function nameplateTests()

context = "nameplates: "

EquadisClassicOverhaulDB = nil
OB = boot("ROGUE", 3)

local plates = OB.modules.nameplates
check(plates ~= nil, "the nameplate module registers")
eq(OB.ModuleEnabled("nameplates"), true, "and ships on")

OB.profile.modulesEnabled.nameplates = true
OB.BindSlots()

local cfg = OB.profile.modules.nameplates

-- ---------------------------------------------------------------------------
-- hostility, read off a colour
-- ---------------------------------------------------------------------------

--[[ **There is no unit to ask.** Nothing to give UnitReaction, so the only thing
     that knows is the bar the client already coloured. Reading a colour to find
     out whether something wants to kill you is absurd, and it is the only way
     there is. ]]--
eq(OB.PlateKind(1, 0, 0), "ENEMY_NPC", "red is an enemy")
eq(OB.PlateKind(1, 1, 0), "NEUTRAL_NPC", "yellow is neutral")
eq(OB.PlateKind(0, 1, 0), "FRIENDLY_NPC", "green is a friendly NPC")
eq(OB.PlateKind(0, 0, 1), "FRIENDLY_PLAYER", "blue is a friendly player")

--[==[ **Grey is a tap, and it used to be nothing.**

     This asserted nil, on the reasoning that the client's four reaction colours
     are exact and anything landing on none of them is something the addon does
     not understand. Sound rule, wrong example: 0.5 grey is not an unrecognised
     colour, it is the one the client draws a mob somebody else tapped, and
     there is no `UnitIsTapped` on 1.12 to ask instead. Falling through to nil
     meant every tapped mob took the fallback colour and wore the enemy red.

     The rule itself still holds and is tested below with a colour that really
     is nothing. ]==]
eq(OB.PlateKind(0.5, 0.5, 0.5), "TAPPED", "grey is a mob somebody else tapped")

--[[ A band rather than an exact triple, so a server that nudges the value
     still reads as a tap. ]]--
eq(OB.PlateKind(0.45, 0.52, 0.48), "TAPPED", "and so is grey near enough to it")

--[[ Anything else is left alone rather than guessed at. A plate coloured by a
     guess is worse than one left as the client drew it. ]]--
eq(OB.PlateKind(0.6, 0.1, 0.8), nil, "and a colour this does not know is left alone")
eq(OB.PlateKind(nil), nil, "and no colour at all is the same")

-- ---------------------------------------------------------------------------
-- finding one
-- ---------------------------------------------------------------------------

--[[ **The signature is the border texture on the first region.** Nothing else
     about a 1.12 plate is distinctive: no name, no type of its own, no field. ]]--
notAPlate = CreateFrame("Button", nil, WorldFrame)
notAPlate.frameType = "Button"
notAPlate:CreateTexture(nil, "ARTWORK")

eq(plates:IsNamePlate(notAPlate), false,
        "a button with a plain texture is not a nameplate")

plates.plates, plates.order, plates.seen = {}, {}, 0
plates:Scan()

enemyPlate = Stub.NewNamePlate("Bloodscalp Berserker", 34, 1, 0, 0, 60)
eq(plates:IsNamePlate(enemyPlate), true, "one with the border texture is")
eq(plates:IsNamePlate(nil), false, "and nothing is not one either")

--[[ Watching a number go up is the whole of detection. There is no event, so the
     child count is compared and only the new tail is walked -- children are
     appended, never inserted. ]]--
check(plates:Scan() >= 1, "a scan finds the plate that is there")
check(plates.plates[enemyPlate] ~= nil, "and takes it over")

platesBefore = table.getn(plates.order)
eq(plates:Scan(), 0, "a second scan with nothing new finds nothing")
eq(table.getn(plates.order), platesBefore, "and adopts nothing twice")

-- ---------------------------------------------------------------------------
-- taking one over
-- ---------------------------------------------------------------------------

--[[ **The originals are kept, not discarded.** They are the only source of
     everything -- the name, the level, the health, and the colour that says
     whether the thing is hostile. Silencing them and then reading them is the
     entire technique. ]]--
adoptedEnemy = plates.plates[enemyPlate]

check(adoptedEnemy.original.name ~= nil, "the client's name string is kept")
check(adoptedEnemy.original.level ~= nil, "and its level string")
check(adoptedEnemy.original.health ~= nil, "and its health bar")

eq(adoptedEnemy.original.name:GetText(), "Bloodscalp Berserker",
        "the name is read from the region the client wrote it into")
eq(adoptedEnemy.original.level:GetText(), "34", "and the level from the next one")

--[[ Order is the whole of the identification: regions answered in a different
     order would let this read the level as the name and pass. ]]--
check(adoptedEnemy.original.border ~= nil, "the border is the first region")

-- ---------------------------------------------------------------------------
-- and it is drawn at the same scale as the rest of the interface
-- ---------------------------------------------------------------------------

--[[ **A nameplate is a child of `WorldFrame`, and `WorldFrame` is not scaled by
     the UI scale.**

     Everything else you look at -- unit frames, action bars, this addon's own
     windows -- hangs off `UIParent` and inherits its scale. A plate does not,
     so an overlay left at scale 1 draws at a different physical size from the
     rest of the interface: ten-point text on a plate is not ten-point text
     anywhere else, one-pixel borders land between physical pixels, and the
     whole thing reads as slightly soft next to a UI that is crisp.

     That is the difference between these plates and ShaguPlates', which does
     `SetScale(UIParent:GetScale())` as the first thing it does to every plate
     it creates. ]]--
UIParent:SetScale(0.7)

eq(plates:UIScale(), 0.7, "the plate follows the interface scale")

plates:Style(adoptedEnemy)
eq(adoptedEnemy.overlay:GetScale(), 0.7, "so the overlay is drawn at it")

--[[ **And the offset is divided by that scale**, because `SetPoint` measures it
     in the *moving* frame's own coordinate space. Without the division a
     vertical offset of -10 would move the plate seven pixels at a UI scale of
     0.7, every plate would sit closer to its mob than the slider says, and the
     slider would feel like it was lying.

     Same rule the buff frames needed, and the same fix. ]]--
cfg.verticalOffset = -14
plates:Style(adoptedEnemy)

GLOBAL_p, GLOBAL_rel, GLOBAL_rp, GLOBAL_ox, GLOBAL_oy = adoptedEnemy.overlay:GetPoint(1)
near(GLOBAL_oy, -20, 0.01, "the offset is divided by the scale, so -14 stays -14 on screen")

--[[ At scale 1 the division changes nothing, which is what says the correction
     is a conversion rather than a fudge factor. ]]--
UIParent:SetScale(1)
plates:Style(adoptedEnemy)
near(select(5, adoptedEnemy.overlay:GetPoint(1)), -14, 0.01,
        "and at scale one it is left exactly alone")

--[[ The target's emphasis multiplies the interface scale rather than replacing
     it. Setting it directly was the same bug twice over: the plate lost the UI
     scale, *and* the emphasis was measured against the wrong baseline, so a
     target scale of 1.2 was only twenty percent bigger than its neighbours when
     the UI scale happened to be exactly one. ]]--
UIParent:SetScale(0.7)
cfg.markTarget = true
cfg.targetScale = 1.2

plates:RefreshTargetTreatment(adoptedEnemy, true)
near(adoptedEnemy.overlay:GetScale(), 0.84, 0.001,
        "the target is emphasised on top of the interface scale")

plates:RefreshTargetTreatment(adoptedEnemy, false)
near(adoptedEnemy.overlay:GetScale(), 0.7, 0.001,
        "and everything else sits at the interface scale")

cfg.verticalOffset = -10
UIParent:SetScale(1)
plates:Style(adoptedEnemy)

-- ---------------------------------------------------------------------------
-- and plate text is outlined whatever the shared setting says
-- ---------------------------------------------------------------------------

--[[ **Every other module draws onto a backdrop of its own.** A nameplate draws
     onto the world -- a name in front of snow, a health percentage over a
     torch, a cast bar against sand. Unoutlined text there does not read as
     plainer, it disappears, and it disappears differently depending on which
     way the camera is facing.

     ShaguPlates hardcodes the outline for this and offers no way out. This is a
     switch: on by default, because the reason is strong enough to be the
     default and not strong enough to be a rule. ]]--
eq(cfg.forceOutline, true, "plate text is outlined by default")

GLOBAL_wasOutline = OB.profile.fontOutline
GLOBAL_wasPlateOutline = cfg.fontOutline
OB.profile.fontOutline = false
cfg.fontOutline = nil

plates:Style(adoptedEnemy)
eq(select(3, adoptedEnemy.name:GetFont()), "OUTLINE",
        "the name keeps its outline with the shared setting off")
eq(select(3, adoptedEnemy.text:GetFont()), "OUTLINE", "and the health text")
eq(select(3, adoptedEnemy.castName:GetFont()), "OUTLINE", "and the cast text")

--[[ Off hands it back to the shared setting, which is what makes it a switch
     rather than a rule with a label on it. ]]--
cfg.forceOutline = false
plates:Style(adoptedEnemy)
eq(select(3, adoptedEnemy.name:GetFont()), nil,
        "switched off it follows the shared font setting again")

OB.profile.fontOutline = GLOBAL_wasOutline
cfg.fontOutline = GLOBAL_wasPlateOutline
cfg.forceOutline = true
plates:Style(adoptedEnemy)

-- ---------------------------------------------------------------------------
-- drawing one
-- ---------------------------------------------------------------------------

plates:Refresh(adoptedEnemy)

eq(adoptedEnemy.health.value, 0.6, "health is a fraction of the original bar")
eq(adoptedEnemy.kind, "ENEMY_NPC", "and the kind comes from its colour")

--[[ **Abbreviated rather than truncated.** "Bloodscalp Berserker" on a 120 wide
     plate has to give somewhere, and everything-but-the-last-word-as-an-initial
     keeps the part that tells one mob from the next. Truncating gives
     "Bloodscalp Ber", which does not.

     **The threshold is set here rather than left to the default**, because
     "Bloodscalp Berserker" is exactly twenty characters and the default is
     exactly twenty -- so this example never once exercised the rule it was
     written for. "Shorten After 20" means longer than twenty, which is what the
     module does and what the caption says; the test was reading it as "twenty or
     more". The boundary is worth pinning, so it gets its own two lines below
     rather than riding silently on an example that meant to be well past it. ]]--
cfg.nameMaxLength = 16
eq(plates:ShortName("Bloodscalp Berserker"), "B. Berserker", "long names shorten")
eq(plates:ShortName("Kobold"), "Kobold", "short ones are left alone")

cfg.nameMaxLength = 20
eq(plates:ShortName("Bloodscalp Berserker"), "Bloodscalp Berserker",
        "a name exactly at the threshold is not past it")
cfg.nameMaxLength = 19
eq(plates:ShortName("Bloodscalp Berserker"), "B. Berserker",
        "and one character over is")
cfg.nameMaxLength = 16

cfg.shortenNames = false
eq(plates:ShortName("Bloodscalp Berserker"), "Bloodscalp Berserker",
        "and nothing shortens with it switched off")
cfg.shortenNames = true

--[[ The colour follows the setting rather than the client, which is the point of
     taking the plate over at all. ]]--
cfg.enemyColor = { 1, 0, 1, 1 }
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.health.barColor[1], 1, "an enemy takes the enemy colour")
eq(adoptedEnemy.health.barColor[2], 0, "as set")
eq(adoptedEnemy.health.barColor[3], 1, "on the panel")

--[[ **Which plates show at all.** Enemies on, friendlies off, which is what
     makes a nameplate useful: they exist to tell you what is attacking you. ]]--
eq(cfg.friendlyPlayer, false, "friendly players are hidden by default")

friendPlate = Stub.NewNamePlate("Sylvie", 60, 0, 0, 1, 100)
plates:Scan()

adoptedFriend = plates.plates[friendPlate]
plates:Refresh(adoptedFriend)

eq(adoptedFriend.kind, "FRIENDLY_PLAYER", "a friendly player is recognised")
eq(adoptedFriend.overlay.shown, false, "and hidden, because the setting says so")

cfg.friendlyPlayer = true
plates:Refresh(adoptedFriend)
eq(adoptedFriend.overlay.shown, true, "switching it on shows them")

--[[ **Health as a number can only be a percentage.** There is no unit, so there
     is no current and no maximum -- only a fraction of a bar whose real numbers
     the client never wrote down. ]]--
cfg.healthText = "max"
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.text:GetText(), "60%",
        "even 'current / max' can only honestly answer the percentage")

cfg.healthText = "none"
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.text.shown, false, "and none means none")

-- ---------------------------------------------------------------------------
-- the one plate that has a unit
-- ---------------------------------------------------------------------------

--[[ **The client raises the targeted plate's alpha to 1 and dims the rest.**
     That is the only signal there is, and it is enough.

     What makes it worth the trouble is not the highlight. The target is the one
     nameplate in the world with a unit token, so everything the game will not
     tell you about a plate -- is it casting, is it attacking me -- becomes
     answerable the moment you know the plate you are looking at is "target". ]]--
Stub.player.hasTarget = false
enemyPlate:SetAlpha(1)
eq(plates:IsTarget(adoptedEnemy), false, "with no target, no plate is the target")

Stub.player.hasTarget = true
eq(plates:IsTarget(adoptedEnemy), true, "a plate at full alpha is the target's")

friendPlate:SetAlpha(0.5)
eq(plates:IsTarget(adoptedFriend), false, "and a dimmed one is not")

--[[ Told apart from the wall: bigger, and everything else faded. Forty identical
     rectangles with no way to see which your spells are going to is the thing
     nameplates are worst at. ]]--
cfg.markTarget = true
plates:Refresh(adoptedEnemy)
plates:Refresh(adoptedFriend)

eq(adoptedEnemy.overlay.scale, cfg.targetScale, "the target's plate grows")
eq(adoptedFriend.overlay.alpha, cfg.otherAlpha, "and the others fade")

--[[ Only while there *is* a target. With none, every plate is equally
     interesting and dimming them all says nothing. ]]--
Stub.player.hasTarget = false
plates:Refresh(adoptedFriend)
eq(adoptedFriend.overlay.alpha, 1, "with no target, nothing is faded")
Stub.player.hasTarget = true

-- ---------------------------------------------------------------------------
-- guild names, which the client will not answer by name
-- ---------------------------------------------------------------------------

--[==[ **`GetGuildInfo` takes a unit token and a nameplate has no unit.**

     That is the whole difficulty, and it is the same one the class colours have.
     A guild can only be asked while the unit happens to be reachable -- your
     target, your mouseover -- or learned from a roster that answers by name.

     Off by default: a guild tag is a third line of text on something already
     carrying two, and in a city it is a third line on forty of them. ]==]
eq(cfg.showGuildName, false, "guild names are opt-in")

cfg.showGuildName = true
cfg.friendlyPlayer = true

plates:Refresh(adoptedFriend)
eq(adoptedFriend.guild.shown, false,
        "a player nobody has heard of shows no guild")

--[==[ **The roster answers by name, which is why it can answer at all.**

     Nobody has targeted Sylvie. The guild roster still knows her, because being
     in the guild roster is what put her there -- and that is the case that makes
     this feature worth having, since the players you most want tagged are the
     ones you never click on. ]==]
Stub.guild = { { name = "Sylvie", level = 60, class = "PRIEST" } }
Stub.playerGuild = "Wipe Club"
OB.modules.roster:LearnGuild()

eq(OB.roster["Sylvie"].guild, "Wipe Club",
        "the guild roster is a list of one guild's members, so it knows theirs")

plates:Refresh(adoptedFriend)
eq(adoptedFriend.guild.shown, true, "and now the plate can say so")
eq(adoptedFriend.guild:GetText(), "Wipe Club", "with the guild on it")

--[==[ Green for your own. Everybody else's guild is a name to read; yours is a
     fact to notice, and at nameplate size a colour is read before a word. ]==]
eq(OB.Round((adoptedFriend.guild.color or {})[2] * 10), 9,
        "your own guild is green")

Stub.guildOf["Sylvie"] = nil
OB.roster["Sylvie"].guild = "Some Other Guild"
plates:Refresh(adoptedFriend)

check(((adoptedFriend.guild.color or {})[1] or 0) > 0.5,
        "and somebody else's is not")

--[==[ **A red plate is not taken on trust, and this is not hypothetical.**

     Enemy players and enemy NPCs are painted the same colour by the client. A
     mob named after a guilded player would otherwise wear that player's guild
     -- the same bug, in the same place, that ShaguPlates had to fix for class
     colours. So a red plate must have been targeted or hovered first. ]==]
OB.roster["Bloodscalp Berserker"] = OB.roster["Bloodscalp Berserker"] or {}
OB.roster["Bloodscalp Berserker"].guild = "Definitely A Guild"

adoptedEnemy.playerVerified = nil
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.guild.shown, false,
        "an unverified red plate shows no guild, whatever the roster claims")

--[==[ Verified, it may. The verification is a unit token having existed, which
     is the only thing that separates a player from a mob with the same name. ]==]
adoptedEnemy.playerVerified = true
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.guild.shown, true, "a verified one may")

adoptedEnemy.playerVerified = nil
OB.roster["Bloodscalp Berserker"].guild = nil
cfg.showGuildName = false
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.guild.shown, false, "and off is off")

--[==[ **An empty string is the client saying "none", not saying nothing.**

     Somebody who leaves a guild is answered as "" rather than nil. Read as "no
     news" they would keep wearing the guild they left for the rest of the
     session, which is the sort of wrong that never corrects itself. ]==]
OB.modules.roster:Learn("Sylvie", nil, nil, nil, "")
eq(OB.roster["Sylvie"].guild, nil, "leaving a guild clears it")


-- ---------------------------------------------------------------------------
-- a red plate proved once stays proved
-- ---------------------------------------------------------------------------

--[==[ **Two reports, one cause: `playerVerified` lived on the frame.**

     Enemy players and enemy NPCs are painted the same colour by the client, so
     the only proof a red plate is a player is `UnitIsPlayer` -- which needs a
     unit token, which a plate has only while it is your target or under your
     cursor.

     That proof was stored on the plate, and nameplate frames are recycled: a
     plate that leaves the screen and comes back has been handed to somebody
     else and everything it knew is thrown away. So a hostile player was grey
     until you clicked them and grey again the moment you turned the camera.
     Both symptoms, one line of storage in the wrong place.

     The fact is about the *player*, not about the frame. `UnitIsPlayer` said
     yes about a name; a frame being reused does not make that stop being
     true. ]==]
plates.verifiedPlayers = {}
OB.roster["Bloodscalp Berserker"] = {}
cfg.enemyClassColor = true
cfg.rosterClasses = true

plates:ResetPlateIdentity(adoptedEnemy)
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.kind, "ENEMY_NPC", "a red plate nobody has proved is a mob")

--[==[ **Proved through the real call**, rather than by setting the flag by hand:
     the line that writes the proof down is the thing under test, and a test that
     sets `playerVerified` itself would pass with that line deleted. ]==]
GLOBAL_realUnitName = UnitName
GLOBAL_realUnitExists = UnitExists
GLOBAL_realUnitClass = UnitClass
GLOBAL_realUnitIsPlayer = UnitIsPlayer

UnitName = function(u)
    if u == "target" then return "Bloodscalp Berserker" end
    return GLOBAL_realUnitName(u)
end

UnitExists = function(u)
    if u == "target" then return 1 end
    return GLOBAL_realUnitExists(u)
end

UnitIsPlayer = function(u)
    if u == "target" then return 1 end
    return GLOBAL_realUnitIsPlayer(u)
end

UnitClass = function(u)
    if u == "target" then return "Rogue", "ROGUE" end
    return GLOBAL_realUnitClass(u)
end

plates:RefreshIdentity(adoptedEnemy, "Bloodscalp Berserker", 34, "target")

UnitName = GLOBAL_realUnitName
UnitExists = GLOBAL_realUnitExists
UnitClass = GLOBAL_realUnitClass
UnitIsPlayer = GLOBAL_realUnitIsPlayer

check(adoptedEnemy.playerVerified, "targeting one proves it")
eq(adoptedEnemy.playerClass, "ROGUE", "and answers the class")

--[==[ **Written down twice, because the two stores answer different questions.**

     The session table remembers that this *name* is a player, which is what a
     recycled plate needs and what nothing else records. The roster remembers the
     class, which is what a plate needs after a reload -- and the roster was
     already being handed this player's guild, so it had been learning half of
     what was in front of it. ]==]
check(plates:KnownPlayer("Bloodscalp Berserker"),
        "the proof is remembered against the name")
eq(OB.roster["Bloodscalp Berserker"].class, "ROGUE",
        "and the class goes to the roster, which outlives the session")

--[==[ **The recycle, which is what turning the camera away and back does.**

     Everything the plate knew is gone. The colour must not be. ]==]
plates:ResetPlateIdentity(adoptedEnemy)
eq(adoptedEnemy.playerVerified, nil, "a recycled plate has forgotten everything")

plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.kind, "ENEMY_PLAYER", "and is a player again without being clicked")

GLOBAL_rogueR, GLOBAL_rogueG = OB.ClassColor("ROGUE")
near(adoptedEnemy.health.barColor[1], GLOBAL_rogueR, 0.001,
        "wearing the class colour it was proved to have",
        tostring(adoptedEnemy.health.barColor[1]))
near(adoptedEnemy.health.barColor[2], GLOBAL_rogueG, 0.001, "on every channel")

-- ---------------------------------------------------------------------------
-- and the database may stand in for the proof
-- ---------------------------------------------------------------------------

--[==[ **A switch, because it is the one inference here that can be wrong.**

     The roster only ever learns players -- from `/who`, guild, friends, party
     and targeting -- so a name it knows is a player. Right up to the one case it
     is not: **an NPC named the same as a real player** wears that player's class
     colour. That is the ShaguPlates bug this code was written to avoid.

     On by default, because the failure it prevents is rare and cosmetic while
     the failure it causes is the feature not working at all -- which is how it
     was reported. A name a real unit confirmed is believed whatever this is set
     to; that costs nothing and can never be wrong. ]==]
plates.verifiedPlayers = {}
OB.roster["Bloodscalp Berserker"] = { class = "MAGE" }

plates:ResetPlateIdentity(adoptedEnemy)
plates:Refresh(adoptedEnemy)

eq(adoptedEnemy.kind, "ENEMY_PLAYER", "a name the database knows is a player")

GLOBAL_mageR = OB.ClassColor("MAGE")
near(adoptedEnemy.health.barColor[1], GLOBAL_mageR, 0.001,
        "and is coloured from it",
        tostring(adoptedEnemy.health.barColor[1]))

cfg.rosterClasses = false
plates:ResetPlateIdentity(adoptedEnemy)
plates:Refresh(adoptedEnemy)

eq(adoptedEnemy.kind, "ENEMY_NPC",
        "switched off, a red plate needs proof of its own again")

--[[ And a confirmed name is still believed with the switch off, which is the
     half of this that is never a guess. ]]--
plates:RememberPlayer("Bloodscalp Berserker", "ROGUE")
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.kind, "ENEMY_PLAYER", "proof outranks the switch")

cfg.rosterClasses = true
plates.verifiedPlayers = {}
OB.roster["Bloodscalp Berserker"] = {}
plates:ResetPlateIdentity(adoptedEnemy)
plates:Refresh(adoptedEnemy)

-- ---------------------------------------------------------------------------
-- totems, which all look the same
-- ---------------------------------------------------------------------------

--[==[ **`UnitCreatureType` says it is a totem; only the name says which one.**

     The type is answered in the client's own language, which is why the test
     for it compares against `CREATURE_TYPE_TOTEM` rather than a shipped word.
     The icon cannot be got that way -- twenty-six totems share one type -- so
     the mapping is by name, and a name table is an English table. ]==]
eq(cfg.totemIcons, false, "totem icons are opt-in too")

eq(plates:TotemIcon("Tremor Totem"), "Interface\\Icons\\spell_nature_tremortotem",
        "a totem's name finds its icon")
eq(plates:TotemIcon("Tremor Totem VII"),
        "Interface\\Icons\\spell_nature_tremortotem",
        "and a rank on the end does not stop it")
eq(plates:TotemIcon("Bloodscalp Berserker"), nil, "a mob is not a totem")
eq(plates:TotemIcon(nil), nil, "and neither is nothing")

--[==[ **The creature type is set after the name, not before it.**

     A nameplate frame is recycled -- the same frame comes back as a different
     mob -- so a changed name resets everything learned about the old one, the
     creature type included. Setting the type first and then renaming would
     silently wipe it, and the test would be asserting against a plate that had
     forgotten it was a totem.

     In the game the type arrives from `UnitCreatureType` while the plate is
     targeted or hovered, which is likewise after the name is known. ]==]
--[==[ **`hideTotemHealth` off for this, so the bar answers to one thing.**

     It defaults on, and it hides a totem's health bar whatever the icon setting
     says. Left on, every "the bar is gone" below would pass without the icon
     feature existing at all -- and the one case that matters, an unrecognised
     totem keeping the bar it was about to lose, could not be told apart from
     the same bar being hidden for the other reason. ]==]
cfg.hideTotemHealth = false

cfg.totemIcons = true
adoptedEnemy.original.name:SetText("Tremor Totem")
plates:Refresh(adoptedEnemy)

adoptedEnemy.creatureType = "Totem"
plates:Refresh(adoptedEnemy)

eq(adoptedEnemy.totemIcon.shown, true, "a totem is drawn as its icon")
eq(adoptedEnemy.totemIcon:GetTexture(),
        "Interface\\Icons\\spell_nature_tremortotem", "the right icon")

--[==[ It *replaces* the plate rather than decorating it. A totem's health is not
     the question anybody has about it, and the bar and the name are the two
     things making four totems in a stack indistinguishable. ]==]
eq(adoptedEnemy.health.shown, false, "and the bar it replaces is gone")
eq(adoptedEnemy.name.shown, false, "along with the name")
eq(adoptedEnemy.level.shown, false, "and the level")

--[==[ **Two conditions, not one.** The option being on is not enough: a totem
     whose name is not in the table yields no icon, and hiding the bar in favour
     of a texture that was never set leaves an empty plate. Whatever it is, it
     keeps its bar until there is something better to put there. ]==]
adoptedEnemy.original.name:SetText("Vergessenes Totem")
plates:Refresh(adoptedEnemy)

adoptedEnemy.creatureType = "Totem"
plates:Refresh(adoptedEnemy)

eq(adoptedEnemy.totemIcon.shown, false, "an unrecognised totem gets no icon")
eq(adoptedEnemy.health.shown, true, "and keeps the bar it would have lost")

--[==[ And the type still has to say totem. A mob with "Totem" in its name is a
     mob, and there are plenty of them. ]==]
adoptedEnemy.original.name:SetText("Tremor Totem")
plates:Refresh(adoptedEnemy)

adoptedEnemy.creatureType = "Humanoid"
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.totemIcon.shown, false,
        "a humanoid named after a totem is still a humanoid")

cfg.totemIcons = false
cfg.hideTotemHealth = true
adoptedEnemy.creatureType = nil
adoptedEnemy.original.name:SetText("Bloodscalp Berserker")
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.health.shown, true, "switched off, the bar is back")

-- ---------------------------------------------------------------------------
-- threat, for the target only
-- ---------------------------------------------------------------------------

--[[ `UnitIsUnit("targettarget", "player")` is the whole question: the thing you
     are looking at is attacking you, or it is attacking somebody else.

     **Only the target, and not because it was easier.** There is no unit token
     for any other plate, so for the rest the question cannot be asked at all.
     ShaguPlates reaches it through SuperWoW's GUID support, which is a client
     mod rather than an API -- and the standing rule here is that a client mod
     may improve an answer, never be required for one. ]]--
Stub.player.targetsTarget = nil
Stub.player.targetFriendly = nil

eq(plates:TargetThreat(), nil, "nothing attacking your target is no answer")

Stub.player.targetsTarget = "player"
eq(plates:TargetThreat(), true, "your target attacking you is threat")

Stub.player.targetsTarget = "someone"
eq(plates:TargetThreat(), false, "attacking somebody else is not")

--[[ A friendly target's target is not a threat relationship, it is a healer
     looking at a tank. ]]--
Stub.player.targetFriendly = true
eq(plates:TargetThreat(), nil, "and a friendly target has no threat to describe")
Stub.player.targetFriendly = nil

cfg.colorByThreat = true
Stub.player.targetsTarget = "player"
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.health.barColor[1], cfg.threatColor[1],
        "a target on you takes the threat colour")

Stub.player.targetsTarget = "someone"
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.health.barColor[1], cfg.noThreatColor[1],
        "and one on somebody else takes the other")

--[[ Nil keeps the ordinary colour rather than being painted as though the
     answer were no -- "nobody is attacking it" and "it is not attacking you"
     are different facts. ]]--
Stub.player.targetsTarget = nil
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.health.barColor[1], cfg.enemyColor[1],
        "and no relationship at all keeps the plate's own colour")

-- ---------------------------------------------------------------------------
-- the bar as a ramp rather than as two colours
-- ---------------------------------------------------------------------------

--[==[ **"Does it have me" is the answer you need after something went wrong.**

     The ramp answers the one you need before it -- how close am I -- which is
     the reading the threat meter exists for and the reason to look at it during
     a pull.

     The colours come from the meter rather than from a second palette here. The
     maths is four lines and could have been copied; then there would be two
     answers to "what does about to pull look like", drifting apart the first
     time either was touched. ]==]
GLOBAL_meter = OB.modules.threat
GLOBAL_meterCfg = OB.profile.modules.threat
GLOBAL_me = UnitName("player")

cfg.threatGradient = true
Stub.player.targetsTarget = "player"

--[[ Nothing on the channel, which is most of the time: solo, out of combat, or
     with the meter off. There is no reading to ramp, so it falls back to the
     two colours rather than painting "safe" -- green for "no data" is a claim,
     and the wrong one. ]]--
GLOBAL_meter.entries = {}
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.health.barColor[1], cfg.threatColor[1],
        "with no threat reading it falls back to the flat colours")

--[==[ **Proved on a middle reading, not on the ends.**

     The two flat colours this falls back to are, by design, the same values as
     the ramp's two ends -- `threatColor` is the pull red and `noThreatColor` is
     the safe green. So "the bar is red at a rip" is true whether the ramp ran or
     whether it fell back, and a test that asserted only the ends could not tell
     a working gradient from a broken one. It did not, and the first version of
     this passed while `OB.MyThreatColor` was answering nothing at all.

     Halfway is the reading no flat colour can produce. Melee rip at 110, so 55
     per cent is the middle of the ramp and the meter's own close colour. ]==]
--[[ Bound, not merely enabled: the packets arrive as an event, and an unbound
     module has registered for nothing. Setting the flag without rebinding gave
     a meter with no entries, which is the shape of "no reading" -- and the
     fallback made that look like a pass. ]]--
OB.profile.modulesEnabled.threat = true
OB.BindSlots()

Stub.FireEvent("CHAT_MSG_ADDON", "TWT",
        "TWTv4=Tank:1:12000:100:1;" .. GLOBAL_me .. ":0:6600:55:1")
Stub.Tick(0.05, 2)

check(GLOBAL_meter:Mine() ~= nil, "the meter has a reading to give")
check(OB.MyThreatColor() ~= nil, "and hands it out as a colour")

plates:Refresh(adoptedEnemy)

near(adoptedEnemy.health.barColor[1], GLOBAL_meterCfg.closeColor[1], 0.05,
        "halfway to a rip paints the middle of the ramp",
        tostring(adoptedEnemy.health.barColor[1]))
near(adoptedEnemy.health.barColor[2], GLOBAL_meterCfg.closeColor[2], 0.05,
        "on every channel", tostring(adoptedEnemy.health.barColor[2]))

--[[ Neither flat colour can be mistaken for it, which is what makes the
     assertion above worth making. ]]--
check(math.abs(adoptedEnemy.health.barColor[1] - cfg.threatColor[1]) > 0.05
        or math.abs(adoptedEnemy.health.barColor[2] - cfg.threatColor[2]) > 0.05,
        "and it is not the flat threat colour")

--[[ The same colour the meter would give the same reading, which is the whole
     point of the meter owning it. ]]--
--[[ Guarded, because `RowColor` on a missing entry throws rather than
     answering -- and a throw here takes the whole suite down instead of
     reporting the one thing that is wrong. ]]--
GLOBAL_row = GLOBAL_meter:Mine()
        and GLOBAL_meter:RowColor(GLOBAL_meter:Mine(), GLOBAL_meter:Mine())

check(GLOBAL_row ~= nil, "the meter can colour the same reading")
near(adoptedEnemy.health.barColor[1], GLOBAL_row and GLOBAL_row[1] or -1, 0.001,
        "exactly what the meter shows for it")

--[[ And at a rip, the pull end. ]]--
Stub.FireEvent("CHAT_MSG_ADDON", "TWT",
        "TWTv4=Tank:1:12000:100:1;" .. GLOBAL_me .. ":0:13200:110:1")
Stub.Tick(0.05, 2)

plates:Refresh(adoptedEnemy)
near(adoptedEnemy.health.barColor[1], GLOBAL_meterCfg.pullColor[1], 0.05,
        "and 110 percent as melee paints the pull end",
        tostring(adoptedEnemy.health.barColor[1]))

--[==[ **Only the target's plate.**

     Threat arrives as one set of figures about one mob, so there is no such
     thing as your threat on the plate over there. A bar coloured from another
     mob's numbers would be confidently wrong, which is worse than uncoloured. ]==]
--[[ A plate is the target when the client draws it at full alpha and fades the
     rest, which is the only signal 1.12 gives -- so the way to stop being the
     target in a test is to be faded, not to write the field. `Refresh`
     recomputes it before the colour is chosen, and would overwrite it. ]]--
adoptedEnemy.frame:SetAlpha(0.6)
plates:Refresh(adoptedEnemy)

check(adoptedEnemy.istarget ~= true, "a faded plate is not the target")
eq(adoptedEnemy.health.barColor[1], cfg.enemyColor[1],
        "and keeps its own colour rather than your threat on something else")

adoptedEnemy.frame:SetAlpha(1)
plates:Refresh(adoptedEnemy)

--[[ And it is behind the switch it refines, rather than being a second opinion
     about it. ]]--
cfg.threatGradient = false
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.health.barColor[1], cfg.threatColor[1],
        "switched off, the two flat colours come back")

Stub.player.targetsTarget = nil
cfg.colorByThreat = false

--[==[ **The border, and the two states the bar version never had.**

     ShaguPlates colours the *border* by threat and leaves the health bar alone,
     which is why it reads as an indicator rather than as the mob changing
     colour -- the existing switch recolours the bar, so a hostile plate stops
     looking hostile in order to say something about threat.

     It also has four states where this had two. A mob can have no target at all
     -- not yet pulled, or just dropped its threat table -- and it can be
     casting, which is the state you most want to notice because it is the one
     you act on. `TargetThreat` folded both into the nil it returns for "does
     not apply", so neither could be coloured. ]==]
context = "threat border: "

cfg.threatBorder = true
Stub.player.hasTarget = true

Stub.player.targetsTarget = "player"
eq(plates:ThreatState(adoptedEnemy), "me", "a mob on you reads as on you")

Stub.player.targetsTarget = "someone"
eq(plates:ThreatState(adoptedEnemy), "other", "and on somebody else as that")

--[[ The state the two-value version could not express: nothing is happening,
     which is worth seeing and is not the same as "does not apply". ]]--
Stub.player.targetsTarget = nil
eq(plates:ThreatState(adoptedEnemy), "none",
        "a mob with no target of its own has its own state")

eq(plates:ThreatStateColor("none")[1], cfg.threatNoneColor[1],
        "and its own colour")

--[[ **Casting wins over all of it.** A border telling you about threat while
     the mob is mid-cast is answering the less urgent question. ]]--
Stub.player.targetsTarget = "player"
adoptedEnemy.cast:Show()
eq(plates:ThreatState(adoptedEnemy), "casting",
        "casting beats whatever the threat relationship is")
adoptedEnemy.cast:Hide()

--[[ A friendly target is still not a threat relationship, and gets no state at
     all rather than being painted as one. ]]--
Stub.player.targetFriendly = true
eq(plates:ThreatState(adoptedEnemy), nil,
        "a friendly target has no threat state to draw")
Stub.player.targetFriendly = nil

cfg.threatGlow = false
Stub.player.targetsTarget = nil

-- ---------------------------------------------------------------------------
-- combo points
-- ---------------------------------------------------------------------------

--[[ On the target's plate and nowhere else. They are the player's points *on
     that unit*, so any other plate would be a lie. ]]--
cfg.showCombo = true
Stub.player.combo = 3

plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.combo[3].shown, true, "three points show three")
eq(adoptedEnemy.combo[4].shown, false, "and not four")

--[==[ **They are the target frame's own orbs.** Each earned point is the
     client's socket ring with the red orb lit inside it, cut from
     `UI-ComboPoint` the way the target frame cuts it -- the orb's cut read
     off `ComboPoint1Highlight` itself. Six-pixel coloured squares were what
     this replaced. ]==]
eq(adoptedEnemy.comboOrbs[3].shown, true, "with the orb lit inside the socket")
eq(adoptedEnemy.comboOrbs[4].shown, false, "and not in the fourth")
eq(adoptedEnemy.comboOrbs[1]:GetTexture(), ComboPoint1Highlight:GetTexture(),
        "the orb is the target frame's own texture")
GLOBAL_clientOrb = { ComboPoint1Highlight:GetTexCoord() }
GLOBAL_plateOrb = { adoptedEnemy.comboOrbs[1]:GetTexCoord() }
near(GLOBAL_plateOrb[1], GLOBAL_clientOrb[1], 0.0001, "cut where the client cuts it (left)")
near(GLOBAL_plateOrb[2], GLOBAL_clientOrb[5], 0.0001, "and (right)")
eq(adoptedEnemy.combo[1]:GetTexture(), adoptedEnemy.comboOrbs[1]:GetTexture(),
        "the ring is from the same file")
GLOBAL_plateRing = { adoptedEnemy.combo[1]:GetTexCoord() }
near(GLOBAL_plateRing[2], 0.375, 0.0001, "cut to the socket")

--[[ Twelve tall at the art's three-to-four, the orb eight of twelve wide,
     growing leftward from the bar's right end as the target frame's row
     does. ]]--
eq(adoptedEnemy.combo[1]:GetHeight(), 12, "a point is the set height")
eq(adoptedEnemy.combo[1]:GetWidth(), 9, "at the art's proportion")
eq(adoptedEnemy.comboOrbs[1]:GetWidth(), 6, "with the orb two thirds of it")
GLOBAL_c1 = { adoptedEnemy.combo[1]:GetPoint(1) }
GLOBAL_c2 = { adoptedEnemy.combo[2]:GetPoint(1) }
eq(GLOBAL_c1[1], "TOPRIGHT", "hung from the bar's right end")
eq(GLOBAL_c1[4] - GLOBAL_c2[4], 10, "each a point and a pixel further left")

cfg.comboSize = 16
plates:Style(adoptedEnemy)
eq(adoptedEnemy.combo[1]:GetHeight(), 16, "the size setting takes")
eq(adoptedEnemy.combo[1]:GetWidth(), 12, "keeping the proportion")
cfg.comboSize = 12
plates:Style(adoptedEnemy)

--[[ Read, not remembered: a client that cuts its orb elsewhere is followed,
     and one with no combo frame at all gets the 1.12 cut. ]]--
ComboPoint1Highlight:SetTexCoord(0.4, 0, 0.4, 1, 0.6, 0, 0.6, 1)
GLOBAL_art = plates:ComboArt(true)
near(GLOBAL_art.orb[1], 0.4, 0.0001, "a client that cuts its orb elsewhere is followed")
near(GLOBAL_art.orb[2], 0.6, 0.0001, "on both sides")
ComboPoint1Highlight:SetTexCoord(0.375, 0, 0.375, 1, 0.5625, 0, 0.5625, 1)

GLOBAL_clientHighlight = ComboPoint1Highlight
ComboPoint1Highlight = nil
GLOBAL_art = plates:ComboArt(true)
near(GLOBAL_art.orb[1], 0.375, 0.0001, "with nothing to read, the 1.12 cut stands")
ComboPoint1Highlight = GLOBAL_clientHighlight
plates:ComboArt(true)

plates:Refresh(adoptedFriend)
eq(adoptedFriend.combo[1].shown, false, "a plate that is not the target shows none")

Stub.player.combo = 0
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.combo[1].shown, false, "and none means none")

cfg.showCombo = false

-- ---------------------------------------------------------------------------
-- cast bars, which are the one thing here that is not target-only
-- ---------------------------------------------------------------------------

--[[ **1.12 has no UnitCastingInfo and no UnitChannelInfo.** They arrive in 2.0.
     So every vanilla addon that draws a cast bar for anything but the player has
     built this layer itself.

     `modules/casts.lua` is keyed by unit **name**, not by token, and that is the
     whole reason cast bars work on every plate while threat and combo points do
     not: a nameplate has a name and no token. ]]--
OB.casting = {}
EquadisClassicOverhaulDB.castTimes = {}
OB.castTimes = EquadisClassicOverhaulDB.castTimes

eq(OB.CastInfo("Bloodscalp Berserker"), nil, "nobody is casting anything")

--[==[ **The channel a mob casting at you arrives on, which was not
     registered.**

     `CREATURE_VS_CREATURE` is a mob casting at another mob. A mob casting at
     *you* comes through `CREATURE_VS_SELF`, and at somebody in your group
     through `CREATURE_VS_PARTY`. Neither was asked for, so the commonest case in
     the game never reached this module and its nameplate never drew a bar.

     Checked against the client's own `ChatFrame.lua`, which names every channel
     it has -- the only list that settles which ones exist. ]==]
context = "cast channels: "

GLOBAL_castHeard = OB.casts.frame.events

check(GLOBAL_castHeard["CHAT_MSG_SPELL_CREATURE_VS_SELF_DAMAGE"],
        "a mob casting at you is listened for")
check(GLOBAL_castHeard["CHAT_MSG_SPELL_CREATURE_VS_SELF_BUFF"],
        "buffing itself at you as well")
check(GLOBAL_castHeard["CHAT_MSG_SPELL_CREATURE_VS_PARTY_DAMAGE"],
        "and casting at somebody in your group")
check(GLOBAL_castHeard["CHAT_MSG_SPELL_CREATURE_VS_CREATURE_DAMAGE"],
        "the mob-on-mob channel it already had is kept")

--[==[ **And the client's own cast event, where there is one.**

     `UNIT_CASTEVENT(casterGUID, targetGUID, type, spellId, castTime)` is
     SuperWoW's. Everything read out of the log is a sentence being turned back
     into facts it was never meant to carry; this is the facts -- which unit,
     which spell, and for how long.

     Registering an event a client does not send costs nothing, so it is asked
     for unconditionally and never fires without it. ]==]
check(GLOBAL_castHeard["UNIT_CASTEVENT"], "the client's own cast event is asked for")

--[[ Not `Fireball`. A cast with a duration teaches `OB.castTimes`, and that
     table outlives the test that filled it -- a later check that a log-only cast
     has *no* known duration then reads the one this taught it. Shared state a
     test writes is shared state the next test inherits. ]]--
Stub.spellNames = { [133] = "Shadow Bolt" }
Stub.plateUnits = { ["0xPLATE1"] = { name = "Bloodscalp Berserker" } }
OB.casting = {}

Stub.FireEvent("UNIT_CASTEVENT", "0xPLATE1", "0xPLAYER", "START", 133, 3000)

GLOBAL_evSpell, GLOBAL_evFraction = OB.CastInfo("0xPLATE1")
eq(GLOBAL_evSpell, "Shadow Bolt", "a cast event opens a bar for that exact unit")
check(GLOBAL_evFraction ~= nil,
        "with a duration, which no combat-log line has ever carried")

--[==[ **Filed under the name as well.** Everything that read this before the
     event existed asks by name, and one record under two keys keeps both
     answering the same thing. ]==]
eq(OB.CastInfo("Bloodscalp Berserker"), "Shadow Bolt", "and under the caster's name")

--[[ Ending it ends both keys. Two records would drift the moment one was
     stopped and the other was not -- a bar that ends on one frame and not on
     another. ]]--
Stub.FireEvent("UNIT_CASTEVENT", "0xPLATE1", "0xPLAYER", "CAST", 133, 0)
eq(OB.CastInfo("0xPLATE1"), nil, "finishing ends the cast")
eq(OB.CastInfo("Bloodscalp Berserker"), nil, "under both of its keys")

--[[ An instant is a `CAST` with no `START` before it, and has no bar to draw. ]]--
OB.casting = {}
Stub.FireEvent("UNIT_CASTEVENT", "0xPLATE1", "0xPLAYER", "CAST", 133, 0)
eq(OB.CastInfo("0xPLATE1"), nil, "an instant opens nothing")

--[[ A channel is a start that says so. ]]--
Stub.FireEvent("UNIT_CASTEVENT", "0xPLATE1", "0xPLAYER", "CHANNEL", 133, 3000)
GLOBAL_evSpell, GLOBAL_evFraction, GLOBAL_evChannel = OB.CastInfo("0xPLATE1")
eq(GLOBAL_evSpell, "Shadow Bolt", "a channel opens a bar too")
check(GLOBAL_evChannel, "and says it is one")

--[[ A spell whose name cannot be read is dropped rather than drawn blank: the
     name is the half of a nameplate cast bar that carries the meaning. ]]--
OB.casting = {}
Stub.FireEvent("UNIT_CASTEVENT", "0xPLATE1", "0xPLAYER", "START", 999999, 3000)
eq(OB.CastInfo("0xPLATE1"), nil, "a spell with no readable name draws nothing")

OB.casting = {}
Stub.plateUnits = nil
Stub.spellNames = {}

context = "casts: "

--[[ A mob's cast is read out of the combat log, through the client's own
     sentence rather than by matching English -- the same rule every other line
     in this addon follows. ]]--
local caster, spellName = OB.casts:ReadCastLine("Bloodscalp Berserker begins to cast Fireball.")
eq(caster, "Bloodscalp Berserker", "the caster comes out of the line")
eq(spellName, "Fireball", "and the spell")

eq(OB.casts:ReadCastLine("Bloodscalp Berserker hits you for 40."), nil,
        "a line that is not a cast is not one")

--[[ **A cast with no known duration still draws.** The combat log says a cast
     has begun and nothing about how long it takes -- and *what* is being cast is
     the useful half, so "I do not know how far through this is" is not a reason
     to say nothing. ]]--
OB.StartCast("Bloodscalp Berserker", "Fireball")

local castSpell, castFraction = OB.CastInfo("Bloodscalp Berserker")
eq(castSpell, "Fireball", "the spell is known")
eq(castFraction, nil, "and its progress is not, which is said rather than faked")

--[==[ **A cast that ends, which nothing was reading.**

     `StopCast` was called from exactly one place -- the player's own
     `SPELLCAST_STOP` -- so nobody else's cast was ever ended. It sat in the
     table until it timed out, at the spell's learned duration or at the five
     second cap for an unknown one, and the nameplate kept showing a spell the
     mob had already finished. Reported as the wrong spell always showing.

     Three sentences end one, and **which name is the caster differs between
     them**: a death has one name and it is the caster, an interrupt names the
     interrupter first and the caster second. Reading that the wrong way round
     would end the *interrupter's* cast and leave the real one running, which is
     a bug that looks like no bug at all until two casters are in the log. ]==]
OB.StartCast("Bloodscalp Berserker", "Fireball")
check(OB.CastInfo("Bloodscalp Berserker") ~= nil, "a mob is casting")

--[[ Driven through OnEvent with the client's own globals rather than by
     calling the reader, so the wiring is what is under test: the reader was
     never the missing part, the call to it was. ]]--
event, arg1 = "CHAT_MSG_COMBAT_HOSTILE_DEATH", "Bloodscalp Berserker dies."
OB.casts:OnEvent()

eq(OB.CastInfo("Bloodscalp Berserker"), nil, "and dying ends it")

OB.StartCast("Bloodscalp Berserker", "Fireball")
OB.StartCast("Bloodscalp Shaman", "Healing Wave")

event = "CHAT_MSG_SPELL_BREAK_AURA"
arg1 = "Bloodscalp Shaman interrupts Bloodscalp Berserker's Fireball."
OB.casts:OnEvent()

eq(OB.CastInfo("Bloodscalp Berserker"), nil,
        "an interrupt ends the cast of the one interrupted")
check(OB.CastInfo("Bloodscalp Shaman") ~= nil,
        "and not the one doing the interrupting, who is still casting")

OB.StopCast("Bloodscalp Shaman")

--[[ **The duration is learned, not shipped.** ShaguPlates carries a database of
     every spell in the game; every spell the player casts reports its exact
     duration to the client, and mobs cast a great many of the same spells that
     players do. Fireball is Fireball. ]]--
OB.StartCast(Stub.player.name, "Fireball", 3000)
eq(OB.castTimes["Fireball"], 3000, "casting it yourself teaches its duration")

OB.StartCast("Bloodscalp Berserker", "Fireball")
castSpell, castFraction = OB.CastInfo("Bloodscalp Berserker")
check(castFraction ~= nil, "so the next mob to cast it gets a filling bar")

--[[ **The longest seen wins**, which is the opposite of the levels rule and
     right for the opposite reason: a cast time shortens with haste and with
     talents and lengthens with nothing, so the largest seen is the base. A bar
     drawn from a hasted duration finishes early on somebody who is not hasted,
     which reads as an interrupt that did not happen. ]]--
OB.LearnCastTime("Fireball", 2500)
eq(OB.castTimes["Fireball"], 3000, "a shorter time seen later is haste, not news")

OB.LearnCastTime("Fireball", 3500)
eq(OB.castTimes["Fireball"], 3500, "and a longer one replaces it")

--[[ A channel empties rather than fills. Same number read the other way round,
     and getting it backwards is what nobody notices until they watch a Drain
     Life. ]]--
OB.StartCast("Sylvie", "Drain Life", 5000, true)
local _, drainFraction = OB.CastInfo("Sylvie")
check(drainFraction and drainFraction > 0.9,
        "a channel starts full", tostring(drainFraction))

--[[ **Expiry happens when somebody asks**, rather than on a timer. It costs
     nothing, there is no sweep to schedule, and nothing leaks when a caster dies
     mid-cast and never sends another line. ]]--
OB.casting["Ghost"] = { spell = "Fireball", start = GetTime() - 60, duration = 3000 }
eq(OB.CastInfo("Ghost"), nil, "a cast that ran out is gone when next asked about")
eq(OB.casting["Ghost"], nil, "and forgotten rather than left behind")

--[[ And the plate draws it, for any plate, because the lookup is by name. ]]--
cfg.castbar = true
OB.StartCast("Bloodscalp Berserker", "Fireball", 3000)

plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.cast.shown, true, "a plate whose unit is casting shows a bar")
eq(adoptedEnemy.castName:GetText(), "Fireball", "with the spell on it")

OB.StopCast("Bloodscalp Berserker")
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.cast.shown, false, "and hides it when the cast ends")

--[==[ **Including the spell name, which is not part of the bar.**

     Reported as spells always appearing under nameplates even when nothing is
     casting. The name is parented to the plate's text layer rather than to the
     bar -- it has to be, or a bar eight pixels tall would clip it -- so hiding
     the bar never hid the name. Every path that gave up on drawing a cast hid
     the bar and its border and left the text, so the last spell a mob cast
     stayed printed under its plate for as long as the plate lived.

     The old test asked only about the bar, which is why a font string nobody
     was switching off looked like a cast bar that worked. ]==]
eq(adoptedEnemy.castName:IsShown(), false,
        "and the spell name goes with it")

--[[ The same on the other two ways of giving up: switched off entirely, and a
     name too ambiguous to attribute. Neither drew a bar, and both left the
     text. ]]--
OB.StartCast("Bloodscalp Berserker", "Fireball", 3000)
plates:Refresh(adoptedEnemy)
check(adoptedEnemy.castName:IsShown(), "a real cast puts the name back")

cfg.castbar = false
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.castName:IsShown(), false,
        "switching cast bars off takes the name with them")

-- ---------------------------------------------------------------------------
-- the plate you are reading does not move
-- ---------------------------------------------------------------------------

--[==[ **Which plate the engine moves is not an addon's to choose.**

     Overlap is resolved by the client, which lays the native plates out before
     any of this artwork is drawn. The only thing that can be said about it from
     Lua is how big each plate's collision footprint is -- there is no way to ask
     for one plate to be preferred over another.

     There is a way to take one out of the argument. A 1x1 footprint has nothing
     to push and nothing to be pushed by, so the engine leaves that plate exactly
     over its mob while the rest go on separating from their neighbours. ]==]
context = "target holds still: "

eq(OB.defaults.modules.nameplates.targetHoldsPosition, true,
        "your target holds its place by default")

Stub.player.hasTarget = true
enemyPlate:SetAlpha(1)
plates:Refresh(adoptedEnemy)
eq(plates:IsTarget(adoptedEnemy), true, "with this plate as the target")

GLOBAL_targetW, GLOBAL_targetH = plates:PlateCollisionSize(adoptedEnemy)
eq(GLOBAL_targetW, 1, "its footprint is nothing across")
eq(GLOBAL_targetH, 1, "and nothing down")
eq(enemyPlate:GetWidth(), 1, "which is what the native frame is set to")

--[==[ **Every other plate keeps a real one**, or nothing would separate from
     anything and the setting would be a way of switching overlap handling off
     for the whole screen. ]==]
enemyPlate:SetAlpha(0.5)
plates:Refresh(adoptedEnemy)
eq(plates:IsTarget(adoptedEnemy), false, "a plate that is not the target")

GLOBAL_otherW = plates:PlateCollisionSize(adoptedEnemy)
check(GLOBAL_otherW > 1, "goes back to a real footprint", tostring(GLOBAL_otherW))
check(enemyPlate:GetWidth() > 1, "and the native frame with it")

--[==[ **Asked before the footprint is set, not a frame later.**

     The answer used to be worked out two-thirds of the way down the refresh,
     while the footprint is set at the top. Read late, a plate would hold its
     position for one frame after you stopped targeting it and be shoved for one
     frame after you started -- which is the flicker this exists to remove. It is
     the same shape as the border reading a cast bar that had not been refreshed
     yet, and it is the second time in this module. ]==]
enemyPlate:SetAlpha(1)
plates:Refresh(adoptedEnemy)
eq(enemyPlate:GetWidth(), 1, "targeting takes hold on the same frame")

enemyPlate:SetAlpha(0.5)
plates:Refresh(adoptedEnemy)
check(enemyPlate:GetWidth() > 1, "and letting go does too")

--[[ Switched off, the target is laid out like everything else. ]]--
enemyPlate:SetAlpha(1)
cfg.targetHoldsPosition = false
plates:Refresh(adoptedEnemy)
check(enemyPlate:GetWidth() > 1, "switched off it takes its chances with the rest")

cfg.targetHoldsPosition = true
plates:Refresh(adoptedEnemy)

-- ---------------------------------------------------------------------------
-- the border the state is reported on
-- ---------------------------------------------------------------------------

--[==[ **One surface, and it used to be carrying a decoration.**

     The plate border was white, four or five pixels of shared window art held
     off the bar by the padding that style carries, and on your target it was
     repainted a flat colour to say "this is the one you clicked" -- which the
     target's size and its glow both already say.

     It is a readout now: one pixel hard against the bar, nearly black at rest,
     and coloured only when it has something to report. A colour means nothing
     unless the absence of it does. ]==]
context = "plate border: "

GLOBAL_platesShipped = OB.defaults.modules.nameplates
eq(GLOBAL_platesShipped.targetBorder, nil, "the flat target highlight is gone")
--[==[ **The states are the border's, and the glow marks the target.**

     They were the border's, then the glow's, and are the border's again. The
     reasoning that moved them -- one surface should not do two jobs -- was
     right about the principle and wrong about which surface to move.

     The border is on every plate, so a colour there answers "what is that one
     doing" about the whole screen at once, which is what four states are for.
     The glow is on one plate by definition, so a colour there could only ever
     describe the plate you were already looking at. ]==]
eq(GLOBAL_platesShipped.threatBorder, true, "the state colouring is the border's")
eq(GLOBAL_platesShipped.threatGlow, false, "and the glow does not carry it")

--[==[ **Tight, and not because the shared border style says so.**

     That setting ships as `None` and is a statement about window decoration.
     Reading it here would have shipped the readout switched off for everybody,
     which is a setting answering a question it was never asked. ]==]
eq(OB.defaults.border, 1, "the shared border style ships as None")

cfg.threatBorder = false
Stub.player.targetsTarget = nil
plates:Refresh(adoptedEnemy)

check(adoptedEnemy.healthBorder:IsShown(), "and a plate has a border anyway")

--[[ The client's own tooltip edge -- the art the target ring was drawn in,
     which is the part of that ring worth keeping. A flat one-pixel rectangle
     was tried first: crisp, and a wireframe. ]]--
eq(adoptedEnemy.healthBorder.backdrop.edgeFile, OB.borderEdges[3].edgeFile,
        "drawn in the client's own border art")

--[[ Narrowed to what fits, because both sides of an eight-pixel bar carry a
     corner and two full-size corners do not fit in eight pixels. ]]--
check(adoptedEnemy.healthBorder.backdrop.edgeSize < OB.borderEdges[3].edgeSize,
        "narrowed from the size that art is drawn at on a tooltip")
check(adoptedEnemy.healthBorder.backdrop.edgeSize * 2
        <= adoptedEnemy.health:GetHeight() + (plates:BorderThickness() * 2),
        "to what fits the bar")

--[[ Hung at the thickness it is set to, on all four sides. The band the art is
     drawn in is that distance, which is why one number decides both. ]]--
GLOBAL_pad = plates:BorderThickness()
GLOBAL_borderTL = adoptedEnemy.healthBorder.points[1]
GLOBAL_borderBR = adoptedEnemy.healthBorder.points[2]
eq(GLOBAL_borderTL[4], -GLOBAL_pad, "hung off the bar's left edge by the thickness")
eq(GLOBAL_borderTL[5], GLOBAL_pad, "and above its top")
eq(GLOBAL_borderBR[4], GLOBAL_pad, "the same to the right")
eq(GLOBAL_borderBR[5], -GLOBAL_pad, "and below")

--[[ A tint on that art rather than a colour of its own, dimmed rather than
     full white -- which is the brightest thing that can be drawn and was being
     wrapped around every plate on screen at once. ]]--
check(cfg.borderColor[1] < 1 and cfg.borderColor[1] == cfg.borderColor[3],
        "at rest it is the art, dimmed")
near(adoptedEnemy.healthBorder.backdropBorder[1], cfg.borderColor[1], 0.001,
        "and that is what a plate with nothing to say is drawn in")

--[==[ **The four states, on your target.**

     Three of them are read off `targettarget`, which exists for exactly one
     unit, so this is the only plate that can be asked at all. ]==]
-- ---------------------------------------------------------------------------
-- a plate takes the mouse away, it does not hand it out
-- ---------------------------------------------------------------------------

--[==[ **`EnableMouse(not clickThrough)` is `EnableMouse(true)` most of the
     time**, applied to every plate on every refresh whether or not the plate
     had the mouse to begin with.

     A mouse-enabled frame in 1.12 swallows every button over it, not only the
     ones it has a handler for -- so forcing it on took right-click-drag away
     from the camera anywhere a plate happened to be, which on a pull is most of
     the screen. The same fault the world map had, from the same cause. ]==]
enemyPlate:EnableMouse(false)
adoptedEnemy.frame.mouseWas = nil
cfg.clickThrough = false
plates:Style(adoptedEnemy)

eq(enemyPlate:IsMouseEnabled(), false,
        "a plate that came without the mouse does not get one")

--[[ And one that came with it keeps it, so clicking a nameplate to target
     still works where the client wanted that. ]]--
enemyPlate:EnableMouse(true)
adoptedEnemy.frame.mouseWas = nil
plates:Style(adoptedEnemy)
eq(enemyPlate:IsMouseEnabled(), true, "and one that came with it keeps it")

--[[ Click-through still takes it away: removing the mouse is this module's
     business, adding it was never asked for. ]]--
--[[ Through `Style` rather than `Refresh`: the mouse is settled when a plate
     is dressed, not on every frame it is redrawn on. ]]--
cfg.clickThrough = true
plates:Style(adoptedEnemy)
eq(enemyPlate:IsMouseEnabled(), false, "click-through still switches it off")

cfg.clickThrough = false
plates:Style(adoptedEnemy)
eq(enemyPlate:IsMouseEnabled(), true, "and switching it back gives the mouse back")

cfg.threatBorder = true

Stub.player.targetsTarget = "player"
plates:Refresh(adoptedEnemy)
near(adoptedEnemy.healthBorder.backdropBorder[1], cfg.threatColor[1], 0.001,
        "a target attacking you colours the border")

Stub.player.targetsTarget = "someone"
plates:Refresh(adoptedEnemy)
near(adoptedEnemy.healthBorder.backdropBorder[1], cfg.noThreatColor[1], 0.001,
        "one attacking somebody else takes the other colour")

Stub.player.targetsTarget = nil
plates:Refresh(adoptedEnemy)
near(adoptedEnemy.healthBorder.backdropBorder[1], cfg.threatNoneColor[1], 0.001,
        "and one attacking nothing has its own")

--[[ Red, green, grey, blue -- named by what they have to be distinguishable as,
     not by their numbers. A palette where two states are both "sort of orange"
     is four states you cannot read. ]]--
check(cfg.threatColor[1] > cfg.threatColor[2] + 0.3, "on you is red")
check(cfg.noThreatColor[2] > cfg.noThreatColor[1] + 0.3, "on somebody else is green")
near(cfg.threatNoneColor[1], cfg.threatNoneColor[3], 0.001, "no target is grey")
check(cfg.threatCastColor[3] > cfg.threatCastColor[1] + 0.3
        and cfg.threatCastColor[3] > cfg.threatCastColor[2] + 0.3, "casting is blue")

--[==[ **Casting is the one state a plate can answer for itself.**

     The cast bar is drawn on the plate it belongs to, so this needs no unit
     token and works on a plate that is not your target -- which the other three
     cannot, and which is most of the plates on screen. It was gated underneath
     the target-only checks, so every other plate's cast went uncoloured. ]==]
enemyPlate:SetAlpha(0.5)
eq(plates:IsTarget(adoptedEnemy), false, "a dimmed plate is not your target")

plates:Refresh(adoptedEnemy)
near(adoptedEnemy.healthBorder.backdropBorder[1], cfg.borderColor[1], 0.001,
        "so it is left at rest rather than told it has no target")

--[[ Cast bars were switched off two checks ago and stay off until they are
     switched back on, which is the whole of the first attempt at this. ]]--
cfg.castbar = true
OB.StartCast("Bloodscalp Berserker", "Fireball", 3000)
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.cast.shown, true, "but it can still be seen casting")
near(adoptedEnemy.healthBorder.backdropBorder[3], cfg.threatCastColor[3], 0.001,
        "and the border says so")

OB.StopCast("Bloodscalp Berserker")
plates:Refresh(adoptedEnemy)
near(adoptedEnemy.healthBorder.backdropBorder[1], cfg.borderColor[1], 0.001,
        "and goes back to rest when the cast ends")

--[[ A recycled frame keeps the last mob's colour, and the mob that inherits it
     is not the one that earned it. ]]--
enemyPlate:SetAlpha(1)
Stub.player.targetsTarget = "player"
plates:Refresh(adoptedEnemy)
near(adoptedEnemy.healthBorder.backdropBorder[1], cfg.threatColor[1], 0.001,
        "a plate that has been coloured")

cfg.threatBorder = false
plates:Refresh(adoptedEnemy)
near(adoptedEnemy.healthBorder.backdropBorder[1], cfg.borderColor[1], 0.001,
        "does not keep the colour when it stops applying")

-- ---------------------------------------------------------------------------
-- and the glow says one thing
-- ---------------------------------------------------------------------------

--[==[ **Your target, and nothing else.**

     It briefly carried the four states as well, which is a colour describing the
     only plate whose state you can already read off the rest of the interface --
     while every other plate, the ones the question is actually about, had
     nothing.

     White by default: it has to read over a plate of any colour, and the border
     beside it is already carrying four. ]==]
check(cfg.targetGlowColor[1] == cfg.targetGlowColor[2]
        and cfg.targetGlowColor[2] == cfg.targetGlowColor[3],
        "the glow ships white rather than tinted")

cfg.threatBorder = true
enemyPlate:SetAlpha(1)
Stub.player.targetsTarget = "player"
plates:Refresh(adoptedEnemy)

check(adoptedEnemy.targetGlow:IsShown(), "your target glows")
near(adoptedEnemy.targetGlow.backdropBorder[1], cfg.targetGlowColor[1], 0.001,
        "in its own colour rather than the state's",
        tostring(adoptedEnemy.targetGlow.backdropBorder[1]))

--[[ And a plate with plenty to say, that is not your target, does not glow --
     it says it on the border, where every plate can. ]]--
enemyPlate:SetAlpha(0.5)
plates:Refresh(adoptedEnemy)

check(not adoptedEnemy.targetGlow:IsShown(),
        "and a plate you are not targeting does not, whatever it is doing")

enemyPlate:SetAlpha(1)
cfg.threatBorder = false

-- ---------------------------------------------------------------------------
-- every plate, once the client can name one
-- ---------------------------------------------------------------------------

--[==[ **`targettarget` is one mob, and a pull is eight.**

     Vanilla has no unit token for an arbitrary nameplate, so "what is this mob
     attacking" could only ever be asked of your target -- which is the plate you
     are already looking at, and the least useful one to be told about.

     SuperWoW answers a plate frame's `GetName(1)` with its unit's GUID, and that
     GUID is a unit token. `guid .. "target"` then answers the same question for
     every plate on screen. It is the route the addon this module was ported from
     takes, and the reason its threat colouring works on a pack. ]==]
context = "plate threat: "

cfg.threatBorder = true
Stub.player.targetsTarget = "player"
Stub.player.hasTarget = true
enemyPlate:SetAlpha(0.5)
plates:Refresh(adoptedEnemy)

eq(plates:ThreatState(adoptedEnemy), nil,
        "with no token, a plate that is not your target has no state to draw")

--[[ Gated on the capability before anything is resolved, so a client without it
     pays nothing per plate per frame. ]]--
eq(plates:PlateUnit(adoptedEnemy), nil, "and no unit to ask about")

SUPERWOW_VERSION = "1.4"
OB.RecheckCapabilities()
enemyPlate.superwowGuid = "0xPLATE1"
Stub.plateUnits = { ["0xPLATE1"] = { target = "player" } }

eq(plates:PlateUnit(adoptedEnemy), "0xPLATE1", "with it, a plate resolves its own unit")
eq(plates:ThreatState(adoptedEnemy), "me",
        "and a mob attacking you says so from a plate that is not your target")

Stub.plateUnits["0xPLATE1"].target = "someone"
eq(plates:ThreatState(adoptedEnemy), "other", "one attacking somebody else likewise")

Stub.plateUnits["0xPLATE1"].target = nil
eq(plates:ThreatState(adoptedEnemy), "none", "and one attacking nothing")

--[[ A friendly's target is a healer looking at a tank, not a threat
     relationship -- which matters more here than it did for one plate, because
     in a battleground half of them are friendly. ]]--
Stub.plateUnits["0xPLATE1"] = { target = "someone", friendly = true }
eq(plates:ThreatState(adoptedEnemy), nil, "a friendly plate still has no threat state")

--[==[ **This is the whole point of the GUID route**, and it is why the states
     belong on the border: with a unit token every plate can answer, and the
     border is the surface every plate has. The glow is on one plate by
     definition and could never have shown this. ]==]
Stub.plateUnits["0xPLATE1"] = { target = "player" }
plates:Refresh(adoptedEnemy)
near(adoptedEnemy.healthBorder.backdropBorder[1], cfg.threatColor[1], 0.001,
        "and the border of a plate you are not targeting is coloured by it")

--[==[ **A token is dropped when it stops existing, not kept until the name
     changes.** Plate frames are recycled, and two mobs with the same name and
     level do not reset the identity -- so the GUID is the only thing that knows
     the mob has been replaced. ]==]
Stub.plateUnits = {}
eq(plates:PlateUnit(adoptedEnemy), nil, "a token that no longer exists is not reused")

enemyPlate.superwowGuid = nil
Stub.plateUnits = nil
SUPERWOW_VERSION = nil
OB.RecheckCapabilities()
eq(plates:PlateUnit(adoptedEnemy), nil, "and the client is back to one plate")

enemyPlate:SetAlpha(1)
cfg.threatBorder = true
Stub.player.targetsTarget = nil
cfg.castbar = true
OB.StopCast("Bloodscalp Berserker")

-- ---------------------------------------------------------------------------
-- a cast bar that does not need the mob to have a unique name
-- ---------------------------------------------------------------------------

--[==[ **The suppression was honest and expensive.**

     A combat-log cast line carries a caster *name*. With three Scarlet Myrmidons
     on screen there is no truthful way to say which of them it came from, so
     every one of their cast bars was hidden -- correct, and it means a pull of
     identical mobs shows no casts at all, which is when you most want them.

     A GUID says which. Where the client gives one -- the same token the threat
     colouring resolves -- the cast is filed under it and the plate asks for its
     own. The name path and its suppression stay underneath for clients that
     cannot do that. ]==]
context = "plate cast by unit: "

cfg.castbar = true
cfg.castTargetOnly = false
SUPERWOW_VERSION = "1.4"
OB.RecheckCapabilities()
enemyPlate.superwowGuid = "0xPLATE1"
Stub.plateUnits = { ["0xPLATE1"] = { name = "Bloodscalp Berserker" } }

--[[ Two of them on screen, which is exactly the case that used to draw
     nothing. ]]--
plates.visibleNameCounts = { ["Bloodscalp Berserker"] = 2 }

OB.casting = {}
OB.StartCastFor("0xPLATE1", "Shadow Bolt", 3000)
plates:Refresh(adoptedEnemy)

eq(adoptedEnemy.cast.shown, true,
        "a plate that knows its own unit shows its cast among identical names")
eq(adoptedEnemy.castName:GetText(), "Shadow Bolt", "with the spell on it")

--[[ And the name path is still suppressed, because on a client without a token
     the ambiguity is real and drawing a guess is worse than drawing nothing. ]]--
OB.casting = {}
OB.StartCast("Bloodscalp Berserker", "Fireball")
enemyPlate.superwowGuid = nil
Stub.plateUnits = nil
adoptedEnemy.unitToken = nil
plates:Refresh(adoptedEnemy)

eq(adoptedEnemy.cast.shown, false,
        "without one, two mobs of a name still hide it rather than guess")

plates.visibleNameCounts = nil
OB.casting = {}
SUPERWOW_VERSION = nil
OB.RecheckCapabilities()
plates:Refresh(adoptedEnemy)

context = "nameplates: "

-- ---------------------------------------------------------------------------
-- and you can see which one the cursor is on
-- ---------------------------------------------------------------------------

--[[ **Nameplates are click targets and the client gives almost no sign of which
     one you are about to click.**

     The plate under the cursor looks exactly like the plate beside it, and in a
     pull with six mobs stacked that is a real question with a real cost.

     There is no "is this frame hovered" to ask -- a nameplate is a child of
     `WorldFrame` and the usual idioms do not reach it. What the client does
     instead is show the plate's own glow region on whichever one the cursor is
     over, and set the `mouseover` unit at the same moment. ]]--
eq(cfg.mouseoverGlow, true, "the hovered plate is marked by default")

--[[ Its own colour, and not one of the four the border reports with: a hover is
     something you are doing and the border is something the mob is doing. ]]--
check(cfg.mouseoverGlowColor[3] > cfg.mouseoverGlowColor[1],
        "in a colour of its own")

check(adoptedEnemy.mouseoverGlow ~= nil, "a plate has something to mark it with")

--[[ **Neither half of the signal is enough alone.** The glow is shown for
     reasons of the client's own besides hovering, and `mouseover` exists
     whenever the cursor is over anything at all -- a mob, a party frame, an item
     in a bag. ]]--
Stub.mouseover = nil
adoptedEnemy.original.glow:Show()
check(not plates:IsMouseover(adoptedEnemy),
        "a glowing plate with no mouseover unit is not hovered")

Stub.mouseover = true
adoptedEnemy.original.glow:Hide()
check(not plates:IsMouseover(adoptedEnemy),
        "and a mouseover unit with no glow is not this plate")

Stub.mouseover = true
adoptedEnemy.original.glow:Show()
check(plates:IsMouseover(adoptedEnemy), "the two together are the signal")

--[[ And it is drawn, which is the half that was missing -- this module already
     used the same pair to work out which unit a plate belongs to and simply
     never drew anything with it. ]]--
plates:Refresh(adoptedEnemy)
check(adoptedEnemy.mouseoverGlow:IsShown(), "so the hovered plate is marked")

adoptedEnemy.original.glow:Hide()
plates:Refresh(adoptedEnemy)
check(not adoptedEnemy.mouseoverGlow:IsShown(),
        "and unmarked the moment the cursor leaves")

--[[ Switched off, nothing is drawn however the cursor moves. ]]--
cfg.mouseoverGlow = false
Stub.mouseover = true
adoptedEnemy.original.glow:Show()
plates:Refresh(adoptedEnemy)
check(not adoptedEnemy.mouseoverGlow:IsShown(), "switched off it stays unmarked")

cfg.mouseoverGlow = true

--[==[ **Both can be true at once** -- you can hover a mob you have targeted --
     which is why the hover is its own frame rather than a colour on the border.
     One surface would have to pick a winner. ]==]
check(adoptedEnemy.targetGlow ~= adoptedEnemy.mouseoverGlow,
        "the target glow and the hover glow are separate frames")
check(adoptedEnemy.mouseoverGlow ~= adoptedEnemy.healthBorder,
        "and neither of them is the border")

-- ---------------------------------------------------------------------------
-- and neither is drawn round a bar that is not there
-- ---------------------------------------------------------------------------

--[==[ **Reported on critters: the plate reads as vanishing on hover and leaves a
     glowing outline behind.**

     Both glows are anchored to `plate.health`, and a hidden frame still resolves
     its anchors -- so a glow drawn round a hidden bar is a rectangle of light
     round nothing.

     **The option list already knew this.** Its own note says *taking the bar
     away left the target glow behind, so the answer to "hide the health bar" was
     a plate with no bar and a glow where the bar had been*. That was written
     when the five redundant switches were removed, and the switches were the
     only thing that got fixed: neither glow ever asked. A **mouseover** glow was
     then added later with the same omission, which is the one somebody
     hovering a rabbit actually meets. ]==]
GLOBAL_critterWas = adoptedEnemy.creatureType
cfg.hideCritterHealth = true
adoptedEnemy.creatureType = "Critter"

Stub.mouseover = true
adoptedEnemy.original.glow:Show()
adoptedEnemy.istarget = true

plates:Refresh(adoptedEnemy)

check(not adoptedEnemy.health:IsShown(), "a critter's health bar is hidden")
check(adoptedEnemy.healthHidden, "and the plate says so")

check(not adoptedEnemy.mouseoverGlow:IsShown(),
        "so hovering it draws no glow round the space where the bar was")
check(not adoptedEnemy.targetGlow:IsShown(),
        "and neither does targeting it")

--[==[ **A totem is the same case**, reached the other way: its bar is replaced
     by an icon rather than switched off by preference, and a glow round the
     absent bar is no better there. ]==]
adoptedEnemy.creatureType = "Totem"
cfg.hideTotemHealth = true
plates:Refresh(adoptedEnemy)

check(not adoptedEnemy.mouseoverGlow:IsShown(), "a totem is the same")

--[[ **And an ordinary mob is untouched**, which is the half that must not
     change: the glows are the feature, and a fix that quietly switched them off
     would be worse than the outline. ]]--
adoptedEnemy.creatureType = "Humanoid"
cfg.hideCritterHealth = false
plates:Refresh(adoptedEnemy)

check(adoptedEnemy.health:IsShown(), "an ordinary mob keeps its bar")
check(not adoptedEnemy.healthHidden, "and the plate says that too")
check(adoptedEnemy.mouseoverGlow:IsShown(), "and hovering it still glows")
check(adoptedEnemy.targetGlow:IsShown(), "and so does targeting it")

adoptedEnemy.istarget = nil
adoptedEnemy.original.glow:Hide()
Stub.mouseover = nil
adoptedEnemy.creatureType = GLOBAL_critterWas
cfg.hideCritterHealth = true
plates:Refresh(adoptedEnemy)

-- ---------------------------------------------------------------------------
-- a glow, rather than a second border
-- ---------------------------------------------------------------------------

--[==[ **What was called a glow was the client's tooltip edge drawn again,
     further out.**

     That art puts its one line at the *outer* boundary of the band it is given,
     so a second copy of it five pixels out is not a glow -- it is a second
     outline with a gap behind it, and the gap is what gave it away. A targeted
     plate wore two.

     `textures\\glow` runs the ramp the other way: solid where it meets the bar
     and gone by the outer boundary, so there is no edge anywhere in it and
     nothing for a gap to open behind. ]==]
context = "plate glow: "

plates:Refresh(adoptedEnemy)

eq(adoptedEnemy.targetGlow.backdrop.edgeFile, OB.glowEdgeFile,
        "the target glow is drawn in the glow art")
eq(adoptedEnemy.mouseoverGlow.backdrop.edgeFile, OB.glowEdgeFile,
        "and so is the hover glow")
check(adoptedEnemy.targetGlow.backdrop.edgeFile ~= OB.borderEdges[3].edgeFile,
        "which is not the border art either of them used to be")

--[==[ **The band and the edge size are one number.** Anchored `n` pixels out
     and asked for an edge of `n`, the glow spans exactly the gap it was given.
     Any other edge size leaves a hard stop partway out, or a band that never
     reaches the bar -- which is the gap again. ]==]
GLOBAL_glowTL = adoptedEnemy.targetGlow.points[1]
eq(adoptedEnemy.targetGlow.backdrop.edgeSize, -GLOBAL_glowTL[4],
        "sized to exactly the distance it is anchored at")

--[[ Tighter than the target's, so hovering the thing you already have targeted
     reads as two glows rather than as one brighter one. ]]--
check(adoptedEnemy.mouseoverGlow.backdrop.edgeSize
        < adoptedEnemy.targetGlow.backdrop.edgeSize,
        "and the hover glow sits inside the target's")

--[==[ **Both measured from the border**, so a heavier border does not swallow
     the glow that is supposed to surround it. ]==]
GLOBAL_thinGlow = adoptedEnemy.targetGlow.backdrop.edgeSize
cfg.borderThickness = 5
plates:Refresh(adoptedEnemy)
plates:Style(adoptedEnemy)
check(adoptedEnemy.targetGlow.backdrop.edgeSize > GLOBAL_thinGlow,
        "a thicker border pushes the glow out with it")

-- ---------------------------------------------------------------------------
-- and the border has a weight
-- ---------------------------------------------------------------------------

--[==[ **One number, not two.** The art is drawn at whatever size the band
     allows, so how far out the border sits and how thick its line comes out are
     the same question. Two sliders would have let them disagree, and a border
     three pixels out drawn at one pixel is the gap this pass exists to
     remove. ]==]
context = "plate border weight: "

GLOBAL_borderTL = adoptedEnemy.healthBorder.points[1]
eq(GLOBAL_borderTL[4], -5, "the border is hung at the thickness it is set to")
GLOBAL_thickEdge = adoptedEnemy.healthBorder.backdrop.edgeSize

cfg.borderThickness = 1
plates:Refresh(adoptedEnemy)
GLOBAL_borderTL = adoptedEnemy.healthBorder.points[1]
eq(GLOBAL_borderTL[4], -1, "and follows the setting down again")
check(adoptedEnemy.healthBorder.backdrop.edgeSize < GLOBAL_thickEdge,
        "with the art drawn lighter to match")

--[[ A slider's range is a statement about the panel, not about the value that
     reaches the drawing code. ]]--
cfg.borderThickness = 99
eq(plates:BorderThickness(), 6, "a value past the top of the slider is clamped")
cfg.borderThickness = 0
eq(plates:BorderThickness(), 1, "and one below the bottom")
cfg.borderThickness = nil
eq(plates:BorderThickness(), 2, "a profile with no answer takes the default")

cfg.borderThickness = 2
plates:Refresh(adoptedEnemy)
plates:Style(adoptedEnemy)


-- ---------------------------------------------------------------------------
-- and the guessed debuff list is not rebuilt every frame
-- ---------------------------------------------------------------------------

--[[ **`OB.AuraList` walks everything known about a name, builds a table for each
     one, and sorts the result.**

     It was called for every plate on every rendered frame. Ten nameplates in a
     dungeon is six hundred of those a second, and on 1.12 that is not CPU -- it
     is garbage, and it is paid for later as the collection pause people call
     lag. The exact aura scan sitting beside it has been throttled since it was
     written; this had the same shape and none of the throttle.

     **Counted rather than compared.** Asserting that two passes produce the same
     list proves nothing -- rebuilding it produces the same list too. The
     question is whether the work happened, so the work is counted. ]]--
GLOBAL_auraCalls = 0
GLOBAL_realAuraList = OB.AuraList
OB.AuraList = function(name, limit)
    GLOBAL_auraCalls = GLOBAL_auraCalls + 1
    return GLOBAL_realAuraList(name, limit)
end

cfg.debuffs = true
cfg.guessDebuffs = true

plates:ResetPlateIdentity(adoptedEnemy)
Stub.SetClock(20000)

plates:Refresh(adoptedEnemy)
eq(GLOBAL_auraCalls, 1, "the first frame builds the guessed list")

--[[ Sixty frames inside a tenth of a second, which is what a dungeon actually
     looks like. Before the throttle this was sixty rebuilds. ]]--
for GLOBAL_i = 1, 60 do
    Stub.SetClock(20000 + (GLOBAL_i * 0.001))
    plates:Refresh(adoptedEnemy)
end

eq(GLOBAL_auraCalls, 1, "and sixty more frames build it no further times")

--[[ It is a throttle rather than a freeze: a debuff applied a quarter of a
     second ago is not late, and the list has to catch up. ]]--
Stub.SetClock(20001)
plates:Refresh(adoptedEnemy)
eq(GLOBAL_auraCalls, 2, "once the interval is up it is built again")

--[[ **And a plate that became a different mob rebuilds at once**, whatever the
     clock says -- showing the previous mob's debuffs for a quarter of a second
     is showing the wrong thing about the wrong creature. ]]--
adoptedEnemy.original.name:SetText("Someone Else Entirely")
plates:Refresh(adoptedEnemy)
eq(GLOBAL_auraCalls, 3, "a plate that changed mob rebuilds immediately")

OB.AuraList = GLOBAL_realAuraList

-- ---------------------------------------------------------------------------
-- how long is left on each of them
-- ---------------------------------------------------------------------------

--[==[ **A debuff icon with no number on it answers half the question.**

     Which debuffs are on a mob is worth knowing; whether the one you refreshed
     is about to fall off is the reason anybody looks. The target frame grew
     these first and the plates were asked for next, and both read the same
     store -- `OB.auras`, keyed by the unit's *name*, which is the only key a
     nameplate has at all.

     Written here rather than assumed, because the feature shipped with no test
     of any kind: the code was correct and nothing said so. ]==]
cfg.debuffs = true
cfg.debuffTimers = true
cfg.guessDebuffs = true

adoptedEnemy.original.name:SetText("Gordok Enforcer")
plates:ResetPlateIdentity(adoptedEnemy)

Stub.SetClock(30000)
OB.auras = {}
OB.AddAura("Gordok Enforcer", "Rend", "Interface\\Icons\\Ability_Gouge")

Stub.SetClock(30005)
plates:Refresh(adoptedEnemy)

check(adoptedEnemy.debuffs[1]:IsShown(), "the debuff is drawn on the plate")
GLOBAL_plateTimer = adoptedEnemy.debuffTimers and adoptedEnemy.debuffTimers[1]
check(GLOBAL_plateTimer ~= nil, "and has a timer of its own")
check(GLOBAL_plateTimer:IsShown(), "which is shown beside it")

--[[ Rend runs twenty-one seconds and five have gone, so sixteen are left. The
     number rather than "some text": a timer that counts the wrong thing is
     worse than none, and only the value can tell those apart. ]]--
eq(GLOBAL_plateTimer:GetText(), "16s", "counting down what is actually left",
        tostring(GLOBAL_plateTimer:GetText()))

Stub.SetClock(30015)
plates:Refresh(adoptedEnemy)
eq(GLOBAL_plateTimer:GetText(), "6s", "and it counts")

--[==[ **A spell with no known duration shows nothing rather than nought.**

     The durations are a table this addon carries; a private server's own spell
     is not in it. A timer reading zero on a debuff that is plainly still
     ticking is read as fact and acted on. ]==]
OB.auras = {}
OB.AddAura("Gordok Enforcer", "Mystery Poison", "Interface\\Icons\\Ability_Gouge")
plates:ResetPlateIdentity(adoptedEnemy)
plates:Refresh(adoptedEnemy)

check(adoptedEnemy.debuffs[1]:IsShown(), "an unknown debuff is still drawn")
check(not GLOBAL_plateTimer:IsShown(), "with no number under it")

--[[ Switched off, no numbers at all -- and the icons stay, because the two are
     separate settings and somebody may want one without the other. ]]--
OB.auras = {}
OB.AddAura("Gordok Enforcer", "Rend", "Interface\\Icons\\Ability_Gouge")
cfg.debuffTimers = false
plates:ResetPlateIdentity(adoptedEnemy)
plates:Refresh(adoptedEnemy)

check(adoptedEnemy.debuffs[1]:IsShown(), "with the timers off the icons remain")
check(not GLOBAL_plateTimer:IsShown(), "and the numbers are gone")

cfg.debuffTimers = true
OB.auras = {}

cfg.guessDebuffs = true
Stub.mouseover = nil
adoptedEnemy.original.glow:Hide()
plates:Refresh(adoptedEnemy)

--[[ The friendly plate is not the target and has no token, and it draws a cast
     bar all the same -- which is the point of keying by name. ]]--
OB.StartCast("Sylvie", "Renew", 1500)
plates:Refresh(adoptedFriend)
eq(adoptedFriend.cast.shown, true,
        "a plate that is not the target shows one too")

-- ---------------------------------------------------------------------------
-- and how long is left of the cast
-- ---------------------------------------------------------------------------

--[==[ **A bar three-quarters along says nothing about how long that leaves.**

     A tenth of a second and two seconds look identical on it, and they are
     opposite decisions: interrupt now, or step out of it. So the seconds go at
     the trailing end of the bar, where the spell name is not.

     Rendered by `OB.CastTimeText`, which is the cast bar's own reading of a
     number -- one decimal below ten, whole seconds above it. ]==]
eq(cfg.castTimer, true, "the countdown is on by default")
check(adoptedFriend.castTime ~= nil, "a plate has a string for it")

Stub.SetClock(52000)
OB.casting = {}
OB.StartCast("Sylvie", "Renew", 3000)

Stub.SetClock(52001)
plates:Refresh(adoptedFriend)

check(adoptedFriend.castTime:IsShown(), "which is shown while the cast runs")
eq(adoptedFriend.castTime:GetText(), "2.0", "counting the seconds left",
        tostring(adoptedFriend.castTime:GetText()))

Stub.SetClock(52002.4)
plates:Refresh(adoptedFriend)
eq(adoptedFriend.castTime:GetText(), "0.6", "to a tenth, which is the whole point")

--[==[ **Nothing rather than nought where the duration is unknown.**

     A combat-log cast with no duration is a real cast and the bar still shows
     it; what cannot be said is how long is left. A number counting down from a
     duration nobody knows is read as fact and acted on -- the same rule the
     debuff timers follow. ]==]
--[[ A spell this session has never seen a duration for: `StartCast` remembers
     one it has been told, so re-using a spell from above would be given the
     duration it was taught rather than none. ]]--
OB.casting = {}
OB.StartCast("Sylvie", "Rite Of The Unknown")
plates:Refresh(adoptedFriend)

eq(adoptedFriend.cast.shown, true, "an unknown-length cast still draws a bar")
check(not adoptedFriend.castTime:IsShown(), "with no number on it")

--[==[ **And it is not somebody else's cast.**

     The seconds come from this addon's own record, which is keyed by name; the
     spell may have come from the client's per-plate cast child, which is keyed
     by nothing at all. Taking the two together without checking they agree
     would count down whatever that name was last casting. ]==]
OB.casting = {}
if adoptedFriend.original.cast then adoptedFriend.original.cast:Hide() end

Stub.SetClock(52003)
OB.StartCast("Sylvie", "Lesser Heal", 4000)
plates:Refresh(adoptedFriend)
eq(adoptedFriend.castTime:GetText(), "4.0",
        "a record that agrees about the spell is the one read")

eq(plates:CastTimeLeft(adoptedFriend, "Renew", "Sylvie"), nil,
        "and one about a different spell is not read at all")

--[[ Switched off, no number, and the bar and name stay -- three settings, three
     answers. ]]--
cfg.castTimer = false
plates:Refresh(adoptedFriend)
eq(adoptedFriend.cast.shown, true, "with the countdown off the bar remains")
check(not adoptedFriend.castTime:IsShown(), "and only the number is gone")

cfg.castTimer = true

--[[ And it goes away with the bar rather than freezing under a plate that has
     stopped casting, which is what the spell name used to do. ]]--
OB.casting = {}
plates:Refresh(adoptedFriend)
check(not adoptedFriend.castTime:IsShown(), "a finished cast leaves no number behind")

OB.casting = {}
cfg.castbar = false

-- ---------------------------------------------------------------------------
-- and the text is not rebuilt every frame
-- ---------------------------------------------------------------------------

--[[ **There are no nameplate events.** Everything here is found by polling, so
     a plate's whole refresh runs on every rendered frame for as long as it is
     on screen -- and every line of text it writes was a freshly built string.
     The name went through the shortener, the level was a concatenation, and the
     health text was formatted from scratch. At ten plates and sixty frames that
     is thousands of throwaway strings a second, which on 1.12 is not a CPU cost
     but a garbage collection pause. It was the single worst thing in the game's
     own profiler.

     They are built when their inputs change and reused otherwise. Same pixels,
     a fraction of the garbage.

     **The danger of caching here is specific and known**: nameplate frames are
     recycled, so the same frame comes back as a different mob. A cache that
     outlived the identity would leave the previous mob's name on screen. That
     is what these checks are actually for. ]]--
cfg.showName = true
cfg.showLevel = true
cfg.healthText = "percent"

plates:Refresh(adoptedEnemy)
GLOBAL_firstName = adoptedEnemy.name:GetText()
GLOBAL_firstLevel = adoptedEnemy.level:GetText()

check(GLOBAL_firstName ~= nil and GLOBAL_firstName ~= "",
        "a plate writes its name", tostring(GLOBAL_firstName))

--[[ Refreshing again with nothing changed must reuse rather than rebuild. The
     observable half is that the text is identical; the point is that no string
     was made to discover that. ]]--
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.name:GetText(), GLOBAL_firstName, "and says the same thing next frame")
eq(adoptedEnemy.level:GetText(), GLOBAL_firstLevel, "the level too")

check(adoptedEnemy.shortNameValue ~= nil, "with the shortened name kept")
check(adoptedEnemy.levelTextValue ~= nil, "and the level text")

--[[ **The cache keys on the text it was built from, not on having been set.**

     That is what makes it self-invalidating, and it is the difference between a
     cache and a bug. A nameplate frame is recycled: the same frame comes back
     as a different mob, and if the name underneath changes the plate has to
     follow it.

     Checked here *without* resetting the identity first, deliberately. The
     reset clears these fields too, and it would mask a comparison that never
     fires -- a cache that only rebuilt when empty would pass a test that
     emptied it. The real hide-to-show path does reset; this is the path where
     nothing helps but the comparison. ]]--
adoptedEnemy.original.name:SetText("Bloodscalp Scout")
adoptedEnemy.original.level:SetText("12")

plates:Refresh(adoptedEnemy)

check(adoptedEnemy.name:GetText() ~= GLOBAL_firstName,
        "a plate whose name changed under it follows the new name",
        tostring(adoptedEnemy.name:GetText()))
check(string.find(adoptedEnemy.level:GetText() or "", "12", 1, true) ~= nil,
        "and the new level", tostring(adoptedEnemy.level:GetText()))

--[[ And the reset path clears them as well, so a recycled plate cannot show the
     previous mob's text even for the one frame before the comparison runs. ]]--
plates:ResetPlateIdentity(adoptedEnemy)
eq(adoptedEnemy.shortNameValue, nil, "resetting a plate's identity drops its cached name")
eq(adoptedEnemy.levelTextValue, nil, "and its cached level")
eq(adoptedEnemy.healthTextValue, nil, "and its cached health text")

plates:Refresh(adoptedEnemy)

--[[ The health text follows its own inputs rather than the identity, because
     health changes constantly while the mob does not. Same rule though: built
     when the displayed value would differ, reused when it would not. ]]--
adoptedEnemy.original.health:SetValue(50)
plates:Refresh(adoptedEnemy)
GLOBAL_halfText = adoptedEnemy.text:GetText()

plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.text:GetText(), GLOBAL_halfText,
        "an unchanged health value keeps the same text")

adoptedEnemy.original.health:SetValue(20)
plates:Refresh(adoptedEnemy)
check(adoptedEnemy.text:GetText() ~= GLOBAL_halfText,
        "and a changed one is rebuilt", tostring(adoptedEnemy.text:GetText()))

--[[ Switching the mode has to invalidate too, or the setting would appear to do
     nothing until the mob's health happened to move.

     Checked on the cache rather than on the text, because a stock 1.12 plate
     supplies a percentage and nothing else: with no real current/max to read,
     every mode honestly degrades to the same percentage, and asserting the
     *text* changed would be asserting that this module invents numbers it does
     not have. What matters is that the mode was noticed. ]]--
cfg.healthText = "deficit"
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.healthTextMode, "deficit", "changing the mode invalidates the cache")

cfg.healthText = "percent"
plates:Refresh(adoptedEnemy)
eq(adoptedEnemy.healthTextMode, "percent", "and changing it back does too")
check(string.find(adoptedEnemy.text:GetText() or "", "%%") ~= nil,
        "with a percentage on screen either way",
        tostring(adoptedEnemy.text:GetText()))

--[[ **A plate that has not changed is not written to.**

     Every plate is refreshed on every rendered frame -- the polling model this
     module is a port of, and the reason the addon it came from is the one
     people turn off when their frames drop. Twenty plates at a hundred and
     fifty frames a second is three thousand refreshes, each setting the same
     text and the same colour on regions that already held them.

     `SetText` re-measures the string and marks the frame for redraw. Handing it
     what it already has is work with no picture attached.

     **Counted at the region**, because the text ends up identical either way --
     comparing what the plate says would pass whether or not the write happened.

     A throttle was tried first and reverted: rebuilding ten times a second
     rather than every frame degraded the mouseover mark, the threat colour, the
     combo points and a recycled plate following its new mob. Twelve tests said
     so. Skipping redundant writes costs those nothing. ]]--
GLOBAL_writes = 0
GLOBAL_realSetText = adoptedEnemy.name.SetText

adoptedEnemy.name.SetText = function(self, text)
    GLOBAL_writes = GLOBAL_writes + 1
    return GLOBAL_realSetText(self, text)
end

plates:Refresh(adoptedEnemy)
GLOBAL_writes = 0

--[[ Sixty frames, which is a second of standing still looking at it. ]]--
for GLOBAL_i = 1, 60 do
    plates:Refresh(adoptedEnemy)
end

eq(GLOBAL_writes, 0, "a second of frames writes the name no further times")

--[[ It is a skip, not a freeze: a plate recycled onto a different mob has to
     follow it, and that is the case this whole module exists to get right. ]]--
adoptedEnemy.original.name:SetText("Somebody Different")
plates:Refresh(adoptedEnemy)

check(GLOBAL_writes > 0, "and a plate that changed mob is written again")
check(string.find(adoptedEnemy.name:GetText() or "", "Different") ~= nil,
        "with the new name on it -- abbreviated, which is the shortener working",
        tostring(adoptedEnemy.name:GetText()))

adoptedEnemy.name.SetText = GLOBAL_realSetText

OB.profile.modulesEnabled.nameplates = true
OB.BindSlots()

end

nameplateTests()

-- 45. unit frames
--
-- These are Blizzard's frames, restyled. Not replacements -- they already know
-- which unit they show, already update on the right events, and already handle
-- ghosts, tapped mobs and pet happiness. What they do badly is look like 2004
-- and refuse to say how much health anybody has, and both of those are texture
-- and font work on frames that are already correct.
-- ---------------------------------------------------------------------------

function unitFrameTests()

context = "unit frames: "

EquadisClassicOverhaulDB = nil
OB = boot("ROGUE", 3)

local frames = OB.modules.unitframes
check(frames ~= nil, "the unit frame module registers")
eq(OB.ModuleEnabled("unitframes"), true, "and ships on")

OB.profile.modulesEnabled.unitframes = true
OB.BindSlots()

local cfg = OB.profile.modules.unitframes

-- ---------------------------------------------------------------------------
-- what colour a unit is
-- ---------------------------------------------------------------------------

--[[ **An NPC has a class and it is meaningless.** The server gives every
     creature one -- a wolf is a warrior -- so NPCs get their reaction instead,
     and the class option for them is a separate switch that ships off. ]]--
Stub.player.hasTarget = true
Stub.target = { name = "Sylvie", isPlayer = true, class = "PRIEST" }
Stub.reaction = 5

local color = frames:UnitColor("target")
local pr, pg, pb = OB.ClassColor("PRIEST")
eq(color[1], pr, "a player takes their class colour")
eq(color[2], pg, "all three channels")
eq(color[3], pb, "of it")

Stub.target = { name = "Wolf", isPlayer = false, class = "WARRIOR" }

color = frames:UnitColor("target")
eq(color[1], cfg.friendlyColor[1], "an NPC takes its reaction instead")

--[==[ **A mob somebody else tagged is grey before anything else is considered.**

     You cannot loot it, and that is the fact worth showing -- it beats reaction,
     it beats the NPC class option, it beats everything. UFI's target update
     gives tap ownership first priority for the same reason.

     **Neither call was in the harness**, so `type(UnitIsTapped) == "function"`
     read false and this whole branch was skipped by every test that has ever
     run: a setting somebody can see and change, with nothing behind it. Two
     calls rather than one because the question has two halves -- tagged at all,
     and tagged by *you*. ]==]
Stub.tapped["target"] = { tapped = true, byPlayer = false }

color = frames:UnitColor("target")
eq(color[1], cfg.tappedColor[1], "a mob tagged by somebody else goes grey",
        tostring(color[1]))

--[[ Tagged by you is your kill, so it keeps its ordinary colour: the grey means
     "not yours", not "already fighting". ]]--
Stub.tapped["target"] = { tapped = true, byPlayer = true }

color = frames:UnitColor("target")
eq(color[1], cfg.friendlyColor[1], "one you tagged yourself keeps its own")

--[==[ **And a player is never greyed by it.** Players are not tagged, and the
     calls answer for them anyway on some builds -- so the guard is on
     `UnitIsPlayer` rather than on the tap, or a party member somebody else was
     fighting would go grey in your frames. ]==]
Stub.target = { name = "Sylvie", isPlayer = true, class = "PRIEST" }
Stub.tapped["target"] = { tapped = true, byPlayer = false }

color = frames:UnitColor("target")
eq(color[1], pr, "a player is never greyed as tapped")

Stub.tapped["target"] = nil
Stub.target = { name = "Wolf", isPlayer = false, class = "WARRIOR" }

--[==[ **And the client does not get to repaint it a tick later.**

     Reported as the enemy target frame flashing between green and red.
     `HealthBar_OnValueChanged` is the *client's* function and paints every
     non-player bar (0, 1, 0); this module replaces it and used to hand every
     bar that was not the player's straight back to the original. That is safe
     only while `lockColor` is set on the bar -- and that flag is written by
     `StyleBar` only when a colour was resolved, is absent for a unit that does
     not exist, and is restored to the client's value whenever this module stops
     owning the frame. In any window where it is off, the next health tick
     repainted the target green.

     So the wrapper colours a bar this module owns rather than delegating, and
     reasserts the flag while it is there. Asserted on the *bar* rather than on
     `UnitColor`, because `UnitColor` was always right -- what was wrong was who
     wrote last. ]==]
Stub.reaction = 2
Stub.target = { name = "Plague Ghoul", isPlayer = false, class = "WARRIOR" }
cfg.npcClassColor = false

GLOBAL_tHealth = getglobal("TargetFrameHealthBar")
GLOBAL_tHealth.lockColor = nil
GLOBAL_tHealth:SetStatusBarColor(0, 1, 0)

frames:ColorUpdate(GLOBAL_tHealth, 50, false)

near(select(1, GLOBAL_tHealth:GetStatusBarColor()), cfg.hostileColor[1], 0.001,
        "a hostile target keeps this addon's colour through a value change")
check(select(2, GLOBAL_tHealth:GetStatusBarColor()) < 0.9,
        "rather than the client's green")
check(GLOBAL_tHealth.lockColor == true,
        "and the flag that keeps the client off is put back")


-- ---------------------------------------------------------------------------
-- the client's own cast bar
-- ---------------------------------------------------------------------------

--[==[ **Two cast bars saying the same thing, and the worse one cannot be
     moved.**

     1.12 draws one for you and nothing for anybody else, prints the literal
     word "Channeling" instead of the spell on a channel, and puts no clock on
     either. This module draws one somebody has placed, so the client's is left
     underneath it saying the same thing in the wrong place.

     **Hidden rather than unregistered.** Taking its events away would need the
     list put back exactly to restore it; a frame that is merely hidden is one
     `Show` from being the client's again.

     And the half that is usually got wrong: `CastingBarFrame_OnEvent` shows the
     bar on **every** cast, so hiding it once lasts until the next spell. The
     guard is on its `OnShow`, which is why the second assertion here matters
     more than the first. ]==]
check(not CastingBarFrame:IsShown(),
        "the client's cast bar is hidden whenever this module is on")

frames:Apply()
check(not CastingBarFrame:IsShown(), "and is down after a styling pass")

Stub.CastBarShows()
check(not CastingBarFrame:IsShown(),
        "and stays down when the client shows it for the next cast")

--[==[ **And there is no switch to turn it back on.**

     It was one, on the reasoning that somebody might want the client's cast bar.
     They might -- and the way to have it is the **Blizzard** border and the
     client's own bar texture, which this addon offers, on a bar that is in the
     right place and answers to the same settings as everything else. Two cast
     bars on one screen was never the third option anybody wanted.

     An old profile carrying `hideBlizzardCast = false` is **ignored rather than
     obeyed**: honouring it would leave somebody with two bars and no row left to
     explain why. ]==]
cfg.hideBlizzardCast = false
Stub.CastBarShows()

check(not CastingBarFrame:IsShown(),
        "a retired hideBlizzardCast = false is ignored, not obeyed")

cfg.hideBlizzardCast = nil

-- ---------------------------------------------------------------------------
-- and the bars are on screen while the layout is being arranged
-- ---------------------------------------------------------------------------

--[==[ **A cast bar exists only during a cast**, and it is registered as
     movable -- so arranging one meant finding something to cast at and doing the
     whole layout inside three seconds. That is a race rather than an
     arrangement.

     Third time this shape has come up and each was written down: the raid frames
     are *shown while unlocked even with nobody in the group, or a raid frame
     layout could only be arranged inside a raid*, and the PvP countdown reached
     the same answer a release ago.

     A sample name and a part-filled bar rather than an empty rectangle, because
     an empty one says nothing about how wide the thing is or what the text on it
     looks like -- which is most of what is being arranged. ]==]
GLOBAL_playerCast = frames:CastBar("player")

OB.SetEditMode(true)

check(GLOBAL_playerCast:IsShown(),
        "unlocked, the cast bar is on screen with nothing casting")
check(GLOBAL_playerCast.label:GetText() ~= "",
        "with a sample name on it",
        tostring(GLOBAL_playerCast.label:GetText()))
check(GLOBAL_playerCast:GetValue() > 0, "and a part-filled bar")

OB.SetEditMode(false)

check(not GLOBAL_playerCast:IsShown(),
        "and locking again puts it away, because nothing is casting")

--[==[ **A border of its own**, asked for, and the reason the switch above could
     go: with the Blizzard edge and the client's own bar texture this looks like
     the bar it replaced, in the right place and answering to the same settings
     as everything else. ]==]
frames:StyleCastBar("player")

check(GLOBAL_playerCast.border ~= nil, "the cast bar has a border frame")
check(GLOBAL_playerCast.border:IsShown(), "drawn by default")

cfg.castBorder = 1
frames:StyleCastBar("player")
check(not GLOBAL_playerCast.border:IsShown(), "and None really means none")

cfg.castBorder = 3
frames:StyleCastBar("player")
check(GLOBAL_playerCast.border:IsShown(), "and back when one is chosen")

--[==[ **Hung where the ink is, which is what `outset` is recorded for.**

     A backdrop's edge band is drawn *inward* from the frame's boundary and the
     opaque art hugs the outer end of that band, so a border frame has to be hung
     outward by however far the ink reaches back in. `OB.borderEdges` measures
     that per style -- it was read off the files -- and this used a flat one
     pixel instead.

     With the tooltip edge narrowed for a fourteen pixel bar that distance is
     nearly three pixels, so the line landed about two pixels *inside* the bar:
     the border sitting on the fill rather than around it, and the fill running
     out from under it. Reported as the texture leaking outside the border, which
     is what it looks like from the front. ]==]
GLOBAL_castEdge = OB.BorderEdge(3, GLOBAL_playerCast:GetWidth(),
        GLOBAL_playerCast:GetHeight())

check(GLOBAL_castEdge ~= nil, "the narrowed edge resolves")
check((GLOBAL_castEdge.outset or 0) > 1,
        "and this one's ink reaches further in than a pixel",
        tostring(GLOBAL_castEdge.outset))

GLOBAL_castPoint, GLOBAL_castRel, GLOBAL_c3, GLOBAL_castX, GLOBAL_castY =
        GLOBAL_playerCast.border:GetPoint(1)

eq(GLOBAL_castX, -math.floor(GLOBAL_castEdge.outset),
        "the border hangs out by the edge's own measurement",
        tostring(GLOBAL_castX))
eq(GLOBAL_castY, math.floor(GLOBAL_castEdge.outset),
        "in both directions", tostring(GLOBAL_castY))

--[==[ **And only the edge reaches the client.** `insets` say where a background
     stops and there is no background here; `outset` is this addon's own
     measurement rather than a key `SetBackdrop` knows. ]==]
GLOBAL_castBackdrop = GLOBAL_playerCast.border:GetBackdrop()

eq(GLOBAL_castBackdrop.bgFile, nil, "the backdrop carries no background")
eq(GLOBAL_castBackdrop.outset, nil,
        "nor a field SetBackdrop has no use for")
eq(GLOBAL_castBackdrop.edgeSize, GLOBAL_castEdge.edgeSize,
        "and the edge is the narrowed one")

--[==[ **The level is re-asserted on every pass**, not only at creation: a frame
     given an explicit level stops tracking its parent's, so a bar raised
     afterwards would leave its border under the fill it sits over. ]==]
GLOBAL_playerCast:SetFrameLevel(40)
frames:StyleCastBar("player")

check(GLOBAL_playerCast.border:GetFrameLevel() > GLOBAL_playerCast:GetFrameLevel(),
        "the border stays above the bar after the bar is raised",
        tostring(GLOBAL_playerCast.border:GetFrameLevel()))

cfg.hideBlizzardCast = true
frames:Apply()

-- ---------------------------------------------------------------------------
-- how long is left on the target's debuffs
-- ---------------------------------------------------------------------------

--[==[ **The other half of the same feature as the nameplates'.**

     A debuff on the target frame is an icon and nothing else in 1.12, so the
     one thing worth knowing about it -- whether it is about to fall off -- is
     the one thing it does not say.

     Two things make it awkward, and both were got wrong once each:

     The aura store is keyed by the unit's **name**. `OB.AddAura` records what
     the combat log said, and the log names a caster and a target and never
     gives a token -- so a lookup made with "target" asks about a unit called
     "target" and finds nothing, silently, which is indistinguishable from a
     spell with no known duration.

     And the *name* of a debuff on somebody else is only readable through the
     tooltip. `SetUnitDebuff` and `SetUnitBuff` are separate calls over
     separately numbered lists, which is why the slot table says which each row
     is rather than running one loop over both. ]==]
Stub.target = { name = "Gordok Enforcer", isPlayer = false, class = "WARRIOR" }
Stub.player.hasTarget = true

cfg.auraTimers = true

--[[ The client's own list: what the tooltip will say for debuff one. ]]--
Stub.SetUnitAuras("target", {}, { "Rend" })
getglobal("TargetFrameDebuff1"):Show()

Stub.SetClock(41000)
OB.auras = {}
OB.AddAura("Gordok Enforcer", "Rend")

Stub.SetClock(41004)
eq(frames:ApplyAuraTimers("target"), 1, "one debuff on the target carries a timer")

GLOBAL_targetTimer = getglobal("TargetFrameDebuff1").ecoAuraTimer
check(GLOBAL_targetTimer ~= nil, "the debuff icon has a timer string")
eq(GLOBAL_targetTimer:GetText(), "17s", "counting down what is left of the debuff",
        tostring(GLOBAL_targetTimer:GetText()))

--[==[ **And it still works when the tooltip says nothing at all**, which is the
     client this addon is actually running on.

     `SetUnitDebuff` answers nothing there. Why is still unknown and recorded as
     unknown in NOTICE -- BetterCharacterStats builds its scanning tooltip
     character for character the same way and its scanning works. It does not
     need to be known: an aura nobody can name has no duration, and **the icon is
     a second way of asking**.

     The nameplates were given that fallback in v0.99.217 and it is what actually
     restored their timers. **This frame reads the same tooltip on the same
     client and never got it**, so its debuff timers went on having no name and
     therefore no number - reported twice as the timers missing.

     Driven by silencing the tooltip rather than by calling the fallback, because
     "the fallback works" was never the question. ]==]
GLOBAL_realSetUnitDebuff = OB.ScanTooltip().SetUnitDebuff
OB.ScanTooltip().SetUnitDebuff = function() return true end

GLOBAL_targetTimer:SetText("")
GLOBAL_targetTimer:Hide()

--[[ The icon the client reports for that debuff, which is the only thing left
     to recognise it by. ]]--
Stub.debuffs["target"] = {
    { texture = OB.auraIcons and OB.auraIcons["Rend"] or "Interface/Icons/Rend",
      count = 1, dtype = "Physical" },
}
OB.NoteAura("Gordok Enforcer", "Rend", Stub.debuffs["target"][1].texture)

eq(frames:ApplyAuraTimers("target"), 1,
        "a silent tooltip still gets a timer, from the icon")
eq(GLOBAL_targetTimer:GetText(), "17s", "with the same number on it",
        tostring(GLOBAL_targetTimer:GetText()))

--[==[ **An empty tooltip line is not a name either.** It is truthy, so left as
     it is it records an aura called "" against the unit and then finds no
     duration for it -- which looks exactly like the tooltip having worked and
     the spell having no timer. ]==]
OB.ScanTooltip().SetUnitDebuff = function(tip)
    tip:ClearLines()
    tip:Line(1):SetText("")
    return true
end

eq(frames:ApplyAuraTimers("target"), 1,
        "and an empty line falls through to the icon rather than being a name")

OB.ScanTooltip().SetUnitDebuff = GLOBAL_realSetUnitDebuff
Stub.debuffs["target"] = nil

--[==[ **A scan notices an aura; it does not restart it.**

     `AddAura` stamps the current time, which is right for a combat log line --
     that line *is* the moment it landed. The debuff scanner walks the target's
     auras every second, and stamping on each pass restarted the clock every
     time, so a timer built on it sat at the full duration and never moved.

     Reported twice, as missing timers on nameplates and on the target frame:
     two readers of the same store, both reading a number that had just been set
     to now.

     And a debuff put on a mob by somebody else never appears in this player's
     log at all, so the store had never heard of it -- which is the other half of
     the same report. What the scan reads is now noted as first-seen, which is a
     weaker fact than "it landed now" and the only one a 1.12 client has. ]==]
Stub.SetClock(41100)
OB.auras = {}
OB.NoteAura("Gordok Enforcer", "Rend")

Stub.SetClock(41105)
OB.NoteAura("Gordok Enforcer", "Rend")

eq(OB.AuraTimeText("Gordok Enforcer", "Rend"), "16s",
        "a second sighting does not restart the clock",
        tostring(OB.AuraTimeText("Gordok Enforcer", "Rend")))

--[[ And a log line still does start it, because that one really is the moment
     it landed. ]]--
OB.AddAura("Gordok Enforcer", "Rend")
eq(OB.AuraTimeText("Gordok Enforcer", "Rend"), "21s",
        "while a fresh application does")

--[==[ **And the scanner itself, which is the one that was still re-stamping.**

     Everything above tests `OB.NoteAura`. The scan that walks the target's
     debuffs every second is `auras:ScanTarget`, and nothing had ever driven it
     here -- so it went on calling `AddAura`, stamping every debuff with the
     current time on every pass, long after both readers were moved onto
     `NoteAura`. The number was redrawn correctly four times a second and the
     value behind it was reset to full just as often, which reads as a timer that
     does not count down.

     Driven rather than reasoned about: the fix is one word, and a test that
     asserts the word rather than the behaviour would not have caught the bug in
     the first place. ]==]
Stub.SetClock(41200)
OB.auras = {}
OB.auraLengths = {}

GLOBAL_auras = OB.auraWatch

--[[ Both halves of what the client gives a scan: `UnitDebuff` answers a texture
     and no name, and the name comes out of the tooltip for that slot. ]]--
Stub.SetUnitAuras("target", {}, { "Rend" })
Stub.debuffs["target"] = { { texture = "Interface" .. string.char(92)
        .. "Icons" .. string.char(92) .. "Ability_Gouge" } }

eq(GLOBAL_auras:ScanTarget(), 1, "the scan finds the debuff on the target")
eq(OB.AuraTimeText("Gordok Enforcer", "Rend"), "21s", "and starts its clock")

Stub.SetClock(41209)
eq(GLOBAL_auras:ScanTarget(), 1, "it is still there nine seconds later")

eq(OB.AuraTimeText("Gordok Enforcer", "Rend"), "12s",
        "and the second pass did not put the clock back",
        tostring(OB.AuraTimeText("Gordok Enforcer", "Rend")))

--[==[ **The frame draws them on a tick, which it never used to.**

     `ApplyAuraTimers` was reachable from `Apply` and from nowhere else -- a full
     restyle, which happens at login and when a setting changes. So the number
     was written once and never again: it could not count down, and a debuff
     landing after the last restyle never got one at all.

     The nameplates have always had this tick. This frame did not, and the two
     halves together are what "unit frame debuffs are missing timers" was.

     A quarter second, matching the nameplates, because the text is whole
     seconds and the tooltip scan behind it is not free. ]==]
frames.nextAuraTimers = nil
frames:OnUpdate(GetTime())

check(frames.nextAuraTimers ~= nil,
        "the ordinary tick reaches the aura timers at all")

near(frames.nextAuraTimers - GetTime(), 0.25, 0.001,
        "and books the next pass a quarter second out",
        tostring(frames.nextAuraTimers and (frames.nextAuraTimers - GetTime())))

--[[ Throttled, or every frame pays for a tooltip scan per visible aura to
     redraw the number it already had. ]]--
GLOBAL_bookedAt = frames.nextAuraTimers
frames:OnUpdate(GetTime())
eq(frames.nextAuraTimers, GLOBAL_bookedAt,
        "and a second call in the same instant does not run it again")

--[==[ **Some debuffs are as long as the combo points that paid for them.**

     Reported as: Blind works, Cheap Shot works, Kidney Shot shows nothing --
     which is precisely the line between a fixed duration and a bought one, and
     the shipped table says so:

         ['Blind']       = { [0] = 10.0 }
         ['Cheap Shot']  = { [0] =  4.0 }
         ['Kidney Shot'] = { [1] =  0,   [2] = 1.0 }

     Kidney Shot has no `[0]` because it has no fixed length. Those are its two
     ranks' *base* durations and the rest is a second a point, so the reader took
     the longest number it could find -- one second -- and the timer was gone
     while the stun plainly was not. ]==]
OB.auras = {}
OB.auraLengths = {}
Stub.SetClock(42000)

--[[ Three points on the bar, then a finisher: the points are spent before the
     debuff lands, so the count is caught on the way down. ]]--
Stub.player.combo = 3
Stub.FireEvent("PLAYER_COMBO_POINTS")

Stub.player.combo = 0
Stub.FireEvent("PLAYER_COMBO_POINTS")

OB.AddAura("Gordok Enforcer", "Kidney Shot")

--[[ One second of base -- the higher rank's, because the rank is unknowable and
     guessing short shows a timer expiring on a stun still running -- and one a
     point on top. ]]--
eq(OB.AuraTimeText("Gordok Enforcer", "Kidney Shot"), "4s",
        "three points buy a four second stun",
        tostring(OB.AuraTimeText("Gordok Enforcer", "Kidney Shot")))

Stub.SetClock(42003)
eq(OB.AuraTimeText("Gordok Enforcer", "Kidney Shot"), "1s",
        "which counts down like any other")

Stub.SetClock(42005)
eq(OB.AuraTimeText("Gordok Enforcer", "Kidney Shot"), nil,
        "and is gone when it is gone")

--[[ Rupture is the other one: six seconds and two more a point. ]]--
OB.auras = {}
OB.auraLengths = {}
Stub.SetClock(42100)

Stub.player.combo = 5
Stub.FireEvent("PLAYER_COMBO_POINTS")
Stub.player.combo = 0
Stub.FireEvent("PLAYER_COMBO_POINTS")

OB.AddAura("Gordok Enforcer", "Rupture")
eq(OB.AuraTimeText("Gordok Enforcer", "Rupture"), "16s",
        "a five point Rupture runs sixteen seconds",
        tostring(OB.AuraTimeText("Gordok Enforcer", "Rupture")))

--[==[ **Somebody else's finisher is assumed to be a full one.**

     There is no way to know what a rogue outside your group spent, and the rule
     in this file is that a timer must never promise less than the aura has: a
     stun that is over according to a number still stunning you is worse than a
     number that runs a little long. ]==]
OB.auras = {}
OB.auraLengths = {}
Stub.SetClock(42500)

OB.AddAura("Gordok Enforcer", "Kidney Shot")
eq(OB.AuraTimeText("Gordok Enforcer", "Kidney Shot"), "6s",
        "with nothing spent recently it is read as a full bar",
        tostring(OB.AuraTimeText("Gordok Enforcer", "Kidney Shot")))

--[[ Points spent a long time ago are not credited to a finisher landing now --
     they were spent on something else, or the target was simply lost. ]]--
OB.auras = {}
OB.auraLengths = {}
Stub.SetClock(43000)

Stub.player.combo = 1
Stub.FireEvent("PLAYER_COMBO_POINTS")
Stub.player.combo = 0
Stub.FireEvent("PLAYER_COMBO_POINTS")

Stub.SetClock(43010)
OB.AddAura("Gordok Enforcer", "Kidney Shot")

eq(OB.AuraTimeText("Gordok Enforcer", "Kidney Shot"), "6s",
        "and a stale count is not credited to a fresh stun",
        tostring(OB.AuraTimeText("Gordok Enforcer", "Kidney Shot")))

--[[ The fixed ones are untouched: this is about the two spells whose length is
     bought, and everything else still reads its one number. ]]--
OB.auras = {}
OB.auraLengths = {}
Stub.SetClock(43100)

OB.AddAura("Gordok Enforcer", "Blind")
OB.AddAura("Gordok Enforcer", "Cheap Shot")

eq(OB.AuraTimeText("Gordok Enforcer", "Blind"), "10s", "Blind is ten, as it was")
eq(OB.AuraTimeText("Gordok Enforcer", "Cheap Shot"), "4s",
        "and Cheap Shot four")

OB.auras = {}
OB.auraLengths = {}
Stub.player.combo = 0

--[==[ **The target frame notes what it reads**, so a debuff applied by somebody
     else -- which never reaches this player's log -- still gets a timer from the
     moment it was first seen. ]==]
OB.auras = {}
Stub.SetUnitAuras("target", {}, { "Rend" })
getglobal("TargetFrameDebuff1"):Show()

Stub.SetClock(41200)
frames:ApplyAuraTimers("target")

check(OB.auras["Gordok Enforcer"] ~= nil,
        "reading a debuff off the target starts its clock")

Stub.SetClock(41204)
frames:ApplyAuraTimers("target")

eq(getglobal("TargetFrameDebuff1").ecoAuraTimer:GetText(), "17s",
        "and the timer counts down from there",
        tostring(getglobal("TargetFrameDebuff1").ecoAuraTimer:GetText()))

--[==[ **Filed under the name, which is what makes it work at all.**

     Asserted by looking the same debuff up under the token: the store has
     nothing there, so a version of this that asked with "target" would draw no
     number and look exactly like a spell whose duration is unknown. ]==]
eq(OB.AuraTimeText("target", "Rend"), nil,
        "the store holds nothing under the unit token")

--[[ An icon the client is not showing gets no number: the frames are reused,
     so slot four holds last target's debuff until something draws over it. ]]--
getglobal("TargetFrameDebuff2"):Show()
Stub.SetUnitAuras("target", {}, { "Rend", "Mystery Poison" })
eq(frames:ApplyAuraTimers("target"), 1,
        "a debuff with no known duration shows no number rather than nought")

--[[ Switched off, every number goes -- including the ones already drawn, which
     is the half a naive early return leaves behind. ]]--
cfg.auraTimers = false
frames:ApplyAuraTimers("target")
check(not GLOBAL_targetTimer:IsShown(), "switching the setting off clears them")

cfg.auraTimers = true
getglobal("TargetFrameDebuff1"):Hide()
getglobal("TargetFrameDebuff2"):Hide()
OB.auras = {}

--[==[ **And the same for a buff, which had no table to look in.**

     Everything above works and none of it ran on the buff half: `AURA_SLOTS`
     has always covered `TargetFrameBuff` as well, and the pass has always read
     it -- but `OB.AuraTimeLeft` asked `debuffDurations` and only that, so a
     target's buffs found nothing and drew nothing.

     `debuffDurations` carries a handful of buffs incidentally -- Battle Shout,
     Arcane Intellect, Mark of the Wild are in it -- which is exactly what made
     this hard to see: some buffs had a timer and most did not, which reads as
     flaky rather than as missing. ]==]
Stub.SetUnitAuras("target", { "Power Word: Fortitude" }, {})
getglobal("TargetFrameBuff1"):Show()

Stub.SetClock(50000)
frames:ApplyAuraTimers("target")

check(OB.auras["Gordok Enforcer"] ~= nil,
        "reading a buff off the target starts its clock too")

Stub.SetClock(50060)
eq(frames:ApplyAuraTimers("target"), 1, "and the buff gets a number")

eq(getglobal("TargetFrameBuff1").ecoAuraTimer:GetText(), "29m",
        "counting down from the thirty minutes the table says",
        tostring(getglobal("TargetFrameBuff1").ecoAuraTimer:GetText()))

--[==[ **The rule the debuff table states holds here too**: a buff nobody has
     written a duration for draws nothing rather than nought. A timer reading
     four minutes on a thirty minute blessing is worse than no timer, because it
     is read as fact rather than as ignorance. ]==]
OB.auras = {}
Stub.SetUnitAuras("target", { "Mystery Blessing" }, {})
frames:ApplyAuraTimers("target")

eq(frames:ApplyAuraTimers("target"), 0,
        "a buff with no known duration shows no number rather than nought")

--[[ Asked of the table directly as well, so a failure says whether the lookup
     or the drawing is at fault. ]]--
check(OB.buffDurations ~= nil, "there is a buff duration table")
eq(OB.buffDurations["Power Word: Fortitude"][0], 1800,
        "with the buffs a target actually carries in it")
eq(OB.buffDurations["Greater Blessing of Might"][0], 900,
        "including the ones that differ from their lesser form")

getglobal("TargetFrameBuff1"):Hide()
Stub.SetUnitAuras("target", {}, {})
OB.auras = {}

-- ---------------------------------------------------------------------------
-- a corpse says "Dead" and nothing else
-- ---------------------------------------------------------------------------

--[==[ **The health text was still there underneath it.**

     The client writes "Dead" into its own bar text for a corpse -- better than
     anything a number could say -- and this addon wrote "0 / 4500" into its own
     string beside it, so a dead target carried both.

     There was a branch meant to stop that. It asked `value == 0 and
     bar.zeroText`, and **nothing anywhere ever set `zeroText`**: it was read in
     that one line and assigned nowhere in the addon. The condition could not be
     true, so the branch had never run once and no test had ever reached it.

     Asked of the unit now, which is the thing that knows. ]==]
--[[ Driven through `StatusText`, which is the function that writes a bar's
     text -- it hangs off the client's own text-status hook rather than off the
     module's apply pass, so `Apply` never reaches it. ]]--
Stub.target = { name = "Plague Ghoul", isPlayer = false, dead = true }
Stub.player.hasTarget = true

frames:StatusText(getglobal("TargetFrameHealthBar"))

GLOBAL_deadText = frames:BarTextString(getglobal("TargetFrameHealthBar"))
check(GLOBAL_deadText ~= nil, "the target's health bar has a text string")
eq(GLOBAL_deadText:GetText(), DEAD, "a dead target reads as dead")

--[[ And not as a number, which is the half that was reported: "Dead" appearing
     is no use while "0 / 4500" is still sitting beside it. ]]--
check(string.find(GLOBAL_deadText:GetText() or "", "%d") == nil,
        "with no health numbers left on it",
        tostring(GLOBAL_deadText:GetText()))

--[==[ **And the client's own "Dead" is put away, not left beside ours.**

     1.12 gives the target frame a `TargetDeadText` and shows it for a corpse.
     This addon writes its own "Dead" into the bar, so a dead target wore two of
     them a few pixels apart -- the client's in white above the bar, ours in red
     inside it. Reported from a screenshot of a Gordok Enforcer wearing both.

     The same fault as the numbers this branch was written for, one layer up:
     the client says something true and this addon says it again beside it.

     Ours is the one kept, because it is the string this module positions, fonts
     and sizes, and the only one the party and pet frames have. ]==]
GLOBAL_clientDead = getglobal("TargetDeadText")
check(GLOBAL_clientDead ~= nil, "the client has a dead word of its own")
check(not GLOBAL_clientDead:IsShown(), "and it is put away while ours is up")
eq(GLOBAL_clientDead:GetText(), "", "with nothing left in it to show through")

--[==[ **Ghosts too.** A player running back is not at zero health and is not
     somebody whose health anybody wants a number for -- `unitDead` covers both
     because `UnitIsDeadOrGhost` does. ]==]
Stub.target = { name = "Sylvie", isPlayer = true, dead = true }
frames:StatusText(getglobal("TargetFrameHealthBar"))

eq(frames:BarTextString(getglobal("TargetFrameHealthBar")):GetText(), DEAD,
        "and so does a ghost")

--[[ Alive again, the numbers come back -- a frame that says "Dead" for the rest
     of the session is worse than one that never said it. ]]--
Stub.target = { name = "Plague Ghoul", isPlayer = false, dead = false }
frames:StatusText(getglobal("TargetFrameHealthBar"))

check(frames:BarTextString(getglobal("TargetFrameHealthBar")):GetText() ~= DEAD,
        "and a living target gets its numbers back",
        tostring(frames:BarTextString(getglobal("TargetFrameHealthBar")):GetText()))

--[==[ **And it is given back**, which is the half that separates hiding
     something from breaking it: an addon switched off has to leave the client's
     own frame able to say a target is dead. Restored through the same
     bookkeeping as the duplicate numbers, which is why it goes through it. ]==]
Stub.target = { name = "Plague Ghoul", isPlayer = false, dead = true }
frames:StatusText(getglobal("TargetFrameHealthBar"))
check(not GLOBAL_clientDead:IsShown(), "the client's word is down while we own the bar")

frames:RestoreAllAuxBarTexts()
check(GLOBAL_clientDead:IsShown(), "and comes back when the module lets go")

Stub.target = { name = "Plague Ghoul", isPlayer = false, class = "WARRIOR" }

Stub.reaction = 5
cfg.npcClassColor = false

--[==[ **There is something to drag even with no target-of-target.**

     Reported as the move frame never appearing in edit mode. Edit mode outlines
     only a frame that is on screen -- the right rule, since an outline round a
     hidden frame is a rectangle over the world with nothing in it -- but these
     two hide themselves whenever their unit is absent, and standing about with
     no target-of-target is exactly when somebody opens edit mode to arrange
     things.

     A placeholder is shown while the mode is on, so the thing being positioned
     is the size and shape of the thing that will be there. ]==]
Stub.player.targetsTarget = nil
frames:StyleSmallFrames()

check(not frames:SmallFrame("targettarget"):IsShown(),
        "with no target-of-target the frame is not on screen")

frames:SetDragMode(true)
check(frames:SmallFrame("targettarget"):IsShown(),
        "but edit mode gives you one to place")

frames:SetDragMode(false)
check(not frames:SmallFrame("targettarget"):IsShown(),
        "and it goes away again when the mode is switched off")

--[==[ **And four things it never drew at all.**

     Reported together, and every one an omission rather than a mistake: the art
     was painted at full brightness whatever dark mode said, the health bar was
     a hardcoded green so a hostile target-of-target looked like a friendly one,
     the resource strip was never given a colour, and there was no level.

     Each is now the same call the rest of the module already makes -- the point
     being that none of these needed new logic, only for the existing logic to
     be reached. ]==]
GLOBAL_totSmall = frames:SmallFrame("targettarget")

if GLOBAL_totSmall then
    --[[ There has to be a target-of-target for any of this to run: the style
         pass hides the frame and returns when the unit does not exist. Asserted
         rather than assumed, so a setup that stops working shows up as a
         failure instead of quietly skipping every check below it. ]]--
    Stub.player.hasTarget = true
    Stub.player.targetsTarget = true

    check(frames:StyleSmallFrame("targettarget"),
            "the target-of-target frame styles at all")

    check(GLOBAL_totSmall.levelText ~= nil
            and GLOBAL_totSmall.levelText:GetText() ~= nil
            and GLOBAL_totSmall.levelText:GetText() ~= "",
            "target of target shows a level")

    check(GLOBAL_totSmall.health.barColor ~= nil,
            "its health bar is given a colour rather than left green")

    check(GLOBAL_totSmall.power.barColor ~= nil,
            "and its resource strip is coloured by the resource")

    --[[ Tinted for dark mode like every other frame here, rather than left
         bright beside frames that are not. ]]--
    GLOBAL_totShade = frames:DarkShade()
    near(GLOBAL_totSmall.art.vertex and GLOBAL_totSmall.art.vertex[1] or -1,
            GLOBAL_totShade, 0.001,
            "and its art carries the same dark shade as the rest")

    Stub.player.targetsTarget = nil
end

cfg.npcClassColor = true
color = frames:UnitColor("target")
local wr = OB.ClassColor("WARRIOR")
eq(color[1], wr, "unless you have asked for their class too")
cfg.npcClassColor = false

--[[ Blizzard's own reaction thresholds: above four is friendly, exactly four is
     neutral, below is hostile. The middle is `== 4` rather than a range because
     it is the only value meaning "will not attack you and will not help you". ]]--
Stub.reaction = 4
eq(frames:ReactionColor("target")[1], cfg.neutralColor[1], "four is neutral")

Stub.reaction = 2
eq(frames:ReactionColor("target")[1], cfg.hostileColor[1], "below it is hostile")

Stub.reaction = 6
eq(frames:ReactionColor("target")[1], cfg.friendlyColor[1], "above it is friendly")

-- ---------------------------------------------------------------------------
-- what the bars say
-- ---------------------------------------------------------------------------

--[[ **1.12 writes health in full or not at all**, and "4382/4382" on a frame the
     size of a postage stamp is four characters of information in nine. ]]--
eq(frames:BarText(4382, 8000, "none"), "", "none is none")
eq(frames:BarText(4382, 8000, "percent"), "55%", "a percentage rounds")
eq(frames:BarText(4382, 8000, "value"), "4.4k", "and a value shortens")
eq(frames:BarText(4382, 8000, "max"), "4.4k/8.0k", "as does a pair")
eq(frames:BarText(4382, 8000, "maxpct"), "4.4k/8.0k (55%)", "and all three")

--[[ The decimal count is the one thing this does differently from the meters'
     shortener: a unit frame is small enough that somebody genuinely wants 4.4k
     on the target and 4.38k on themselves. ]]--
cfg.decimals = 2
eq(frames:BarText(4382, 8000, "value"), "4.38k", "with the places asked for")
cfg.decimals = 1

--[[ Under a thousand is written out. "0.4k" is not shorter than "437" and is
     harder to read. ]]--
eq(frames:BarText(437, 8000, "value"), "437", "a small number is left alone")

cfg.shortNumbers = false
eq(frames:BarText(4382, 8000, "value"), "4382", "and nothing shortens when off")
cfg.shortNumbers = true

-- ---------------------------------------------------------------------------
-- the client, which owns these strings and keeps writing to them
-- ---------------------------------------------------------------------------

--[[ **The whole difficulty of restyling Blizzard's frames rather than replacing
     them.**

     `TextStatusBar_UpdateTextString` is the client's, it owns every one of these
     strings, and it runs from the bar's own `OnValueChanged` -- so it fires
     *after* any handler that took a damage event as its cue. Writing the text on
     an event and stopping there means the client overwrites it a frame later,
     which reads as a setting that does nothing.

     The addon this is ported from replaces the function outright, and that is
     the only thing that works: there is no `hooksecurefunc` in 1.12 and no
     ordering guarantee that would make an event handler win.

     So the test is the client's own path, not the module's: call what Blizzard
     calls and assert the module's answer comes out. ]]--
--[[ Driven from the *unit*, not from the bar. The bar is the fallback for a
     frame with no unit behind it; where there is one, its health is the truth
     and the bar is only where the client happened to leave the number. ]]--
Stub.player.health, Stub.player.healthMax = 4382, 8000

GLOBAL_hp = _G["PlayerFrameHealthBar"]
GLOBAL_hp:SetMinMaxValues(0, 8000)
GLOBAL_hp:SetValue(4382)

cfg.healthText = "maxpct"
--[[ The number lands on the string this addon draws, not the client's. Its own
     overlay sits above the bar and the client's strings are hidden beneath it,
     so asking the client's for the text asks the wrong one. ]]--
TextStatusBar_UpdateTextString(GLOBAL_hp)

eq(frames:BarTextString(GLOBAL_hp):GetText(), "4.4k/8.0k (55%)",
        "the client's own update writes the format that was asked for")

--[[ **And shows it.** Blizzard hides the string unless the `statusBarText` CVar
     is on, which it is not by default -- so a port that writes the right text
     into a hidden string has a setting that silently does nothing for almost
     everybody. ]]--
check(frames:BarTextString(GLOBAL_hp):IsShown(),
        "and shows a string the client would have hidden")

--[[ "None" is the one mode that agrees with the client: no text, and hidden. ]]--
cfg.healthText = "none"
TextStatusBar_UpdateTextString(GLOBAL_hp)
eq(frames:BarTextString(GLOBAL_hp):GetText(), "", "none writes nothing")
check(not frames:BarTextString(GLOBAL_hp):IsShown(), "and hides the string")
cfg.healthText = "maxpct"

--[[ The power bar reads its own setting, not the health one. They are two rows
     on the panel and a single format key would make one of them a lie. ]]--
Stub.player.power, Stub.player.powerMax = 60, 100

GLOBAL_mp = _G["PlayerFrameManaBar"]
GLOBAL_mp:SetMinMaxValues(0, 100)
GLOBAL_mp:SetValue(60)

cfg.powerText = "percent"
TextStatusBar_UpdateTextString(GLOBAL_mp)
eq(frames:BarTextString(GLOBAL_mp):GetText(), "60%", "the power bar reads the power format")

--[[ **The colour, which the client rewrites just as often.**

     `HealthBar_OnValueChanged` paints every health bar green on every value
     change. A module that sets the colour on an event gets one frame of its own
     colour and then Blizzard's. ]]--
Stub.player.class = "ROGUE"
cfg.classColorHealth = true

this = GLOBAL_hp
HealthBar_OnValueChanged(4382, nil)
this = nil

GLOBAL_r, GLOBAL_g, GLOBAL_b = OB.ClassColor("ROGUE")
eq(select(1, GLOBAL_hp:GetStatusBarColor()), GLOBAL_r,
        "the client's own colour pass leaves the class colour alone")
eq(select(2, GLOBAL_hp:GetStatusBarColor()), GLOBAL_g,
        "on every channel")

--[[ Off, and the player's own swatch is used -- which is a setting the original
     has and this one needs, because "not class coloured" still has to be some
     colour and green is the client's, not a choice. ]]--
cfg.classColorHealth = false

this = GLOBAL_hp
HealthBar_OnValueChanged(4382, nil)
this = nil

eq(select(1, GLOBAL_hp:GetStatusBarColor()), cfg.playerColor[1],
        "and off, the player's own swatch")
cfg.classColorHealth = true

--[[ **A bar that is not the player's is left to the client.** Target, pet and
     party health are coloured by reaction through the styling pass; the
     replacement only has an opinion about the player's own bar, which is the
     one the client insists on painting green. ]]--
GLOBAL_tot = _G["TargetofTargetHealthBar"]
GLOBAL_tot:SetMinMaxValues(0, 100)

this = GLOBAL_tot
HealthBar_OnValueChanged(50, nil)
this = nil

eq(select(2, GLOBAL_tot:GetStatusBarColor()), 1,
        "another bar still gets the client's own green")

-- ---------------------------------------------------------------------------
-- where the text sits
-- ---------------------------------------------------------------------------

--[[ **A nudge that can be nudged back.**

     Applying the offset only when it is non-zero leaves the text wherever it was
     last put once somebody returns the slider to zero -- a setting that works
     going out and not coming back, which is worse than one that never worked.
     So the anchor is set every pass. ]]--
cfg.healthX, cfg.healthY = 12, -3
frames:Apply()

GLOBAL_point, GLOBAL_rel, GLOBAL_relPoint, GLOBAL_x, GLOBAL_y =
        frames:BarTextString(_G["PlayerFrameHealthBar"]):GetPoint()
eq(GLOBAL_x, 12, "the health text takes the offset across")
eq(GLOBAL_y, -3, "and up")

cfg.healthX, cfg.healthY = 0, 0
frames:Apply()

GLOBAL_point, GLOBAL_rel, GLOBAL_relPoint, GLOBAL_x, GLOBAL_y =
        frames:BarTextString(_G["PlayerFrameHealthBar"]):GetPoint()
eq(GLOBAL_x, 0, "and comes back when the slider does")
eq(GLOBAL_y, 0, "on both axes")

--[[ **The target's horizontal nudges mirror the player's.**

     The target frame's art is the player's reversed, so its numbers sit on the
     opposite side and a positive nudge has to travel the other way. Without it,
     nudging both frames right moves them apart. The name already did this and
     the numbers did not, which is half a rule.

     General says 8 and 6; the player gets +8 and +6, the target -8 and -6, and
     up is up on both. ]]--
cfg.healthX, cfg.healthY = 8, -3
cfg.powerX, cfg.powerY = 6, -2
frames:Apply()

GLOBAL_px = select(4, frames:BarTextString(_G["PlayerFrameHealthBar"]):GetPoint())
GLOBAL_tx = select(4, frames:BarTextString(_G["TargetFrameHealthBar"]):GetPoint())

eq(GLOBAL_px, 8, "the player's health text goes right")
eq(GLOBAL_tx, -8, "and the target's goes the other way by the same amount")

GLOBAL_py = select(5, frames:BarTextString(_G["PlayerFrameHealthBar"]):GetPoint())
GLOBAL_ty = select(5, frames:BarTextString(_G["TargetFrameHealthBar"]):GetPoint())
eq(GLOBAL_py, GLOBAL_ty, "while up stays up on both")

GLOBAL_ppx = select(4, frames:BarTextString(_G["PlayerFrameManaBar"]):GetPoint())
GLOBAL_tpx = select(4, frames:BarTextString(_G["TargetFrameManaBar"]):GetPoint())

eq(GLOBAL_ppx, 6, "the player's power text too")
eq(GLOBAL_tpx, -6, "mirrored on the target the same way")

--[[ **Target of target and the pet are not mirrored.** Only the target frame's
     art is reversed; mirroring the others would move their numbers the wrong
     way for no reason. ]]--
GLOBAL_ptx = select(4, frames:BarTextString(_G["PetFrameHealthBar"]):GetPoint())
eq(GLOBAL_ptx, 8, "the pet follows the player's direction")

--[[ And zero comes back to zero on every frame, which is the half of a nudge
     that is easy to leave broken. ]]--
cfg.healthX, cfg.healthY = 0, 0
cfg.powerX, cfg.powerY = 0, 0
frames:Apply()

eq(select(4, frames:BarTextString(_G["TargetFrameHealthBar"]):GetPoint()), 0,
        "the target's health text returns to its baseline")
eq(select(4, frames:BarTextString(_G["TargetFrameManaBar"]):GetPoint()), 0,
        "and so does its power text")

--[[ **The name anchors to the health bar's top edge, not the frame's centre.**

     Which is the original's anchor, and it is not a detail: a name centred on
     the frame lands in the middle of the portrait. It also means the player and
     target names stay level with each other automatically, because their bars
     are the same size at the same height. ]]--
cfg.nameX, cfg.nameY = 0, 0
frames:Apply()

GLOBAL_point, GLOBAL_rel, GLOBAL_relPoint, GLOBAL_x, GLOBAL_y =
        _G["PlayerName"]:GetPoint()
eq(GLOBAL_relPoint, "TOP", "the name hangs off the top of the health bar")
eq(GLOBAL_rel, _G["PlayerFrameHealthBar"], "its own bar, not the frame")

--[[ The target's X is mirrored, because the target frame's art is. Nudging the
     player's name right and the target's name right would move them apart. ]]--
cfg.nameX = 8
frames:Apply()

GLOBAL_point, GLOBAL_rel, GLOBAL_relPoint, GLOBAL_x = _G["PlayerName"]:GetPoint()
eq(GLOBAL_x, 8, "the player's name moves the way the slider says")

GLOBAL_point, GLOBAL_rel, GLOBAL_relPoint, GLOBAL_x =
        _G["TargetName"]:GetPoint()
eq(GLOBAL_x, -8, "and the target's mirrors it")
cfg.nameX = 0

--[[ **A bar that is not ours is left to the client, exactly as it was.**

     Which is what makes replacing the function safe rather than rude: the focus
     frame, a raid frame and any other addon's status bar all still get
     Blizzard's own text. Switching a frame off here has to be indistinguishable
     from this module not existing. ]]--
cfg.replacePet = false
GLOBAL_pet = _G["PetFrameHealthBar"]
GLOBAL_pet:SetMinMaxValues(0, 500)
GLOBAL_pet:SetValue(250)

TextStatusBar_UpdateTextString(GLOBAL_pet)
eq(GLOBAL_pet.TextString:GetText(), "250/500",
        "a frame switched off gets the client's own text back")
cfg.replacePet = true

--[[ **The pet's numbers, hidden as a whole.**

     The original's Hide Pet Text, which is a separate switch from the format --
     a pet bar is small and its exact health is rarely the thing being read, but
     that is a decision about the pet rather than about the format. ]]--
Stub.player.health, Stub.player.healthMax = 250, 500
cfg.hidePetText = true

TextStatusBar_UpdateTextString(GLOBAL_pet)
check(not frames:BarTextString(GLOBAL_pet):IsShown(), "the pet's numbers can be hidden")

cfg.hidePetText = false
TextStatusBar_UpdateTextString(GLOBAL_pet)
check(frames:BarTextString(GLOBAL_pet):IsShown(), "and shown again")
cfg.hidePetText = true

Stub.player.health, Stub.player.healthMax = 4382, 8000

-- ---------------------------------------------------------------------------
-- not rebuilding a string that already says the right thing
-- ---------------------------------------------------------------------------

--[==[ **`TextStatusBar_UpdateTextString` builds "2.10k / 3.06k (69%)" from
     scratch every call**, and the repair pass that undoes Octo re-showing its
     own white text runs at ten hertz against four frames. Nine times in ten it
     was rebuilding a string identical to the one already on screen -- forty a
     second, for the whole session.

     That is what a hitch every few seconds is made of. Nothing here is slow; it
     just keeps handing the collector work. ]==]
GLOBAL_hpBar = getglobal("PlayerFrameHealthBar")

--[==[ Noted so the bar goes back exactly as it was. This block drives the bar
     directly rather than through the stub's player, and a test that leaves one
     of those set is answered by whichever test reads it next -- which is a
     failure a long way from its cause. ]==]
GLOBAL_hpWas = GLOBAL_hpBar:GetValue()
GLOBAL_hpMinWas, GLOBAL_hpMaxWas = GLOBAL_hpBar:GetMinMaxValues()

GLOBAL_realUpdate = TextStatusBar_UpdateTextString
GLOBAL_textBuilds = 0

TextStatusBar_UpdateTextString = function(bar)
    GLOBAL_textBuilds = GLOBAL_textBuilds + 1
    return GLOBAL_realUpdate(bar)
end

frames:RefreshBarText(GLOBAL_hpBar, true)
GLOBAL_textBuilds = 0

for GLOBAL_i = 1, 20 do frames:RefreshBarText(GLOBAL_hpBar) end
eq(GLOBAL_textBuilds, 0, "twenty passes at the same health rebuild nothing")

--[==[ And it is a skip, not a freeze: the number moving is the whole point. ]==]
Stub.player.health = 4000
GLOBAL_hpBar:SetValue(4000)
frames:RefreshBarText(GLOBAL_hpBar)

eq(GLOBAL_textBuilds, 1, "and health changing rebuilds it once")

--[==[ A maximum that moves counts too -- buffing stamina changes the second
     number without touching the first. ]==]
GLOBAL_textBuilds = 0
GLOBAL_hpBar:SetMinMaxValues(0, 9000)
frames:RefreshBarText(GLOBAL_hpBar)
eq(GLOBAL_textBuilds, 1, "and so does the maximum moving")

--[==[ **The unconditional pass has to stay.**

     The repair exists for text somebody *else* re-showed, and that can happen
     without any value moving. Driven purely by change, the one case this was
     written for is exactly the case it would stop covering -- so `force` still
     rebuilds regardless, and the ticker calls it that way once a second. ]==]
GLOBAL_textBuilds = 0
frames:RefreshBarText(GLOBAL_hpBar, true)
eq(GLOBAL_textBuilds, 1, "a forced pass rebuilds whatever the values say")

TextStatusBar_UpdateTextString = GLOBAL_realUpdate

Stub.player.health, Stub.player.healthMax = 4382, 8000
GLOBAL_hpBar:SetMinMaxValues(GLOBAL_hpMinWas, GLOBAL_hpMaxWas)
GLOBAL_hpBar:SetValue(GLOBAL_hpWas)
frames:RefreshBarText(GLOBAL_hpBar, true)

-- ---------------------------------------------------------------------------
-- shortening, which is one band and not everything
-- ---------------------------------------------------------------------------

--[[ **The switch is about the thousand-to-ten-thousand band and nothing else**,
     which is what the original's "Format HP<10k" means.

     Above ten thousand always shortens: five digits do not fit on a unit frame
     and nobody reads them, so that is not offered as a preference. The port had
     the switch governing everything above a thousand, which made it mean
     something its own label did not say. ]]--
cfg.shortNumbers = false
cfg.decimals = 2

eq(frames:Number(4382), "4382", "off, the middle band is written out")
eq(frames:Number(43820), "43.82k", "but five digits shorten regardless")
eq(frames:Number(4382000), "4.38m", "and millions do too")

cfg.shortNumbers = true
eq(frames:Number(4382), "4.38k", "on, the middle band shortens as well")
eq(frames:Number(437), "437", "and under a thousand is left alone either way")

cfg.decimals = 3
eq(frames:Number(4382), "4.382k", "the original offers three places")
cfg.decimals = 1

-- ---------------------------------------------------------------------------
-- the rest of what the original does
-- ---------------------------------------------------------------------------

--[[ **The combat glow**, which is the client's own art and the only sign that
     you are in a fight rather than beside one. Cleared to nil rather than
     hidden, because the client shows and hides these itself -- a hidden texture
     would come back on the next event that showed it. ]]--
cfg.statusGlow = true
frames:Apply()
check(_G["PlayerStatusTexture"].texture ~= nil, "the combat glow can be switched on")

cfg.statusGlow = false
frames:Apply()
check(_G["PlayerStatusTexture"].texture == nil, "and cleared rather than hidden")
check(_G["PetAttackModeTexture"].texture == nil, "the pet's flash with it")

--[[ **The pet frame drawn as a target-of-target frame**, which is the right size
     for a bar three units tall -- Blizzard's pet art is a full-size frame.
     Happiness becomes a colour instead of a meter, which says the same thing in
     space the bar already occupies. ]]--
Stub.player.class = "HUNTER"
OB.class = "HUNTER"
cfg.improvedPet = true
Stub.petHappiness = 3

frames:Apply()
check(not _G["PetFrameHappiness"]:IsShown(), "the happiness meter goes")
eq(select(1, _G["PetFrameHealthBar"]:GetStatusBarColor()), cfg.friendlyColor[1],
        "a fed pet reads friendly")

Stub.petHappiness = 2
frames:Apply()
eq(select(1, _G["PetFrameHealthBar"]:GetStatusBarColor()), cfg.neutralColor[1],
        "a content one reads neutral")

Stub.petHappiness = 1
frames:Apply()
eq(select(1, _G["PetFrameHealthBar"]:GetStatusBarColor()), cfg.hostileColor[1],
        "and an unhappy one reads hostile")

--[[ **Only a hunter's pet has happiness.** A warlock's demon, a totem and a
     water elemental are friendly and nothing else; giving them the unhappy
     colour because `GetPetHappiness` answered oddly would invent a problem the
     player does not have. ]]--
Stub.player.class = "WARLOCK"
OB.class = "WARLOCK"
frames:Apply()
eq(select(1, _G["PetFrameHealthBar"]:GetStatusBarColor()), cfg.friendlyColor[1],
        "a demon is friendly whatever the happiness call says")

Stub.player.class = "ROGUE"
OB.class = "ROGUE"
cfg.improvedPet = false
frames:Apply()
check(_G["PetFrameHappiness"]:IsShown(), "and the meter comes back when off")

--[[ **`lockColor` is how the client is told to keep off a bar.** Without it
     `UnitFrame_Update` repaints the colour the moment the unit changes, and the
     one this module set lasts until the next target -- a colour setting that
     works for a second. ]]--
frames:Apply()
check(_G["TargetFrameHealthBar"].lockColor == true,
        "a bar this module colours is locked against the client")

--[[ The player's bar is the exception, and has to be: 1.12 gives it no such
     flag, which is the whole reason `HealthBar_OnValueChanged` is replaced. ]]--
this = _G["PlayerFrameHealthBar"]
HealthBar_OnValueChanged(4382, nil)
this = nil

cfg.classColorHealth = true
GLOBAL_r = OB.ClassColor("ROGUE")

this = _G["PlayerFrameHealthBar"]
HealthBar_OnValueChanged(4382, nil)
this = nil

eq(select(1, _G["PlayerFrameHealthBar"]:GetStatusBarColor()), GLOBAL_r,
        "so the player's colour survives the client's own pass instead")


-- ---------------------------------------------------------------------------
-- what colour the numbers are
-- ---------------------------------------------------------------------------

--[[ **Not the colour of the bar, which is what the port had.**

     On a class-coloured bar that makes a warlock's health purple text on a
     purple bar -- the one arrangement that cannot be read. The original colours
     each by what it *means*: health ramps red to green by what is left, and
     resource takes its power type's own colour. ]]--
cfg.colorText = true

GLOBAL_health = OB.profile.modules.health

--[[ Compared to two places, because a ramp is arithmetic and the ends come back
     as 0.10000000000001 rather than as the anchor that was put in. ]]--
function rampChannel(value, max)
    return OB.Round(frames:TextColor("health", value, max) * 100)
end

eq(rampChannel(8000, 8000), OB.Round(GLOBAL_health.fullColor[1] * 100),
        "full health reads as full")
eq(rampChannel(0, 8000), OB.Round(GLOBAL_health.lowColor[1] * 100),
        "and empty reads as empty")

--[[ The anchors are the health module's own, so a number on a unit frame and
     the bar in the HUD agree about what half looks like rather than being two
     opinions that drift. ]]--
eq(rampChannel(4000, 8000), OB.Round(GLOBAL_health.halfColor[1] * 100),
        "and half is the health module's half")

--[[ **Resource goes by power type, not by class.** A druid in cat form is on
     energy and in bear form on rage; reading the class would give both of them
     mana blue. ]]--
Stub.player.powerType = 3
eq(OB.Round(frames:TextColor("power", 50, 100) * 255), 250, "energy is pale")

Stub.player.powerType = 1
eq(OB.Round(frames:TextColor("power", 50, 100) * 255), 250, "rage is red")
eq(OB.Round(select(2, frames:TextColor("power", 50, 100)) * 255), 108,
        "on the channel that tells them apart")

Stub.player.powerType = 0
eq(frames:TextColor("power", 50, 100), 0.6, "and mana is blue")
Stub.player.powerType = 3

cfg.colorText = false
eq(frames:TextColor("health", 0, 8000), 1, "off, everything is white")
cfg.colorText = true

-- ---------------------------------------------------------------------------
-- moving the frames
-- ---------------------------------------------------------------------------

--[[ **The original's Unlock button, as a mode rather than a lock.**

     On, drag, off -- the same shape the action bars use, because a permanently
     draggable player frame is one you move by accident every time you
     right-click your own buffs. ]]--
eq(frames:DragMode(), false, "drag mode ships off")
GLOBAL_ok, GLOBAL_err = pcall(function() OB.modules.actionbars:SetDragMode(true) end)
check(GLOBAL_ok, "DEBUG actionbars drag mode does not throw", tostring(GLOBAL_err))
GLOBAL_ok, GLOBAL_err = pcall(function() OB.modules.actionbars:ResetPositions() end)
check(GLOBAL_ok, "DEBUG actionbars reset does not throw", tostring(GLOBAL_err))

frames:SetDragMode(true)
eq(frames:DragMode(), true, "and can be switched on")
check(_G["PlayerFrame"]:IsMovable(), "which makes the player frame movable")
check(_G["TargetFrame"]:IsMovable(), "and the target frame")

--[[ The border art tinted green while the mode is on, which is the original's
     own signal: these frames are always on screen, so "can I drag this right
     now" is not otherwise answerable without trying it. ]]--
eq(select(2, _G["PlayerFrameTexture"]:GetVertexColor()), 1,
        "and tints the art so you can see which")

--[==[ **The frame it makes movable has to be the one on screen.**

     Reported as target-of-target not being draggable in edit mode. The list was
     the client's four by name, and two of those are not what you are looking at:
     when this module draws its own target-of-target and pet it hides the
     client's and puts its own in their place. So the drag worked -- on a hidden
     frame -- and the one on screen never moved.

     Asserted through `MovableFrames` rather than by dragging, because the fault
     was never in the dragging. ]==]
GLOBAL_movable = frames:MovableFrames()

GLOBAL_names = {}
for GLOBAL_i = 1, table.getn(GLOBAL_movable) do
    GLOBAL_names[GLOBAL_movable[GLOBAL_i]] = true
end

check(GLOBAL_names["PlayerFrame"] and GLOBAL_names["TargetFrame"],
        "the player and target frames are always movable")

if frames:OwnsSmall("targettarget") then
    check(GLOBAL_names["EquadisClassicOverhaulToT"],
            "and where this module draws its own, that is the one moved")
    check(not GLOBAL_names["TargetofTargetFrame"],
            "rather than the client's, which is hidden underneath it")
else
    check(GLOBAL_names["TargetofTargetFrame"],
            "and the client's where this module is not drawing its own")
end

frames:SetDragMode(false)
eq(frames:DragMode(), false, "off again")
--[[ **Left movable, and that is deliberate.**

     This used to require the frame be locked again, which read as tidy and
     broke a neighbour: an addon offering its own "hold two keys to drag these"
     calls `SetUserPlaced` before `SetMovable`, and on a frame this addon had
     locked the client throws "Frame PlayerFrame is not movable or resizable".
     Reported from a live client, on the keypress that closes edit mode.

     What actually stops a drag is having no handler to start one, which is
     what is checked here. Movable with no `OnDragStart` cannot be dragged by
     anybody, and leaves the frame in the state a neighbour expects. ]]--
check(_G["PlayerFrame"]:GetScript("OnDragStart") == nil,
        "and nothing can start a drag afterwards")
check(_G["PlayerFrame"]:IsMovable(),
        "while the frame itself is left as other addons expect to find it")

--[[ **Back to whatever dark mode says, not to white.** Restoring white here
     would undo the tint every time the mode was switched off, which is a setting
     that quietly loses to a button. ]]--
cfg.darkMode = true
cfg.darkMode = true
frames:SetDragMode(true)
frames:SetDragMode(false)

eq(OB.Round(select(1, _G["PlayerFrameTexture"]:GetVertexColor()) * 100), 60,
        "the dark mode tint survives a trip through drag mode")
cfg.darkMode = false

--[[ **A position is stored as an offset from the centre of the screen**, which
     is the rule the meters and the action bars already follow: measured from an
     edge it is a different place on a different resolution. ]]--
--[[ Anchored CENTER-on-CENTER because that is the only anchor the stub resolves
     into screen coordinates -- see its GetLeft. In the client any anchor works;
     here anything else answers nil and the test would be measuring the stub. ]]--
_G["PlayerFrame"]:ClearAllPoints()
_G["PlayerFrame"]:SetPoint("CENTER", UIParent, "CENTER", -300, 150)
_G["PlayerFrame"]:SetWidth(200)
_G["PlayerFrame"]:SetHeight(100)

frames:StorePosition(_G["PlayerFrame"])

check(cfg.positions["PlayerFrame"] ~= nil, "a dragged frame remembers where it went")

--[[ Put back on the next load, and forgotten rather than moved back on reset --
     the client's own anchor is a place that exists on every resolution, which is
     more than any coordinate this addon could pick. ]]--
frames:PlaceFrames()
GLOBAL_point, GLOBAL_rel, GLOBAL_relPoint = _G["PlayerFrame"]:GetPoint()
eq(GLOBAL_relPoint, "CENTER", "and is placed from the centre on the next load")

--[[ **Not user-placed, which is the opposite of what this once asserted.**

     The old expectation here was that the frame must be marked user-placed "or
     the client puts it back". That is backwards, and believing it cost a long
     time: `SetUserPlaced(true)` hands the position to the *client*, which
     writes it to `layout-cache.txt` on logout and restores it on login, with
     its own anchor, after this module has placed the frame.

     On the install where this was found, that cache still held coordinates left
     by two addons that were switched off entirely, and they were being restored
     over this addon on every single login. The frames were reported as
     misaligned for as long as the geometry was being blamed, and the geometry
     was correct throughout.

     So the frame is kept off the client's books and this addon's saved position
     is the only one -- which is also the only one it can offer to reset. ]]--
check(not _G["PlayerFrame"]:IsUserPlaced(),
        "and is kept off the client's own layout cache")


--[[ **And it survives the client restoring its cache afterwards**, which is the
     half that actually failed in the field: the module placed the frame, the
     client put it back, and nothing looked wrong in any of this addon's own
     numbers. Modelled by moving the frame the way the client's restore does,
     and then letting the login event through. ]]--
_G["PlayerFrame"]:ClearAllPoints()
_G["PlayerFrame"]:SetPoint("TOPLEFT", UIParent, "TOPLEFT", 642, -472)

event = "PLAYER_ENTERING_WORLD"
frames:OnEvent()
event = nil

GLOBAL_point, GLOBAL_rel, GLOBAL_relPoint = _G["PlayerFrame"]:GetPoint()
eq(GLOBAL_relPoint, "CENTER",
        "a cache restore is put back where this addon saved it")
frames:ResetPositions()
eq(next(cfg.positions), nil, "reset forgets rather than choosing a new place")
-- ---------------------------------------------------------------------------
-- taking a frame over
-- ---------------------------------------------------------------------------

--[[ **Per frame, not all at once.** Somebody who has turned the pet frame off
     should keep Blizzard's pet frame exactly as it was. ]]--
eq(frames:Owns({ setting = "replacePlayer" }), true, "the player frame is ours")

cfg.replacePet = false
eq(frames:Owns({ setting = "replacePet" }), false, "and the pet frame is not")
cfg.replacePet = true

frames:Apply()

--[[ The bar takes this addon's texture, which is what makes a unit frame look
     like it belongs beside the HUD rather than beside the client's own art. ]]--
check(getglobal("PlayerFrameHealthBar").barTexture ~= nil,
        "the health bar takes the shared texture")

--[[ **The client's naming is not consistent and cannot be derived**, and for a
     long time both this file and the module derived it anyway -- badly.

     The names used here were `TargetFrameTextureFrameName` and
     `TargetFrameTextureFrameTexture`, which are WotLK globals that do not exist
     on 1.12. Module and stub shared the mistake, so the suite agreed with
     itself while the target frame's font and border settings changed nothing on
     a live client. The 1.12 names are `TargetName` and `TargetFrameTexture`,
     which is what the standalone, DragonflightUI and ShaguTweaks all use. ]]--
local _, nameSize = getglobal("PlayerName"):GetFont()
eq(nameSize, cfg.nameSize, "the player's name takes the font size")

local _, targetSize = getglobal("TargetName"):GetFont()
eq(targetSize, cfg.nameSize, "and so does the target's, under its own name")

--[[ The numbers are written on. The client keeps writing its own into these
     strings, so this rides the same events the frames do rather than hooking
     them. ]]--
Stub.player.health = 4382
Stub.player.healthMax = 8000
cfg.healthText = "maxpct"

frames:Apply()
eq(frames:BarTextString(getglobal("PlayerFrameHealthBar")):GetText(), "4.4k/8.0k (55%)",
        "and the health text says what was asked for")

--[[ **Target-of-target is allowed to have no client FontString.** Stock 1.12
     and private-server forks do not agree on the global name here, and some
     expose no health text at all. ECO creates a private string in that case so
     the same number options still work instead of silently returning false. ]]--
GLOBAL_totTextBar = getglobal("TargetofTargetHealthBar")
GLOBAL_oldTotTextString = GLOBAL_totTextBar.TextString
GLOBAL_oldTotTextGlobal = getglobal("TargetofTargetHealthBarText")
GLOBAL_totTextBar.TextString = false
_G["TargetofTargetHealthBarText"] = nil
Stub.player.targetsTarget = "player"

frames:StyleBar(GLOBAL_totTextBar, 10, 0, 0, nil)
GLOBAL_syntheticTotText = frames:BarTextString(GLOBAL_totTextBar, false)
check(GLOBAL_syntheticTotText ~= nil,
        "target of target gets a fallback number string when the client has none")
check((GLOBAL_syntheticTotText.width or 0) > GLOBAL_totTextBar:GetWidth(),
        "and the small frame gives long numbers more room than its 46px bar")

--[[ With the hide switched off: target of target draws no numbers by
     default now -- vanilla draws none and the donor sets none -- so what is
     being checked here is the format machinery, which needs the text on to
     be visible at all. ]]--
GLOBAL_totHideWas = cfg.hideTotText
cfg.hideTotText = false

frames:StatusText(GLOBAL_totTextBar)
eq(GLOBAL_syntheticTotText:GetText(), "4.4k/8.0k (55%)",
        "so target of target renders the same requested number format")

--[[ **And nothing at all by default**, which is the state a 46x7 bar wants:
     `62.90k/62.90k` and `20.20k` on top of each other is what asking a
     seven-pixel bar to hold two numbers looks like. ]]--
cfg.hideTotText = true
frames:StatusText(GLOBAL_totTextBar)

eq(GLOBAL_syntheticTotText:GetText(), "",
        "and none at all when target of target is left as vanilla draws it")

cfg.hideTotText = GLOBAL_totHideWas

GLOBAL_syntheticTotText:Hide()
GLOBAL_totTextBar.TextString = GLOBAL_oldTotTextString
_G["TargetofTargetHealthBarText"] = GLOBAL_oldTotTextGlobal
Stub.player.targetsTarget = nil

--[[ **The power bar keeps the client's colour.** Mana is blue, rage is red and
     energy is yellow, and those are not preferences -- they are what the numbers
     mean. Only the font and the position are ours.

     **Cleared first, because this asks what `StyleBar` does and not what the
     process has accumulated.** The stub's frames are built once and outlive
     every simulated login, and `RestoreOriginals` legitimately writes the
     client's own colour back on each unbind -- so by the time this line is
     reached the bar has been coloured and uncoloured a hundred times over.
     Reading the leftover asserted that no module anywhere had ever touched it,
     which is a different and much weaker claim that happened to hold until the
     module list changed length. ]]--
local powerBar = getglobal("PlayerFrameManaBar")
powerBar.barColor = nil
frames:StyleBar(powerBar, 10, 0, 0, false, nil)
eq(powerBar.barColor, nil, "the power bar's colour is left to the client")

-- ---------------------------------------------------------------------------
-- portraits and dark mode
-- ---------------------------------------------------------------------------

--[[ **The circular atlas, and this addon's own copy of it.**

     This used to say the art was "the client's own, not a copy -- it is already
     installed", and both halves were wrong. `UI-CLASSES-CIRCLES` is not client
     art, it ships with the addon this one replaces; and depending on that addon
     staying installed is a portrait that breaks when somebody tidies up.

     What was actually being drawn was `UI-CharacterCreate-Classes`, which is a
     **square** atlas. Its corners sit outside the round portrait opening, which
     is the leak this was reported as -- and no amount of shrinking fixes a
     square.

     Asserted by the texture that lands on the portrait rather than by
     `StylePortrait` returning true: the old test passed the whole time the
     wrong atlas was being used. ]]--
Stub.target = { name = "Sylvie", isPlayer = true, class = "PRIEST" }
cfg.classPortrait = true

eq(frames:StylePortrait({ portrait = "TargetPortrait", unit = "target" }), true,
        "a player's portrait becomes their class icon")

GLOBAL_portraitArt = getglobal("TargetPortrait").texture

check(string.find(GLOBAL_portraitArt or "", "UI-CLASSES-CIRCLES", 1, true) ~= nil,
        "cut from the circular atlas", tostring(GLOBAL_portraitArt))
check(string.find(GLOBAL_portraitArt or "", "EquadisClassicOverhaul", 1, true) ~= nil,
        "this addon's own copy of it, not another addon's",
        tostring(GLOBAL_portraitArt))
check(string.find(GLOBAL_portraitArt or "", "CharacterCreate", 1, true) == nil,
        "and never the square one", tostring(GLOBAL_portraitArt))

--[==[ **And it survives the unit walking out of range**, which is the one time
     it is doing any work.

     `UnitIsPlayer` answers from an object the client only keeps for units it
     can see, so a party member across the zone reads as not-a-player and the
     class icon was dropped in favour of the 3D portrait -- the single thing the
     client certainly cannot draw for a unit it has no object for. The icon is
     what still works at distance, so the icon is what should stay. ]==]
Stub.unseen["party1"] = true
Stub.SetGroup({ { name = "Faraway", class = "MAGE" } }, false)

getglobal("TargetPortrait").texture = nil

eq(frames:StylePortrait({ portrait = "TargetPortrait", unit = "party1" }), true,
        "an out-of-range party member keeps a class portrait")

GLOBAL_farArt = getglobal("TargetPortrait").texture
check(string.find(GLOBAL_farArt or "", "UI-CLASSES-CIRCLES", 1, true) ~= nil,
        "still cut from the class atlas", tostring(GLOBAL_farArt))

Stub.unseen["party1"] = nil
Stub.target = { name = "Sylvie", isPlayer = true, class = "PRIEST" }


--[[ **Classic frame art is a choice, not a fallback.**

     Which art the frames wear used to be inferred: if the addon whose art it is
     happened to be installed, its art was used, and otherwise the client's.
     That reads as a consolation prize, and it means uninstalling an unrelated
     addon silently changes how somebody's frames look -- which is exactly what
     happened.

     This addon is meant to be friendly to a classic look, so the client's own
     art is something you can ask for and keep. ]]--
GLOBAL_artCfg = OB.profile.modules.unitframes
GLOBAL_artWas = GLOBAL_artCfg.frameMode

GLOBAL_artCfg.frameMode = "classic"
frames:Apply()

GLOBAL_playerArt = getglobal("PlayerFrameTexture").texture

check(string.find(GLOBAL_playerArt or "", "EquadisUnitFrames", 1, true) == nil,
        "asking for classic art gets the client's own", tostring(GLOBAL_playerArt))
check(string.find(GLOBAL_playerArt or "", "Interface\\TargetingFrame", 1, true) ~= nil,
        "from the client's own folder", tostring(GLOBAL_playerArt))

--[[ And switched off it goes back to the borrowed art where that is installed,
     which is what somebody upgrading already had. ]]--
GLOBAL_artCfg.frameMode = "compact"
frames:Apply()

GLOBAL_playerArt = getglobal("PlayerFrameTexture").texture
check(GLOBAL_playerArt ~= nil, "and switching it off still draws something",
        tostring(GLOBAL_playerArt))

-- ---------------------------------------------------------------------------
-- art and geometry are one decision, across every combination
-- ---------------------------------------------------------------------------

--[==[ **The recurring fault, guarded rather than fixed again.**

     "The bars are not aligned with the frame overlay" has come back repeatedly,
     and every previous answer fixed one side of a pair. The pair is the fault:
     `StyleFrameArt` branched on classic *and* compact -- three outcomes -- while
     the geometry branched on classic alone. One combination therefore painted
     the stock **small** frame and applied the client's **full-size** bar layout,
     and there is no arrangement of numbers that makes those agree.

     Each side was individually reasonable, which is why reading either one alone
     never found it, and why it survived four passes through geometry that was
     correct.

     So this walks every combination of the two switches and requires the art
     that was painted and the layout that was applied to come from the same
     named choice. A third switch, or a fourth frame, cannot reintroduce the
     divergence without failing here. ]==]
context = "frame art and geometry: "

GLOBAL_compactWas = GLOBAL_artCfg.frameMode

--[[ Every outcome the choice can name has a layout. A choice with no layout is
     the small-frame branch coming back under another name. ]]--
GLOBAL_layoutFor = { donorFull = "full", donorCompact = "compact", classicFull = "client" }

--[[ Written out rather than counted in binary: the point is that every
     combination is named, and a list you can read is a list somebody can add
     the fifth row to. ]]--
GLOBAL_artCombos = {
    --[==[ **Three modes, where this used to walk four combinations.**

         `classicFrameArt` and `compact` were independent booleans and this
         swept all four pairs -- including classic-and-compact, which is not a
         thing the art supports and was only ever reachable because two
         switches cannot express one choice. `frameMode` says which of three,
         so there are three. ]==]
    { mode = "overhaul" },
    { mode = "compact" },
    { mode = "classic" },
}

for GLOBAL_ci = 1, table.getn(GLOBAL_artCombos) do
    GLOBAL_artCfg.frameMode = GLOBAL_artCombos[GLOBAL_ci].mode

    GLOBAL_choice = frames:FrameArtChoice()
    GLOBAL_where = "classic=" .. tostring(GLOBAL_artCfg.classicFrameArt)
            .. " compact=" .. tostring(GLOBAL_artCfg.compact)

    check(GLOBAL_layoutFor[GLOBAL_choice] ~= nil,
            "every art choice names a layout it was drawn for",
            GLOBAL_where .. " -> " .. tostring(GLOBAL_choice))

    eq(frames:FrameGeometryMode(), GLOBAL_layoutFor[GLOBAL_choice],
            "and the geometry follows it, " .. GLOBAL_where)

    frames:Apply()
    GLOBAL_playerArt = getglobal("PlayerFrameTexture").texture

    --[==[ **The small stock frame is never selected.** It is the one texture with
         no bar layout behind it, and selecting it is the misalignment. ]==]
    check(string.find(GLOBAL_playerArt or "", "SmallTargetingFrame", 1, true) == nil,
            "and the frame with no layout behind it is never painted, " .. GLOBAL_where,
            tostring(GLOBAL_playerArt))

    --[[ Classic means the client's own art; anything else means the donor's.
         Read off the texture that was actually set, so the choice cannot claim
         one thing while the frame wears another. ]]--
    if GLOBAL_choice == "classicFull" then
        check(string.find(GLOBAL_playerArt or "", "Interface" .. "\\" .. "TargetingFrame",
                1, true) ~= nil,
                "classic art is the client's own, " .. GLOBAL_where,
                tostring(GLOBAL_playerArt))
    else
        --[[ Stated as "not the client's" rather than by naming the donor's
             folder: where the bundled art lives is a packaging detail and has
             moved once already, while "classic means the client's own art" is
             the rule under test. ]]--
        check(string.find(GLOBAL_playerArt or "",
                    "Interface" .. "\\" .. "TargetingFrame", 1, true) == nil,
                "and anything else is the donor's, " .. GLOBAL_where,
                tostring(GLOBAL_playerArt))
    end
end

GLOBAL_artCfg.frameMode = GLOBAL_compactWas


-- ---------------------------------------------------------------------------
-- a frame this module does not own keeps the client's own numbers
-- ---------------------------------------------------------------------------

--[==[ **"Not ours" is ownership, not recognition.**

     `StatusText` asked only whether the bar was one it *knew* --
     `PlayerFrameHealthBar` always is -- so on a frame this module had declined
     to own it went on writing its own numbers into the client's bar.
     `3.61k/3.61k (100%)` in a 119-pixel bar the client sized for `3610 / 3610`
     spills past the bar and past the art around it, and reads exactly like the
     frame not fitting its bars.

     The comment on that line was already right about what should happen -- a
     module that is switched off has to look switched off. The condition did not
     implement it. ]==]
context = "bar text ownership: "

GLOBAL_replaceWas = GLOBAL_artCfg.replacePlayer
GLOBAL_blizzCalls = 0
GLOBAL_realBlizz = EquadisOverhaulBlizzStatusText
EquadisOverhaulBlizzStatusText = function(bar)
    GLOBAL_blizzCalls = GLOBAL_blizzCalls + 1
end

GLOBAL_artCfg.replacePlayer = false
frames:StatusText(getglobal("PlayerFrameHealthBar"))
eq(GLOBAL_blizzCalls, 1,
        "an unowned bar is handed back to the client's own writer")

GLOBAL_artCfg.replacePlayer = true
GLOBAL_blizzCalls = 0
frames:StatusText(getglobal("PlayerFrameHealthBar"))
eq(GLOBAL_blizzCalls, 0, "and an owned one is written by this module")

EquadisOverhaulBlizzStatusText = GLOBAL_realBlizz
GLOBAL_artCfg.replacePlayer = GLOBAL_replaceWas

context = "unit frames: "

GLOBAL_artCfg.frameMode = GLOBAL_artWas
frames:Apply()
--[[ Only for players. A wolf with a warrior's crest on it is worse than the
     model it replaced -- and the icon must not survive the target changing
     from a player to a mob, which is what restoring rather than returning
     early is for. ]]--
Stub.target = { name = "Wolf", isPlayer = false, class = "WARRIOR" }
eq(frames:StylePortrait({ portrait = "TargetPortrait", unit = "target" }), false,
        "an NPC keeps the model the client draws")

GLOBAL_portraitArt = getglobal("TargetPortrait").texture
check(string.find(GLOBAL_portraitArt or "", "UI-CLASSES-CIRCLES", 1, true) == nil,
        "with no class icon left over from the player before it",
        tostring(GLOBAL_portraitArt))

cfg.classPortrait = false

--[[ **Switching it off has to undo it.**

     The refresh that applies class portraits lived inside `if classPortrait`,
     so turning the setting off stopped the loop -- and `StylePortrait`, which
     is the only thing that calls `RestorePortrait`, stopped being called with
     it. The icon applied while the setting was on stayed on the frame, and
     nothing in the addon would ever take it off again. It read as a setting
     that does not work.

     Driven through the tick rather than by calling the restore directly, since
     the tick is what stopped happening. ]]--
Stub.target = { name = "Sylvie", isPlayer = true, class = "PRIEST" }
cfg.classPortrait = true

GLOBAL_portrait = getglobal("TargetPortrait")
GLOBAL_portrait.portraitOf = nil

frames.nextPortraitRefresh = nil
frames:OnUpdate(GetTime())

check(frames.classPortraitsApplied, "the tick applies class portraits")

--[[ Off, and one more tick -- which is the pass that used to do nothing. ]]--
cfg.classPortrait = false
GLOBAL_portrait.portraitOf = nil

frames:OnUpdate(GetTime())

eq(GLOBAL_portrait.portraitOf, "target",
        "switching it off puts the unit's own portrait back")
check(not frames.classPortraitsApplied, "and it stops claiming to have applied one")

--[[ **Once, not every tick.** `SetPortraitTexture` is the client's own job from
     here, and repainting it ten times a second would fight the portrait updates
     it does for itself. ]]--
GLOBAL_portrait.portraitOf = nil
frames:OnUpdate(GetTime())

eq(GLOBAL_portrait.portraitOf, nil, "and does not keep repainting it afterwards")

--[[ Dark mode tints rather than replaces, so it works whatever the client's art
     actually is -- which matters on a server that has restyled its frames. ]]--
cfg.darkMode = true
cfg.darkMode = true
frames:StyleFrameArt({ frame = "PlayerFrame" })

local tint = getglobal("PlayerFrameTexture").vertex
check(tint and tint[1] < 1, "dark mode tints the frame art", tostring(tint and tint[1]))

cfg.darkMode = false
frames:StyleFrameArt({ frame = "PlayerFrame" })
eq(getglobal("PlayerFrameTexture").vertex[1], 1, "and switching it off restores it")

-- ---------------------------------------------------------------------------
-- cast bars, yours and theirs
-- ---------------------------------------------------------------------------

--[==[ **The client draws you a bar with no name and no clock.**

     1.12's own casting bar shows the literal word "Channeling" for every
     channelled spell. Not because the name is unavailable -- the event hands it
     over in `arg2`, which is exactly where `casts.lua` reads it from -- but
     because the stock FrameXML never looks. And neither a cast nor a channel
     gets a number, so "can I finish this before the pull lands" is answered by
     watching a rectangle. ]==]
eq(cfg.playerCastBar, true, "you get your own cast bar")
eq(cfg.castTimer, true, "with the seconds on it")

--[==[ Yellow, near enough to energy to read as the same family of thing: a
     resource filling and emptying on its own clock. The client's grey says
     nothing and looks like a disabled control. ]==]
near(cfg.castColor[1], 1.00, 0.001, "and it is yellow")
near(cfg.castColor[2], 0.82, 0.001, "the way energy is yellow")
check(cfg.castColor[3] < 0.2, "rather than grey")

OB.casting = {}
OB.StartCast(Stub.player.name, "Fireball", 3000)
frames:ApplyPlayerCastBar()

GLOBAL_pcast = frames:CastBar("player")
eq(GLOBAL_pcast.shown, true, "casting shows your bar")
eq(GLOBAL_pcast.label:GetText(), "Fireball", "with the spell named")

--[==[ **The number, which is the half a fraction cannot answer.** A bar
     three-quarters along says the same thing whether the last quarter is a
     tenth of a second or two, and those are different decisions. ]==]
check(GLOBAL_pcast.timer:IsShown(), "and the time left drawn")
check(tonumber(GLOBAL_pcast.timer:GetText()) ~= nil,
        "as a number", tostring(GLOBAL_pcast.timer:GetText()))

near(GLOBAL_pcast.barColor[1], 1.00, 0.001, "drawn in the cast colour")
near(GLOBAL_pcast.barColor[2], 0.82, 0.001, "as set on the panel")

--[==[ One decimal below ten, because the difference between 1.4 and 0.6 seconds
     is the whole of an interrupt decision and "1" for both throws it away.
     Whole numbers above, where a tenth is noise on a number nobody is reacting
     to yet. ]==]
eq(OB.CastTimeText(2.44), "2.4", "seconds are precise while precision matters")
eq(OB.CastTimeText(24.4), "24", "and round once it does not")
eq(OB.CastTimeText(nil), nil, "an unknown duration has no clock")

--[==[ **1.12 hands over a name and a duration, and no picture.**

     Every addon that shows a cast icon builds the name-to-icon map itself, and
     the usual way is to ship a table of every spell in the game -- a large file
     that is wrong the day a server adds something.

     Two sources are already here. Your own spellbook is exact, free and in the
     client's own locale; the aura cache covers a good deal of the rest, because
     much of what is worth watching a mob cast lands as a debuff you have seen
     before. ]==]
eq(cfg.castIcon, true, "the spell icon is shown")

Stub.player.spellNames = { "Fireball", "Frostbolt" }
Stub.player.spellbook = { "Interface\\Icons\\Spell_Fire_FlameBolt",
                          "Interface\\Icons\\Spell_Frost_FrostBolt02" }
OB.RebuildSpellIcons()

eq(OB.SpellIcon("Fireball"), "Interface\\Icons\\Spell_Fire_FlameBolt",
        "your own spellbook answers exactly")

--[==[ The aura cache is the second source, and it is filled by being hit rather
     than by being shipped. ]==]
OB.auraIcons = OB.auraIcons or {}
OB.auraIcons["Corruption"] = "Interface\\Icons\\Spell_Shadow_Corruption"

eq(OB.SpellIcon("Corruption"), "Interface\\Icons\\Spell_Shadow_Corruption",
        "and a debuff you have seen answers for the rest")

--[==[ **No icon rather than a wrong one.** A spell in neither place simply has
     none, and a bar without an icon reads fine -- a bar wearing somebody else's
     icon is a spell you would swear you recognised. ]==]
eq(OB.SpellIcon("Something Nobody Has"), UNKNOWN_SPELL_ICON, "and anything else gets the question mark")
eq(OB.SpellIcon(nil), nil, "nor does nothing at all")

OB.casting = {}
OB.StartCast(Stub.player.name, "Fireball", 3000)
frames:ApplyPlayerCastBar()

check(GLOBAL_pcast.icon:IsShown(), "a cast you know shows its icon")
eq(GLOBAL_pcast.icon:GetTexture(), "Interface\\Icons\\Spell_Fire_FlameBolt",
        "the right one")

--[==[ The name stays regardless. It is what covers the case the icon cannot. ]==]
eq(GLOBAL_pcast.label:GetText(), "Fireball", "with the name still on it")

OB.casting = {}
OB.StartCast(Stub.player.name, "Something Nobody Has", 3000)
frames:ApplyPlayerCastBar()

--[==[ **A spell nothing knows gets the question mark, not a gap.**

     This hid the icon, on the reasoning that no icon is better than somebody
     else's. That half is still right and this is not the other half:
     `INV_Misc_QuestionMark` is the client's own "there is no art for this", so it
     is not a spell anybody could mistake for another.

     What it buys is a bar that is the same shape every time. An icon that
     appears and disappears depending on whether the caster happens to be in your
     spellbook makes the row jump, and a gap reads as a fault rather than as an
     absence. Asked for in those words. ]==]
check(GLOBAL_pcast.icon:IsShown(),
        "a cast nothing knows still shows an icon")
eq(GLOBAL_pcast.icon:GetTexture(), UNKNOWN_SPELL_ICON,
        "and it is the client's own question mark",
        tostring(GLOBAL_pcast.icon:GetTexture()))
eq(GLOBAL_pcast.label:GetText(), "Something Nobody Has",
        "and is still named")

cfg.castIcon = false
OB.casting = {}
OB.StartCast(Stub.player.name, "Fireball", 3000)
frames:ApplyPlayerCastBar()

check(not GLOBAL_pcast.icon:IsShown(), "and off is off")
cfg.castIcon = true

--[==[ **A channel empties as it runs and a cast fills.**

     That is the one visual difference between them, and it was not merely
     missing here but backwards: `CastInfo` turns a channel round -- it is the
     one place holding the flag -- and the bar turned it round a second time, so
     every channel filled up like a cast.

     Two functions both being careful about the same thing is how that happens.
     Only the one with the flag should be. ]==]
OB.casting = {}
OB.StartCast(Stub.player.name, "Drain Life", 5000, true)
frames:ApplyPlayerCastBar()

check(GLOBAL_pcast.value > 0.9,
        "a channel just begun is nearly full", tostring(GLOBAL_pcast.value))

OB.casting[Stub.player.name].start = GetTime() - 4
frames:ApplyPlayerCastBar()

check(GLOBAL_pcast.value < 0.3,
        "and nearly empty near the end of it", tostring(GLOBAL_pcast.value))

--[==[ Against a cast, read the other way, from the same code. ]==]
OB.casting = {}
OB.StartCast(Stub.player.name, "Fireball", 3000)
OB.casting[Stub.player.name].start = GetTime() - 2.5
frames:ApplyPlayerCastBar()

check(GLOBAL_pcast.value > 0.7,
        "a cast near the end is nearly full", tostring(GLOBAL_pcast.value))

--[==[ Nothing to show when nothing is being cast. ]==]
OB.casting = {}
frames:ApplyPlayerCastBar()
eq(GLOBAL_pcast.shown, false, "and no cast, no bar")

cfg.playerCastBar = false
OB.StartCast(Stub.player.name, "Fireball", 3000)
frames:ApplyPlayerCastBar()
eq(GLOBAL_pcast.shown, false, "switched off, it stays away")
cfg.playerCastBar = true

--[==[ **Your bar and your target's are the same bar built twice.**

     The only things that differ are which unit is read and where it starts.
     Written separately, the timer went on one of them and the colour on the
     other -- which is how the target's came to have neither. ]==]
GLOBAL_tcast = frames:CastBar("target")
check(GLOBAL_tcast ~= GLOBAL_pcast, "they are two bars")

Stub.player.hasTarget = true
Stub.target = { name = "Sylvie", isPlayer = true, class = "PRIEST" }

OB.casting = {}
OB.StartCast("Sylvie", "Mind Flay", 3000, true)
frames:ApplyTargetCastBar()

eq(GLOBAL_tcast.label:GetText(), "Mind Flay", "and the target's names its spell")
check(GLOBAL_tcast.timer:IsShown(), "carries the same clock")
near(GLOBAL_tcast.barColor[2], 0.82, 0.001, "in the same colour")
check(GLOBAL_tcast.value > 0.9, "and empties the same way")

--[==[ **It has to move on its own, every frame.**

     This is what was actually wrong: both bars were refreshed from `Apply`,
     which runs on a restyle. A cast bar driven that way crosses its gap in
     three or four visible jumps and reads as broken rather than slow -- and the
     target's bar had been doing exactly that since it was written.

     So the test is not "does a bar appear" but "does it advance when nothing
     happened except time passing". `OnUpdate` is called rather than `Apply`,
     because wiring the update to the per-frame pass is the whole fix. ]==]
OB.casting = {}
OB.StartCast(Stub.player.name, "Fireball", 3000)

frames:OnUpdate(GetTime())
GLOBAL_castWas = GLOBAL_pcast.value

OB.casting[Stub.player.name].start = OB.casting[Stub.player.name].start - 1
frames:OnUpdate(GetTime())

check(GLOBAL_pcast.value > GLOBAL_castWas,
        "a second of casting moves the bar with no restyle",
        tostring(GLOBAL_castWas) .. " -> " .. tostring(GLOBAL_pcast.value))

--[==[ And the clock moves with it, which is the half a fraction cannot say. ]==]
check(GLOBAL_pcast.timer:GetText() ~= "",
        "and the clock comes with it")

--[==[ **Only the fill, the name and the clock.** The per-frame pass must not be
     re-picking textures and fonts sixty times a second -- the same rule the
     frame geometry refresh beside it already follows. ]==]
GLOBAL_realBarTex = GLOBAL_pcast.SetStatusBarTexture
GLOBAL_texWrites = 0

GLOBAL_pcast.SetStatusBarTexture = function(self, tex)
    GLOBAL_texWrites = GLOBAL_texWrites + 1
    return GLOBAL_realBarTex(self, tex)
end

for GLOBAL_i = 1, 20 do frames:OnUpdate(GetTime()) end
eq(GLOBAL_texWrites, 0, "twenty frames re-pick the texture no times")

GLOBAL_pcast.SetStatusBarTexture = GLOBAL_realBarTex

--[==[ A restyle still does, because that is when it can have changed. ]==]
frames:StyleCastBar("player")
near(GLOBAL_pcast.barColor[2], 0.82, 0.001, "a restyle sets the colour again")

--[==[ **How big the bar is, which used to be 150 by 14 and nothing else.**

     It is drawn away from the frame it belongs to and read out of the corner of
     the eye, so the size depends entirely on where it has been dragged and what
     else is on screen. One pair of sliders for both bars, like the colour and
     the icon. ]==]
eq(cfg.castWidth, 150, "the bar ships at the size it was hard-coded to")
eq(cfg.castHeight, 14, "in both directions")

cfg.castWidth = 300
cfg.castHeight = 24
frames:StyleCastBar("player")

eq(GLOBAL_pcast:GetWidth(), 300, "a wider setting makes a wider bar")
eq(GLOBAL_pcast:GetHeight(), 24, "and a taller one a taller bar")

--[[ The icon is square off the bar's height, so growing the bar does not leave
     a stretched picture beside it. ]]--
eq(GLOBAL_pcast.icon:GetWidth(), 24, "with the icon still square")

--[[ Both bars, because they are the same bar drawn for two units. ]]--
frames:StyleCastBar("target")
eq(frames:CastBar("target"):GetWidth(), 300, "and the target's bar with it")

--[==[ **Clamped to the sliders' own range**, because a profile from an older
     build has no number at all and a hand-edited one can hold any number: a bar
     four pixels tall has no room for the name written on it, and one wider than
     the screen cannot be dragged back. ]==]
cfg.castWidth = 5000
cfg.castHeight = 2
frames:StyleCastBar("player")

eq(GLOBAL_pcast:GetWidth(), 400, "a width past the slider stops at its top",
        tostring(GLOBAL_pcast:GetWidth()))
eq(GLOBAL_pcast:GetHeight(), 8, "and a height under it at its bottom",
        tostring(GLOBAL_pcast:GetHeight()))

cfg.castWidth = nil
cfg.castHeight = nil
frames:StyleCastBar("player")

eq(GLOBAL_pcast:GetWidth(), 150, "a profile with no size at all gets the old one")
eq(GLOBAL_pcast:GetHeight(), 14, "in both directions")

cfg.castWidth = 150
cfg.castHeight = 14
frames:StyleCastBar("player")
frames:StyleCastBar("target")

--[==[ The spell name is not rewritten while it is the same spell. ]==]
GLOBAL_realLabel = GLOBAL_pcast.label.SetText
GLOBAL_labelWrites = 0

GLOBAL_pcast.label.SetText = function(self, text)
    GLOBAL_labelWrites = GLOBAL_labelWrites + 1
    return GLOBAL_realLabel(self, text)
end

for GLOBAL_i = 1, 20 do frames:OnUpdate(GetTime()) end
eq(GLOBAL_labelWrites, 0, "nor rewrite a spell name that has not changed")

OB.casting = {}
OB.StartCast(Stub.player.name, "Frostbolt", 3000)
frames:OnUpdate(GetTime())

check(GLOBAL_labelWrites > 0, "and a different spell is written once")
eq(GLOBAL_pcast.label:GetText(), "Frostbolt", "with the new name on it")

GLOBAL_pcast.label.SetText = GLOBAL_realLabel

Stub.player.hasTarget = true
OB.casting = {}
OB.StartCast("Sylvie", "Mind Flay", 3000, true)

--[==[ The timer answers to its own switch, on both. ]==]
cfg.castTimer = false
frames:ApplyTargetCastBar()
check(not GLOBAL_tcast.timer:IsShown(), "off is off")
cfg.castTimer = true

OB.casting = {}
Stub.player.hasTarget = false

-- ---------------------------------------------------------------------------
-- how much health a mob actually has
-- ---------------------------------------------------------------------------

--[[ **1.12 will not tell you, and MobHealth3 worked out that it does not have
     to.**

     `UnitHealthMax` on a mob answers 100, because what the client gives is a
     percentage. But the percentage and the damage you deal are two views of the
     same number: hit something for 340, watch it drop four percent, and it has
     eight and a half thousand. ]]--
EquadisClassicOverhaulDB.mobHealth = {}
OB.mobHealth = EquadisClassicOverhaulDB.mobHealth
frames.mobAccHP, frames.mobAccPerc, frames.mobNoCalc = {}, {}, {}

--[[ Driven the way the game drives it: a hostile mob targeted, UNIT_COMBAT
     with the damage, UNIT_HEALTH with the percentage the client answers for a
     mob. The stub's target health is the player's health field, so the
     percentage is written there. ]]--
GLOBAL_wasHealth, GLOBAL_wasMax = Stub.player.health, Stub.player.healthMax
GLOBAL_wasTarget, GLOBAL_hadTarget = Stub.target, Stub.player.hasTarget
Stub.player.hasTarget = true
Stub.target = { name = "Defias Thug", level = 22, isPlayer = false, friendly = false }
Stub.player.health, Stub.player.healthMax = 100, 100
cfg.mobHealth = true
cfg.mobHealthPrecision = 10
cfg.mobHealthStableMax = false

eq(OB.MobHealthMax("Defias Thug", 22), nil, "nothing is known to begin with")

eq(frames:MobTargetChanged(), true, "a hostile mob is taken up")
frames:MobCombat(340)
Stub.player.health = 96
frames:MobHealthUpdate()

--[[ Both halves accumulate rather than being divided on the spot. A hit that
     took "four percent" might have taken 3.6 or 4.4, and one sample carries
     that error into the answer where twenty average it away -- so nothing is
     said until the precision floor is reached. ]]--
eq(OB.MobHealthMax("Defias Thug", 22), nil, "four percent is not enough to say")

frames:MobCombat(850)
Stub.player.health = 86
frames:MobHealthUpdate()
eq(OB.MobHealthMax("Defias Thug", 22), 8500,
        "fourteen percent for 1190 is eight and a half thousand")

--[[ **Keyed by name and level together**, which is not fussiness: a level 22
     Defias Thug and a level 24 one are different creatures with the same name,
     and averaging them gives a number that is wrong for both. ]]--
eq(OB.MobHealthMax("Defias Thug", 24), nil,
        "the same name at another level is another creature")

--[[ **nil rather than a guess.** The frames fall back to the percentage, which
     is what the client would have shown anyway -- so a mob nobody has hit reads
     exactly as it does without any of this. ]]--
eq(OB.MobHealthMax("Ghost", 10), nil, "a mob nobody has hit is unknown")

Stub.player.health, Stub.player.healthMax = GLOBAL_wasHealth, GLOBAL_wasMax
Stub.target, Stub.player.hasTarget = GLOBAL_wasTarget, GLOBAL_hadTarget
frames.mobCurrent = nil

-- ---------------------------------------------------------------------------
-- a hunter who is not actually dead
-- ---------------------------------------------------------------------------

--[[ **Feign Death reports as death, at zero health** -- which in a raid is a
     healer watching somebody they believe is a corpse.

     **Kept internal rather than overriding UnitHealth.** The addon this comes
     from replaces the global, which fixes it for every addon at once and is
     exactly why it is wrong: a core function that lies is one every neighbour is
     now reading wrong, and none of them consented. ]]--
OB.feignedHealth = {}
Stub.player.hasTarget = true
Stub.target = { name = "Hunter", isPlayer = true, class = "HUNTER" }
Stub.player.dead = false
Stub.player.health = 3200

eq(frames:NoteFeign("target"), true, "a living player's health is remembered")

--[[ Recorded while alive and read while "dead". A value recorded at the moment
     of death would be zero, which is the number this exists to avoid. ]]--
Stub.player.dead = true
eq(frames:NoteFeign("target"), false, "and not overwritten once they drop")

local feignHealth = frames:HealthOf("target")
eq(feignHealth, 3200, "so the remembered number is what shows")

cfg.feignHealth = false
eq(frames:HealthOf("target"), Stub.player.health,
        "and the client's answer is used with it switched off")
cfg.feignHealth = true

Stub.player.dead = false

-- ---------------------------------------------------------------------------
-- compact, and re-targeting
-- ---------------------------------------------------------------------------

--[[ Sizes rather than a replacement texture, so it works on a server that has
     restyled its frames -- where a replacement would sit on top of something it
     was never drawn for. ]]--
cfg.frameMode = "compact"
frames:StylePlayerGeometry()
frames:StyleTargetGeometry()
--[[ **The width belongs to the client and this module must not write it.**

     It used to set 119, which is what Blizzard's own frame uses. Turtle ships a
     modified FrameXML whose bar is not necessarily that, so the number put the
     bar out of step with art drawn for the client's real width -- a bar that
     does not fit its frame, reported as the frames being broken and chased
     through four wrong answers before anybody compared the two implementations.

     The mod that had these frames looking right never touched the width. It set
     the anchor and the height and inherited the rest, which is the only thing
     that can be correct on a client whose numbers are not known here.

     Written as "whatever it was, it is still that" rather than a number,
     because a test that asserted 119 would be the same mistake in a different
     file. ]]--
--[[ **The donor's geometry, and the art region it was drawn for.**

     A previous revision asserted the opposite of this -- that the width must be
     left at whatever the client had -- on a comment that read ShaguTweaks'
     big-health mod and described it as the addon this is ported from. It is
     not. `EquadisUnitFrames.lua:343` sets the width to 119, the height to 29,
     and the anchor to (106, -22), and the target the same at :447.

     The real fault was never the bars. `UI-TargetingFrame` is a 256x128 file
     that the client displays in a 232x100 region with tex coords cropping it --
     232/256 is 0.90625, 100/128 is 0.78125. Swapping the texture without
     restoring that leaves the region at the file's own size, stretching the art
     by 1.28 vertically and pushing the bottom of the border down past the bars.

     `/eq frames` had been reporting `PlayerArt 256x128` against
     `PlayerFrame 232x100` the whole time. ]]--
cfg.frameMode = "overhaul"
frames:StylePlayerGeometry()
frames:StyleTargetGeometry()
frames:Apply()

eq(getglobal("PlayerFrameHealthBar").width, 119, "the player bar is the donor's width")
eq(getglobal("PlayerFrameHealthBar").height, 29, "and the donor's height")
eq(getglobal("TargetFrameHealthBar").width, 119, "the target bar too")

GLOBAL_pArt = getglobal("PlayerFrameTexture")
eq(GLOBAL_pArt.width, 232, "the art region is the frame's width, not the file's")
eq(GLOBAL_pArt.height, 100, "and the frame's height, which is the whole fault")

--[[ Cropped, and mirrored for the player: the frame art is the target's
     reversed, which is why its left and right run backwards. ]]--
check(GLOBAL_pArt.texcoord ~= nil, "with tex coords set")
eq(GLOBAL_pArt.texcoord and GLOBAL_pArt.texcoord[1], 1.0,
        "the player's crop starts at the right edge")
eq(GLOBAL_pArt.texcoord and GLOBAL_pArt.texcoord[4], 0.78125,
        "and stops where the frame's hundred pixels do")

GLOBAL_tArt = getglobal("TargetFrameTexture")
--[[ **The same window, forward.** The player samples 0.09375 to 1.0 mirrored,
     so the artwork lives in the right 232 pixels of the 256. The target is
     the same file unmirrored and must sample the same window -- not 0 to
     0.90625, which is a different 232 pixels and lands partly on the empty
     margin, drawing a thin outline where the ornate border should be. ]]--
eq(GLOBAL_tArt.texcoord and GLOBAL_tArt.texcoord[1], 0.09375,
        "the target samples the same window as the player")
eq(GLOBAL_tArt.texcoord and GLOBAL_tArt.texcoord[2], 1.0,
        "running forward rather than mirrored")


--[[ **The smaller frames keep the client's own region, from a capture.**

     Pet, target of target and the party have art regions of their own and this
     addon does not know any of their numbers. Four more hardcoded pairs would
     be the player frame's bug in four new places, and wrong on any client
     shipping different art. So each texture's own size is read once, before
     anything here has touched it, and put back afterwards.

     Modelled by breaking one the way the player's was broken -- left at the
     file's own size -- and requiring the styling to put it back. ]]--
GLOBAL_totArt = getglobal("TargetofTargetTexture")

if GLOBAL_totArt then
    GLOBAL_totHome = frames.artHome and frames.artHome["TargetofTargetTexture"]
    check(GLOBAL_totHome ~= nil, "the target of target's region was captured")

    GLOBAL_totArt:SetWidth(256)
    GLOBAL_totArt:SetHeight(128)

    frames:StyleFrameArt({ id = "targettarget", frame = "TargetofTargetFrame",
            art = "TargetofTargetTexture" })

    eq(GLOBAL_totArt.width, GLOBAL_totHome and GLOBAL_totHome.width,
            "and a region left at the file's size is put back to it")
    check(GLOBAL_totArt.width ~= 256,
            "which is not the file's size", tostring(GLOBAL_totArt.width))

--[[ **Target of target gets all of its geometry back, not just its frame.**

     This restored the frame and moved the portrait, and left the bars, the name
     and the artwork wherever anything else had put them. A frame arriving in
     the right place with its contents scattered inside it is what "target of
     target is still a little bit broken" was.

     Broken here the way a neighbour would break it, then required to come back.
     Vanilla's own numbers, for the record: 93x45 frame, 46x7 bars anchored
     TOPRIGHT, art cropping 0.015625 -> 0.7265625 by 0 -> 0.703125. ]]--
--[[ The module's own entry for this frame, so the styling is driven the way
     the addon drives it rather than with a hand-made table. ]]--
FRAMES_TOT = nil
for GLOBAL_fi = 1, table.getn(OB.modules.unitframes.frameEntries or {}) do
    if OB.modules.unitframes.frameEntries[GLOBAL_fi].id == "targettarget" then
        FRAMES_TOT = OB.modules.unitframes.frameEntries[GLOBAL_fi]
    end
end

GLOBAL_totBar = getglobal("TargetofTargetHealthBar")
GLOBAL_totName = getglobal("TargetofTargetName")

if GLOBAL_totBar and GLOBAL_totName then
    GLOBAL_totBar:ClearAllPoints()
    GLOBAL_totBar:SetPoint("CENTER", UIParent, "CENTER", 400, 400)
    GLOBAL_totName:ClearAllPoints()
    GLOBAL_totName:SetPoint("CENTER", UIParent, "CENTER", 400, 400)

    frames:StyleTargetTargetGeometry()

    GLOBAL_barRel = select(2, GLOBAL_totBar:GetPoint(1))
    check(GLOBAL_barRel ~= UIParent,
            "the health bar is taken off wherever it was put")

    --[[ **And its name keeps the client's position.** The donor changes this
         frame's name font and nothing else about it. Hanging it off the top of
         the health bar is the player and target's geometry -- a layout drawn
         for a 232x100 frame, applied to a 93x45 one. ]]--
    --[[ **Through the styling that actually moves it.**

         `StyleTargetTargetGeometry` puts the name back; it is `StyleFrame`
         that would hang it off the health bar. A test that called only the
         first measured a state the fault does not touch, and passed with
         the fix removed. ]]--
    frames:StyleFrame(FRAMES_TOT)

    GLOBAL_nameRel = select(2, GLOBAL_totName:GetPoint(1))
    --[[ Not merely "somewhere other than UIParent": the fault being guarded
         against anchors it to the health bar, which is also not UIParent, so
         that check passed with the fix removed. Named directly instead. ]]--
    check(GLOBAL_nameRel ~= getglobal("TargetofTargetHealthBar"),
            "and the name is not given the health-bar anchor drawn for the"
                    .. " bigger frames")
end

--[[ **The pet's art belongs to the pet frame.**

     The donor hangs it off `PlayerFrame`, which is harmless there because the
     pet frame cannot move. This addon lets it be dragged, and the moment
     somebody does, the bars, portrait and name go with it while the art stays
     behind on the player. It only goes wrong after a drag, which is exactly the
     sort of fault that survives a suite that never drags anything. ]]--
GLOBAL_petCfg = OB.profile.modules.unitframes
GLOBAL_petWas = GLOBAL_petCfg.improvedPet
GLOBAL_petCfg.improvedPet = true

frames:StylePetGeometry()

GLOBAL_petArt = getglobal("PetFrameTexture")
GLOBAL_petArtRel = GLOBAL_petArt and select(2, GLOBAL_petArt:GetPoint(1))

eq(GLOBAL_petArtRel, getglobal("PetFrame"),
        "the slim pet art is anchored to the pet frame, not the player's")

GLOBAL_petCfg.improvedPet = GLOBAL_petWas
end

--[[ **Captured once.** A second capture would record whatever the last pass
     left -- the state being corrected, not the one to return to -- which is the
     same trap the minimap button collector has. ]]--
if GLOBAL_totArt and GLOBAL_totHome then
    GLOBAL_totArt:SetWidth(999)
    frames:RememberArt({ id = "targettarget", frame = "TargetofTargetFrame",
            art = "TargetofTargetTexture" })

    eq(frames.artHome["TargetofTargetTexture"].width, GLOBAL_totHome.width,
            "a later capture does not overwrite the first")
end

cfg.frameMode = "compact"
frames:StyleTargetGeometry()
eq(getglobal("TargetFrameHealthBar").height, 20, "compact shortens the health bar")

cfg.frameMode = "overhaul"
frames:StyleTargetGeometry()
--[[ 29, which is the donor's number: `EquadisUnitFrames.lua:344`.

     This said 29 while calling it "the client's own number", which it is not
     -- the client's health bar is a thin strip and 29 is the donor's
     big-health figure. Then it briefly said 30, from a mod that is not the
     donor. It is the donor's 29, and the comment now says whose. ]]--
eq(getglobal("TargetFrameHealthBar").height, 29,
        "and switching it off gives the donor's taller bar back")

--[[ **Re-target somebody who vanished.** Feign Death, Vanish and Invisibility
     all clear your target, and the target you had is almost always the target
     you still want. Off, because it is the one thing here that acts on its
     own. ]]--
eq(cfg.retarget, false, "re-targeting is off")

cfg.retarget = true
frames.retargetUnit = nil
Stub.target = { name = "Sylvie", isPlayer = true, class = "PRIEST" }
Stub.player.hasTarget = true
eq(frames:RetargetStep(), false, "a target you can see is recorded, not acted on")
eq(frames.retargetUnit, "Sylvie", "who you were looking at is remembered")

Stub.player.hasTarget = false
eq(frames:RetargetStep(), false, "and with nobody there, nothing comes back")

--[[ **And they are still remembered, which is the whole feature.**

     This asserted the opposite -- that a failed reacquisition forgets the name.
     That was the first ECO port's behaviour; the SHIRSIG state machine
     deliberately holds the name after the first failure so the *next* attempt
     can take it back. Forgetting on failure would defeat the point: Vanish,
     Feign Death and Invisibility all fail the first attempt by definition,
     which is precisely when you want your target back. ]]--
eq(frames.retargetUnit, "Sylvie", "and still remembered, so they can be taken back")

-- ---------------------------------------------------------------------------
-- and it does not fight you for the target you chose
-- ---------------------------------------------------------------------------

--[[ **This broke Tab-targeting.**

     The step above records the current target only when it is a *player*. The
     reacquisition below it then ran whenever the current target was not one --
     which includes every mob in the game.

     So: Tab onto a boar. Not a player, so nothing is recorded; fall through;
     the last player you had is re-targeted within a frame. Press Tab and
     nothing happens, or you snap back to somebody standing behind you.

     The feature is for Vanish, Feign Death and Invisibility -- things that
     *clear* your target. A target you can see is a target you chose, and
     choosing one is not a problem to be corrected. ]]--
cfg.retarget = true

Stub.targetable["Sylvie"] = { name = "Sylvie", isPlayer = true, class = "PRIEST" }

--[[ Remember a player, the way the feature is meant to. ]]--
Stub.player.hasTarget = true
Stub.target = { name = "Sylvie", isPlayer = true, class = "PRIEST" }
frames:RetargetStep()
eq(frames.retargetUnit, "Sylvie", "a player target is remembered")

--[[ **Now Tab onto a mob**, which is the case that was broken. ]]--
Stub.target = { name = "Ragged Boar", isPlayer = false, class = "WARRIOR" }
Stub.player.hasTarget = true

frames:RetargetStep()

eq(Stub.target and Stub.target.name, "Ragged Boar",
        "targeting a mob is left exactly alone",
        tostring(Stub.target and Stub.target.name))

--[[ And doing it again does not creep back either -- the ticker runs this
     several times a second, so one pass proving nothing is not enough. ]]--
frames:RetargetStep()
frames:RetargetStep()
eq(Stub.target and Stub.target.name, "Ragged Boar", "and stays left alone")

--[==[ **Feign death, which is the case this whole feature was written for --
     and which had never run.**

     `IsFeigning` opens with `if type(UnitBuff) ~= "function" then return false
     end`, and `UnitBuff` was not modelled at all. So feign detection answered
     "no" in every test there has ever been, and the retarget branch that reads
     it was only ever reached through its *other* condition, hostility.

     A hunter feigning is the reason somebody wants this. It is also the one case
     with no event and no unit flag: the only signature is the aura's icon on a
     player pretending to be a corpse. ]==]
GLOBAL_bs = string.char(92)

Stub.player.class = "HUNTER"
Stub.unitBuffs["target"] = { "Interface" .. GLOBAL_bs .. "Icons" .. GLOBAL_bs
        .. "Ability_Rogue_FeignDeath" }

Stub.player.hasTarget = true
Stub.target = { name = "Sylvie", isPlayer = true, class = "HUNTER" }

check(frames:IsFeigning("target"), "a hunter carrying the feign aura is feigning")

Stub.unitBuffs["target"] = { "Interface" .. GLOBAL_bs .. "Icons" .. GLOBAL_bs
        .. "Spell_Holy_WordFortitude" }
check(not frames:IsFeigning("target"),
        "and one carrying something else is not")

--[[ Only a hunter. Nobody else has the spell, and a rogue with a lookalike icon
     would otherwise read as feigning. ]]--
Stub.unitBuffs["target"] = { "Interface" .. GLOBAL_bs .. "Icons" .. GLOBAL_bs
        .. "Ability_Rogue_FeignDeath" }
Stub.target.class = "ROGUE"
check(not frames:IsFeigning("target"), "and no other class can feign at all")

Stub.target.class = "HUNTER"
Stub.unitBuffs["target"] = nil

--[==[ **The thing it is actually for, driven the way the client produces it.**

     This block used to clear the target and assert the player was taken back on
     the very next step. That passed only because **`ClearTarget` was not
     modelled** -- the give-up path called it, the call did nothing, and the
     target the step had just reacquired stayed put. On a real client that call
     works, so the behaviour under test never existed.

     The feature's own note says what the real path is: *failed once means the
     unit genuinely disappeared*. A Vanish, a Feign Death or an Invisibility
     takes the target away **and** makes them unfindable, so the first attempt
     fails -- and that failure is the whole signal. Reacquiring somebody who was
     there all along is not the feature; it is the Tab-targeting bug fixed
     twenty lines above, wearing a different hat. ]==]
Stub.player.hasTarget = false
Stub.target = nil
Stub.targetable["Sylvie"] = nil

frames:RetargetStep()

check(not Stub.player.hasTarget,
        "while they are really gone there is nothing to take back")
check(frames.retargetLost,
        "and the failed attempt is what marks it a disappearance")

--[[ The Vanish ends and they are findable again. ]]--
Stub.targetable["Sylvie"] = { name = "Sylvie", isPlayer = true, class = "PRIEST" }

frames:RetargetStep()

check(Stub.player.hasTarget, "so coming back is reacquired")
eq(Stub.target and Stub.target.name, "Sylvie", "as the player who was remembered")

--[==[ **And deselecting on purpose is left alone**, which is the case
     `ClearTarget` existing finally made reachable.

     Press Escape and the player you were on is still standing there, so
     `TargetByName` succeeds on the first attempt -- no failure, no
     disappearance, nothing to correct. The feature drops it again rather than
     dragging you back, on exactly the reasoning that fixed Tab-targeting: a
     target you chose, or chose to let go of, is not a problem. ]==]
Stub.player.hasTarget = true
Stub.target = { name = "Sylvie", isPlayer = true, class = "PRIEST" }
frames:RetargetStep()

eq(frames.retargetUnit, "Sylvie", "the player is remembered again")
check(not frames.retargetLost, "with no disappearance behind it")

Stub.player.hasTarget = false
Stub.target = nil

frames:RetargetStep()

check(not Stub.player.hasTarget,
        "letting a target go on purpose is not undone a frame later",
        tostring(Stub.target and Stub.target.name))

Stub.targetable["Sylvie"] = nil
Stub.player.hasTarget = false
Stub.target = nil
frames.retargetUnit = nil
frames.retargetDead = nil
frames.retargetLost = nil

cfg.retarget = false

-- ---------------------------------------------------------------------------
-- the five minutes after /pvp goes off
-- ---------------------------------------------------------------------------

--[==[ **Turning `/pvp` off does not unflag you**, and the interface never said
     so: the faction icon stays up for five minutes and nothing explains why.
     `GetPVPTimer` is the client's own source for it.

     **None of it had ever run.** `GetPVPTimer`, `UnitIsPVP` and the
     `PlayerPVPIcon` region were all unmodelled, so `UpdatePVPTimer` returned at
     its first guard in every test there has ever been -- three absent calls, one
     invisible feature. ]==]
GLOBAL_ufCfg = OB.profile.modules.unitframes
GLOBAL_replaceWas = GLOBAL_ufCfg.replacePlayer
GLOBAL_ufCfg.replacePlayer = true

Stub.pvp.flagged = false
frames:UpdatePVPTimer(true)

check(not (frames.pvpTimerText and frames.pvpTimerText:IsShown()),
        "not flagged is no countdown")

--[==[ **301000 is the sentinel for a permanent flag**, not five minutes and one
     second. A reader that took it at face value would draw a countdown that
     never moves for as long as somebody stays flagged -- which is most of the
     time, for most people who use `/pvp` at all. ]==]
Stub.pvp.flagged = true
Stub.pvp.timer = 301000
frames:UpdatePVPTimer(true)

check(not (frames.pvpTimerText and frames.pvpTimerText:IsShown()),
        "and a permanent flag is not a countdown either")

--[==[ **Minutes and seconds, asked for as `4m59s` down to `1s`.** ]==]
Stub.pvp.timer = 299000
frames:UpdatePVPTimer(true)

check(frames.pvpTimerText and frames.pvpTimerText:IsShown(),
        "a real countdown is drawn")
eq(frames.pvpTimerText:GetText(), "4m59s", "in minutes and seconds",
        tostring(frames.pvpTimerText:GetText()))

Stub.pvp.timer = 61000
frames:UpdatePVPTimer(true)
eq(frames.pvpTimerText:GetText(), "1m01s",
        "with the seconds padded, so the string does not change width")

--[==[ **And the seconds keep their unit once the minutes are gone.**
     `OB.DurationText` drops it on purpose -- everything under a buff icon is
     seconds -- but this number sits under a faction icon among things that are
     not durations, so it says what it is. ]==]
Stub.pvp.timer = 59000
frames:UpdatePVPTimer(true)
eq(frames.pvpTimerText:GetText(), "59s", "under a minute it is seconds")

Stub.pvp.timer = 1000
frames:UpdatePVPTimer(true)
eq(frames.pvpTimerText:GetText(), "1s", "down to the last one")

--[==[ **It has a frame of its own, and somebody puts it where they want it.**

     Seven passes at placing this from here -- beside the icon, under it, further
     under, higher, from the icon's top, by the icon's height -- each one aimed at
     a frame this addon cannot see, and the last of them put the number *behind*
     the emblem. That is enough guessing.

     A `FontString` has no drag scripts, cannot be registered with edit mode and
     has nothing to outline; only a frame does. So the string lives in one, the
     same answer the minimap coordinates reached after the same argument. ]==]
GLOBAL_pvpFrame = frames:PVPTimerFrame()

check(GLOBAL_pvpFrame ~= nil, "the countdown has a frame of its own")
eq(frames.pvpTimerText:GetParent(), GLOBAL_pvpFrame, "and the string lives in it")

--[==[ **Part of the player frame, which is what keeps them together.** Parented
     to it and positioned from its top-left, so moving the player frame takes the
     countdown along and there is no second placement to keep in step. ]==]
eq(GLOBAL_pvpFrame:GetParent(), getglobal("PlayerFrame"),
        "parented to the player frame")

GLOBAL_pvpPoint, GLOBAL_pvpRel, GLOBAL_pvpRelPoint, GLOBAL_pvpOffX, GLOBAL_pvpOffY =
        GLOBAL_pvpFrame:GetPoint(1)

eq(GLOBAL_pvpPoint, "TOPLEFT", "anchored by its top-left")
eq(GLOBAL_pvpRel, getglobal("PlayerFrame"), "to the player frame's")

--[==[ **Above the faction icon.** The icon is the client's, drawn on the player
     frame, and a number on the same layer disappears behind the emblem -- which
     is what "the timer is gone" turned out to be. A level up draws over it
     whatever the client does to its own regions. ]==]
check(GLOBAL_pvpFrame:GetFrameLevel() > getglobal("PlayerFrame"):GetFrameLevel(),
        "and drawn above the frame the icon is on",
        tostring(GLOBAL_pvpFrame:GetFrameLevel()) .. " over "
                .. tostring(getglobal("PlayerFrame"):GetFrameLevel()))

--[==[ **The position is the setting, and the drag writes it**, so the sliders
     and the mouse are one position rather than two that drift. ]==]
GLOBAL_ufCfg.pvpTimerX = 120
GLOBAL_ufCfg.pvpTimerY = 60
frames:PlacePVPTimer()

GLOBAL_p2, GLOBAL_r2, GLOBAL_rp2, GLOBAL_x2, GLOBAL_y2 = GLOBAL_pvpFrame:GetPoint(1)

eq(GLOBAL_x2, 120, "the across setting places it", tostring(GLOBAL_x2))
eq(GLOBAL_y2, -60, "and the down one", tostring(GLOBAL_y2))

--[==[ **Fixed where it is, and out of edit mode.**

     It was draggable for a release -- which is the standing answer for a
     placement somebody has questioned -- and here the placement got settled by
     hand and the machinery was asked to go: *lock current position, remove it
     from edit mode.* Fair. Edit mode is a list of things worth arranging, and a
     thing that is already where it belongs is clutter on it.

     **So it takes no mouse at all**, and that is not incidental. This frame sits
     over the player frame, and a frame holding the mouse with nothing to do with
     it eats clicks meant for whatever is underneath -- the fault three separate
     reports have been traced to. Nothing to drag means nothing to hold. ]==]
check(not GLOBAL_pvpFrame:IsMouseEnabled(),
        "it takes no clicks from the frame it sits over")
check(not GLOBAL_pvpFrame:IsMovable(), "and is not movable")

OB.SetEditMode(true)
check(not GLOBAL_pvpFrame:IsMouseEnabled(),
        "not even in edit mode, because there is nothing to grab it for")
OB.SetEditMode(false)

--[==[ **And a switch of its own**, asked for in the player frame's options.
     There is a coherent player on both sides -- the five minutes after `/pvp`
     matters if you are trying to stop being flagged and is noise if you never
     turn it off -- which is what makes it a setting rather than a default. ]==]
eq(GLOBAL_ufCfg.showPVPTimer, true, "the countdown is on by default")

GLOBAL_ufCfg.showPVPTimer = false
frames:UpdatePVPTimer(true)

check(not frames.pvpTimerText:IsShown(), "switched off, nothing is drawn")

GLOBAL_ufCfg.showPVPTimer = true
frames:UpdatePVPTimer(true)
check(frames.pvpTimerText:IsShown(), "and back on it returns")

GLOBAL_ufCfg.pvpTimerX = nil
GLOBAL_ufCfg.pvpTimerY = nil
frames:PlacePVPTimer()

--[==[ **Ten, and outlined.**

     Six was the first pass and was never looked at in game; eight was still
     small against the frame art beside it. The size is taste and the reason it
     kept changing is that nobody had seen it.

     The outline is not taste. The gap beside the portrait is the player frame's
     own carved metal rather than a flat panel, and unoutlined text over that
     does not read as plainer -- it disappears into whichever bit of the
     engraving it lands on. The nameplates force an outline on their own text for
     exactly this reason; this is the same argument with metal in place of
     terrain, which is why it is forced rather than following the profile. ]==]
GLOBAL_pvpFont, GLOBAL_pvpFontSize, GLOBAL_pvpFontFlags =
        frames.pvpTimerText:GetFont()

eq(GLOBAL_pvpFontSize, 10, "and readable at ten point",
        tostring(GLOBAL_pvpFontSize))

check(string.find(tostring(GLOBAL_pvpFontFlags or ""), "OUTLINE", 1, true) ~= nil,
        "with an outline, because it is drawn onto artwork",
        tostring(GLOBAL_pvpFontFlags))

--[[ Expired, and it goes. ]]--
Stub.pvp.timer = 0
frames:UpdatePVPTimer(true)
check(not frames.pvpTimerText:IsShown(), "and it goes when the grace runs out")

--[[ The formatter on its own, since it is the part somebody will read back. ]]--
eq(frames:PVPTimerFormat(300), "5m00s", "five minutes exactly")
eq(frames:PVPTimerFormat(60), "1m00s", "one minute exactly")
eq(frames:PVPTimerFormat(0), "0s", "and nothing left is still seconds")

-- ---------------------------------------------------------------------------
-- and on a build that has no GetPVPTimer at all
-- ---------------------------------------------------------------------------

--[==[ **Ollie's client does not export `GetPVPTimer`.**

     `/eq pvpdebug` answers `GetPVPTimer: nil` while `UnitIsPVP("player")` is
     `1` -- flagged, and no call to ask how long is left. It is standard 1.12
     API and this fork simply does not have it, so no amount of reading it
     differently helps.

     **What is observable is the flag.** Turning `/pvp` off does not unflag you:
     `UnitIsPVP` stays true and `PLAYER_FLAGS_CHANGED` fires. A flag change that
     leaves you still flagged is the grace starting; the flag going false is it
     ending, which is also the confirmation that makes a wrong start
     self-correcting. ]==]
GLOBAL_realPVPTimer = GetPVPTimer
GetPVPTimer = nil

Stub.pvp.flagged = true
Stub.player.afk = nil
Stub.player.dnd = nil
frames:ClearPVPGrace()

--[[ Freshly flagged: no countdown, because nothing is running out. ]]--
frames.pvpWasFlagged = false
frames:NotePVPFlags()

check(frames:PVPGraceStart() == nil, "flagging up starts no countdown")

--[[ Now the toggle: the flag changes and you are still flagged. ]]--
frames:NotePVPFlags()

check(frames:PVPGraceStart() ~= nil, "toggling it off starts the five minutes")

frames:UpdatePVPTimer(true)
check(frames.pvpTimerText:IsShown(), "and the countdown is drawn")
eq(frames.pvpTimerText:GetText(), "5m00s", "starting at five minutes",
        tostring(frames.pvpTimerText:GetText()))

--[==[ **Time really passing**, which needs a clock a test can move -- `time` is
     the wall clock and was `os.time` straight through. ]==]
Stub.clockOffset = 241
frames:UpdatePVPTimer(true)
eq(frames.pvpTimerText:GetText(), "59s", "and counting down as it runs")

--[==[ **Run out while still flagged means the start was wrong**, so it is
     forgotten rather than left showing a number that has stopped meaning
     anything. ]==]
Stub.clockOffset = 400
frames:UpdatePVPTimer(true)

check(not frames.pvpTimerText:IsShown(), "a countdown that runs out goes")
check(frames:PVPGraceStart() == nil, "and is forgotten, not left running")

--[==[ **`PLAYER_FLAGS_CHANGED` also fires for away and busy**, which would
     otherwise start a five-minute countdown for somebody going to make tea. ]==]
Stub.clockOffset = 0
frames:ClearPVPGrace()
frames.pvpWasFlagged = true
frames.pvpWasAfk = false
Stub.player.afk = true

frames:NotePVPFlags()
check(frames:PVPGraceStart() == nil, "going away is not a PvP toggle")

Stub.player.afk = nil
frames:NotePVPFlags()
check(frames:PVPGraceStart() == nil, "and neither is coming back")

--[[ Unflagging clears it outright: the grace ended. ]]--
frames:NotePVPFlags()
check(frames:PVPGraceStart() ~= nil, "a real toggle still starts it")

Stub.pvp.flagged = false
frames:NotePVPFlags()
check(frames:PVPGraceStart() == nil, "and dropping the flag ends it")

--[==[ **Kept on the profile as a wall-clock time**, so a reload in the middle of
     it does not restart the five minutes. `GetTime` would be useless here -- it
     is seconds since the client started, which is the mistake the mail
     autocomplete made for years. ]==]
Stub.pvp.flagged = true
frames.pvpWasFlagged = true
frames:NotePVPFlags()

--[==[ **Kept as state rather than as a setting.** The profile survives a reload,
     which is what this needs -- and it is also what a **share code** exports, and
     the pruner deliberately keeps a key it has never heard of. Somebody's PvP
     grace timestamp would have ridden along into everybody they gave a profile
     to. `EquadisClassicOverhaulDB` is where this addon already keeps facts
     rather than preferences, and none of that is exported. ]==]
check(frames:PVPGraceStart() > 1000000000,
        "the start is stored as a date, not as client uptime",
        tostring(frames:PVPGraceStart()))

check(OB.profile.pvpGraceAt == nil,
        "and not on the profile, which is what share codes carry")

check(EquadisClassicOverhaulDB.pvpGrace ~= nil,
        "it lives with the other facts this addon keeps")

--[==[ **And a client that does answer is believed over our arithmetic.** ]==]
GetPVPTimer = GLOBAL_realPVPTimer
Stub.pvp.timer = 120000
frames:UpdatePVPTimer(true)

eq(frames.pvpTimerText:GetText(), "2m00s",
        "where the client can answer, the client wins",
        tostring(frames.pvpTimerText:GetText()))

Stub.clockOffset = 0
frames:ClearPVPGrace()
Stub.pvp.flagged = false
Stub.pvp.timer = 301000
GLOBAL_ufCfg.replacePlayer = GLOBAL_replaceWas
frames:UpdatePVPTimer(true)

-- ---------------------------------------------------------------------------
-- and it does not redraw for units it never draws
-- ---------------------------------------------------------------------------

--[[ **This was the largest source of stutter in the addon.**

     `UNIT_HEALTH`, `UNIT_MANA` and `UNIT_AURA` fire for every unit the client
     knows about. In a raid that is forty people's health ticking continuously,
     and every single one of those events reached `Apply` -- which restyles all
     eight frames, re-reads the config and walks the party list twice, to redraw
     nothing at all, because `raid23` is not on screen here.

     Worse, each pass built four fresh party entry tables with seven
     concatenated strings each. On 1.12 that cost is not paid in CPU when you
     make it; it is paid later, all at once, as the garbage collection pause
     that reads as the game hitching. The game's own profiler had
     `EquadisClassicOverhaulHUD:OnUpdate` at the top of the list. ]]--
check(frames:DrawsUnit("player"), "the player is drawn here")
check(frames:DrawsUnit("target"), "and the target")
--[[ **Not the party.** It asserted the opposite six lines above the comment
     explaining why party frames are their own subsystem now -- two tests in one
     file disagreeing about the same thing, and only one of them could pass. ]]--
check(not frames:DrawsUnit("party3"), "and not the party, which has its own")
check(frames:DrawsUnit("pet"), "and the pet")

-- Party frames are their own Party & Raid Frames subsystem now. UnitFrames
-- must not redraw or hook them or the two modules fight over the same Blizzard
-- objects (the source of the duplicate group-frame text/visibility bugs).
check(not frames:DrawsUnit("party2"), "a party member belongs to group frames, not UnitFrames")
check(not frames:DrawsUnit("raid23"), "a raid member is not")
check(not frames:DrawsUnit("partypet2"), "nor a party pet")
check(not frames:DrawsUnit("mouseover"), "nor whatever is under the cursor")
check(not frames:DrawsUnit(nil), "and no unit at all is not a unit")

--[[ Counted through `Apply`, which is the expensive half. ]]--
GLOBAL_applies = 0
GLOBAL_realApply = frames.Apply
frames.Apply = function(self)
    GLOBAL_applies = GLOBAL_applies + 1
    return GLOBAL_realApply(self)
end

event, arg1 = "UNIT_HEALTH", "raid23"
frames:OnEvent()
eq(GLOBAL_applies, 0, "a raid member's health tick redraws nothing")

event, arg1 = "UNIT_MANA", "raid7"
frames:OnEvent()
eq(GLOBAL_applies, 0, "nor their mana")

--[==[ **A unit this module draws still does not earn a restyle.**

     `Apply` restores anything given back, redoes the geometry of all four
     frames, restyles their art and fonts, repaints the glow, the pet's
     happiness, the target's auras and both cast bars. That is the right answer
     when a *setting* changed and a very expensive one when a health bar moved --
     and in a raid your own health moves constantly. A profile of eighty-three
     seconds showed thirteen thousand events reaching this handler and thirty-one
     megabytes of garbage behind them.

     Art does not change because somebody took damage. So a value event writes
     the numbers on the frame that changed and stops. ]==]
event, arg1 = "UNIT_HEALTH", "player"
frames:OnEvent()
eq(GLOBAL_applies, 0, "your own health writes the numbers rather than restyling")

--[==[ It is a fast path, not a dropped event: the frame that changed is still
     the frame that gets written. ]==]
check(frames:EntryForUnit("player") ~= nil, "and it knows which frame that was")
eq(frames:EntryForUnit("party2"), nil, "while a unit it does not draw has none")

event, arg1 = "UNIT_HEALTH", "party2"
frames:OnEvent()
eq(GLOBAL_applies, 0, "a party member still redraws nothing at all")

--[==[ **An aura takes the long way**, because a buff arriving really can change
     what a frame draws -- the aura row, a dispel outline, the target's cast
     bar. ]==]
event, arg1 = "UNIT_AURA", "target"
frames:OnEvent()
eq(GLOBAL_applies, 1, "an aura on a drawn unit still restyles")

--[[ **An event with no unit concerns every frame** and must not be filtered.
     `arg1` is only set by the `UNIT_*` events; entering the world or the party
     changing genuinely does mean redraw everything. ]]--
event, arg1 = "PARTY_MEMBERS_CHANGED", nil
frames:OnEvent()
eq(GLOBAL_applies, 2, "an event about no unit in particular still applies")

frames.Apply = GLOBAL_realApply
event, arg1 = nil, nil

--[[ **The party entries are built once**, not rebuilt on every pass. Four
     tables and twenty-eight concatenated strings, describing frames whose names
     have not changed since the client was written. ]]--
GLOBAL_entryA = frames:PartyEntry(2)
GLOBAL_entryB = frames:PartyEntry(2)
eq(GLOBAL_entryA, GLOBAL_entryB, "asking twice gives back the same table")
eq(GLOBAL_entryA.frame, "PartyMemberFrame2", "with the right frame on it")
eq(GLOBAL_entryA.health, "PartyMemberFrame2HealthBar", "and the right bars")
check(frames:PartyEntry(3) ~= GLOBAL_entryA, "and each member gets its own")

-- Kept as a compatibility descriptor only: even an old profile carrying the
-- removed replaceParty key cannot make UnitFrames take those objects back.
OB.profile.modules.unitframes.replaceParty = true
check(not frames:Owns(GLOBAL_entryA), "UnitFrames never owns party frames now")

-- ---------------------------------------------------------------------------
-- where the frame art comes from
-- ---------------------------------------------------------------------------

--[[ **This module is a port, and the port kept looking for its art under the
     name of the addon it was ported *from*.**

     `UnitFramesImproved_Vanilla` is one name the asset tree ships under.
     `EquadisUnitFrames` is the fork this project is merging in and carries the
     same `Textures\`, so an install running the fork -- as the author's does --
     failed the probe, and every custom frame texture, the status glow and the
     entire target aura skin fell back to stock Blizzard art. No error, no
     warning: the module simply looked like it was not doing anything, which is
     exactly how it was reported. ]]--
Stub.player.hasTarget = true
Stub.target = { name = "Kobold", isPlayer = false, class = "WARRIOR" }
OB.profile.modulesEnabled.unitframes = true
OB.BindSlots()

frames:Apply()
GLOBAL_targetArt = getglobal("TargetFrameTexture").texture

check(GLOBAL_targetArt ~= nil, "the target frame gets a texture")
--[[ **From this addon's own folder**, which is the point of bundling it.

     This asked for `EquadisUnitFrames` in the path -- the neighbour whose
     art this is. That was right while the art was read out of its folder,
     and it is exactly the dependency that made the frames change when
     somebody uninstalled it. The files ship here now, under their MIT
     licence with the notice kept beside them. ]]--
check(string.find(GLOBAL_targetArt or "", "EquadisClassicOverhaul", 1, true) ~= nil,
        "taken from this addon's own textures, not another addon's folder")

--[[ The aura skin is the part that vanished completely rather than degrading:
     it has no stock fallback, so a failed probe meant no border at all. ]]--
check(frames:StyleTargetAuras(), "and the target aura skin has assets to use")

--[[ **The art follows compact alone, and dark mode is a tint over it.**

     This asserted four art files chosen by compact *and* dark, on the reasoning
     that the addon whose art this is swaps files rather than tinting. Its source
     does exactly that -- and it is still the wrong thing to do here, because the
     files on this install are not light and dark pairs of one design:

         UI-TargetingFrame.blp      44884 bytes  b1e7994c...
         darkUI-TargetingFrame.blp  88552 bytes  27730d42...
         newUI-TargetingFrame.blp   88552 bytes  27730d42...

     `darkUI` is byte-identical to `newUI`. Asking for dark art hands back the
     *new* frame, a wider layout drawn for different bars, and the classic bars
     then sit inside a frame that carries on past them -- reported, correctly,
     as the border being too big.

     A tint cannot be wrong about a layout, because it does not change one. ]]--
GLOBAL_ufCfg = OB.profile.modules.unitframes
GLOBAL_ufDark = GLOBAL_ufCfg.darkMode
GLOBAL_ufCompact = GLOBAL_ufCfg.frameMode

GLOBAL_ufCfg.frameMode = "overhaul"
GLOBAL_ufCfg.darkMode = false
eq(frames:UFIFramePrefix(), "UI", "plain asks for the plain art")

GLOBAL_ufCfg.darkMode = true
eq(frames:UFIFramePrefix(), "UI", "and dark asks for the same art, not another")

GLOBAL_ufCfg.frameMode = "compact"
eq(frames:UFIFramePrefix(), "compactUI", "compact asks for the compact art")

GLOBAL_ufCfg.darkMode = false
eq(frames:UFIFramePrefix(), "compactUI", "dark or not")

--[[ Dark is the tint, and it is applied to whatever that art turned out to
     be. ]]--
GLOBAL_ufCfg.frameMode = "overhaul"
GLOBAL_ufCfg.darkMode = true
frames:Apply()

GLOBAL_playerArt = getglobal("PlayerFrameTexture")
check(string.find(GLOBAL_playerArt.texture or "", "darkUI", 1, true) == nil,
        "the dark file is never asked for", tostring(GLOBAL_playerArt.texture))
check(GLOBAL_playerArt.vertex and GLOBAL_playerArt.vertex[1] < 1,
        "and dark mode shows up as a tint instead",
        GLOBAL_playerArt.vertex and tostring(GLOBAL_playerArt.vertex[1]) or "unset")

GLOBAL_ufCfg.darkMode = false
frames:Apply()

check(GLOBAL_playerArt.vertex and GLOBAL_playerArt.vertex[1] == 1,
        "and switching it off leaves the art alone",
        GLOBAL_playerArt.vertex and tostring(GLOBAL_playerArt.vertex[1]) or "unset")

GLOBAL_ufCfg.darkMode = GLOBAL_ufDark
GLOBAL_ufCfg.frameMode = GLOBAL_ufCompact

GLOBAL_ufCfg.darkMode = GLOBAL_ufDark
GLOBAL_ufCfg.frameMode = GLOBAL_ufCompact

-- ---------------------------------------------------------------------------
-- who owns the target frame's art
-- ---------------------------------------------------------------------------

--[[ **`TargetFrame_CheckClassification` belongs to the client, and it writes
     the texture straight back to Blizzard's.**

     It is not a one-off at login -- the client calls it on every target change
     -- so styling the texture from `Apply` alone is a race this module wins
     only by happening to run second. Taking the function is how every other
     addon that restyles this frame does it, the standalone included. ]]--
check(type(TargetFrame_CheckClassification) == "function",
        "the classification hook exists")
check(EquadisOverhaulBlizzClassification ~= nil, "and the client's is kept")

getglobal("TargetFrameTexture").texture = "Interface\\TargetingFrame\\UI-TargetingFrame"
TargetFrame_CheckClassification()
check(string.find(getglobal("TargetFrameTexture").texture or "",
        "EquadisClassicOverhaul", 1, true) ~= nil,
        "so a target change repaints the frame as ours, not Blizzard's")

--[[ Classification still comes from `StyleFrameArt`, so Compact, Dark and the
     shared border tint keep applying -- one source of truth for the look. ]]--
Stub.classification = "rareelite"
TargetFrame_CheckClassification()
check(string.find(getglobal("TargetFrameTexture").texture or "",
        "Rare-Elite", 1, true) ~= nil, "and an elite still reads as an elite")
Stub.classification = "normal"

--[[ Handed back when the frame is not ours, or switching the module off would
     leave the target frame stuck on whatever was last painted with nothing
     left alive to repaint it. ]]--
GLOBAL_ufTarget = OB.profile.modules.unitframes.replaceTarget
OB.profile.modules.unitframes.replaceTarget = false
getglobal("TargetFrameTexture").texture = nil
TargetFrame_CheckClassification()
check(getglobal("TargetFrameTexture").texture == nil
        or string.find(getglobal("TargetFrameTexture").texture, "EquadisUnitFrames", 1, true) == nil,
        "with the target frame unticked the client gets its function back")
OB.profile.modules.unitframes.replaceTarget = GLOBAL_ufTarget

Stub.target = nil
Stub.player.hasTarget = false
OB.profile.modulesEnabled.unitframes = true
OB.BindSlots()

--[[ **The target-of-target frame follows the target frame.**

     `StyleTargetTargetGeometry` moved the portrait and never the frame, so
     whatever last re-anchored `TargetofTargetFrame` -- another unit frame addon,
     or a drag in edit mode, both of which anchor to UIParent at an absolute
     screen position -- was left standing. `/eq frames` reported it anchored to
     nothing recognisable at (1372, -601) while every other frame named its
     parent, which is the whole of "target of target is partially bugged".

     Put back to the anchor the client itself had, captured before anything was
     touched, rather than to offsets invented here. ]]--
GLOBAL_tot = getglobal("TargetofTargetFrame")

if GLOBAL_tot then
    GLOBAL_totCfg = OB.profile.modules.unitframes
    GLOBAL_totCfg.positions = GLOBAL_totCfg.positions or {}
    GLOBAL_totCfg.positions.TargetofTargetFrame = nil

    --[[ Dragged off to a corner of the screen, which is what a drag leaves
         behind: anchored to UIParent rather than to the frame it belongs to. ]]--
    GLOBAL_tot:ClearAllPoints()
    GLOBAL_tot:SetPoint("TOPLEFT", UIParent, "TOPLEFT", 1372, -601)

    frames:StyleTargetTargetGeometry()

    GLOBAL_totPoint = { GLOBAL_tot:GetPoint() }

    check(GLOBAL_totPoint[1] ~= "TOPLEFT" or GLOBAL_totPoint[4] ~= 1372,
            "a stranded target-of-target frame is put back",
            tostring(GLOBAL_totPoint[1]) .. " " .. tostring(GLOBAL_totPoint[4]))

    --[[ **But a position somebody chose is left alone.** Restoring over a saved
         position would undo the drag on the next style pass, which is the same
         bug in the other direction. ]]--
    GLOBAL_totCfg.positions.TargetofTargetFrame = { x = 120, y = -40 }

    GLOBAL_tot:ClearAllPoints()
    GLOBAL_tot:SetPoint("CENTER", UIParent, "CENTER", 120, -40)

    frames:StyleTargetTargetGeometry()

    GLOBAL_totPoint = { GLOBAL_tot:GetPoint() }
    eq(GLOBAL_totPoint[1], "CENTER", "a saved position survives a style pass")
    eq(GLOBAL_totPoint[4], 120, "at the coordinates it was saved at")

    GLOBAL_totCfg.positions.TargetofTargetFrame = nil
end

--[[ **A frame edit mode can move is a frame whose position is kept.** The
     target-of-target and pet frames were draggable and unsaved, so moving one
     worked until the next reload and then undid itself -- which is worse than
     not being draggable, because it looks like the addon forgetting. ]]--
GLOBAL_ufSaved = {}

for GLOBAL_i = 1, table.getn(OB.movables or {}) do
    local entry = OB.movables[GLOBAL_i]
    local name = entry.frame and entry.frame.GetName and entry.frame:GetName()
    if name then GLOBAL_ufSaved[name] = true end
end

frames:SetDragMode(true)

GLOBAL_ufMovable = {}

for GLOBAL_i = 1, table.getn(OB.movables or {}) do
    local entry = OB.movables[GLOBAL_i]
    local name = entry.frame and entry.frame.GetName and entry.frame:GetName()
    if name then GLOBAL_ufMovable[name] = true end
end

--[==[ **Whichever of the two is on screen**, which is not always the client's.

     This named `TargetofTargetFrame` and `PetFrame` outright. When this module
     draws its own target-of-target and pet it hides the client's, so that
     asserted a hidden frame was draggable -- which it was, uselessly, while the
     frame you can actually see was not in the list at all.

     Resolved the same way the module resolves it, so the test cannot drift from
     the rule it is checking. ]==]
GLOBAL_totName = frames:OwnsSmall("targettarget")
        and "EquadisClassicOverhaulToT" or "TargetofTargetFrame"
GLOBAL_petName = frames:OwnsSmall("pet")
        and "EquadisClassicOverhaulPet" or "PetFrame"

check(GLOBAL_ufMovable[GLOBAL_totName] == true,
        "target of target can be dragged", GLOBAL_totName)
check(GLOBAL_ufMovable[GLOBAL_petName] == true,
        "and so can the pet frame", GLOBAL_petName)

--[[ Dropped somewhere, and the drop is what has to survive. ]]--
GLOBAL_tot = getglobal(GLOBAL_totName)
GLOBAL_tot:ClearAllPoints()
GLOBAL_tot:SetPoint("CENTER", UIParent, "CENTER", 200, 150)

frames:StorePosition(GLOBAL_tot)

check(OB.profile.modules.unitframes.positions[GLOBAL_totName] ~= nil,
        "and where it was dropped is written down")

--[[ Which is only half of it: `PlaceFrames` is the half that runs on the next
     login, and it walked a list of two.

     It reads the same resolver as the drag registration, which is the point of
     having one: a saved position and the frame it belongs to cannot disagree
     about which of the two they mean. ]]--
GLOBAL_tot:ClearAllPoints()
GLOBAL_tot:SetPoint("TOPLEFT", UIParent, "TOPLEFT", 0, 0)

frames:PlaceFrames()

GLOBAL_totPoint = { GLOBAL_tot:GetPoint() }
eq(GLOBAL_totPoint[1], "CENTER", "and put back on the next login")

frames:SetDragMode(false)
OB.profile.modules.unitframes.positions[GLOBAL_totName] = nil

--[[ **The numbers are not cut off.**

     Blizzard's font strings carry a width from XML sized for Blizzard's own
     format. The default format here is the longest offered -- `3.3k/3.3k
     (100%)` -- and it arrived on screen as `3.3k/3.3k...`, which reads as the
     addon failing to work out a number it had worked out correctly. ]]--
GLOBAL_bar = getglobal("PlayerFrameHealthBar")

if GLOBAL_bar then
    GLOBAL_barText = frames:BarTextString(getglobal("PlayerFrameHealthBar"))
    GLOBAL_bar:SetWidth(119)

    if GLOBAL_barText then
        GLOBAL_barText:SetWidth(40)

        frames:StyleBar(GLOBAL_bar, 12, 0, 0, nil)

        eq(GLOBAL_barText:GetWidth(), 119,
                "the health text is as wide as the bar it sits on")
    end
end


end

unitFrameTests()

-- 45b. the addons this one has absorbed
--
-- An all-in-one merging other addons in has to notice when the addon it
-- replaced is still switched on, because two addons that both restyle a frame
-- do not share it -- they race, and the loser's settings quietly stop changing
-- pixels.
-- ---------------------------------------------------------------------------

function conflictTests()

context = "addon conflicts: "

EquadisClassicOverhaulDB = nil
OB = boot("ROGUE", 3, { loadedAddons = { EquadisUnitFrames = true } })

--[[ Nothing is said while the module that would fight it is switched off.
     Somebody who has deliberately kept the standalone and turned ECO's Unit
     Frames off has not got a conflict; they have got a choice. ]]--
--[==[ **Switched off here rather than relied on as a default.**

     This rested on unit frames shipping off, which they no longer do -- see
     "feature modules". What the assertion is actually about survives that: a
     loaded ancestor is not a conflict while the module it would fight is off,
     because somebody who kept the standalone and turned ECO's copy off has made
     a choice rather than a mistake. ]==]
OB.profile.modulesEnabled.unitframes = false
OB.BindSlots()

eq(OB.ModuleEnabled("unitframes"), false, "with unit frames switched off")
eq(table.getn(OB.ConflictingAddOns()), 0, "a loaded ancestor is not a conflict yet")

OB.profile.modulesEnabled.unitframes = true
OB.BindSlots()

GLOBAL_clashes = OB.ConflictingAddOns()
eq(table.getn(GLOBAL_clashes), 1, "switch the module on and the clash is real")
eq(GLOBAL_clashes[1] and GLOBAL_clashes[1].addon, "EquadisUnitFrames",
        "named so it can be turned off")

--[[ Loaded is the test, not installed. The art probe deliberately accepts an
     installed-but-disabled addon -- that is where the textures live -- so the
     two questions must not share an answer. ]]--
Stub.loadedAddons = {}

--[[ **One addon can fight several modules at once, and each is named.**

     DragonflightUI-Reforged has its own unit frames, action bars, map, chat,
     bags and party frames. It was registered here against unit frames alone --
     while the comment beside it said "unit frames *and action bars*", so the
     sentence knew about a conflict the data did not and nothing was ever said
     about the bars.

     Two addons hooking one frame do not error. The loser stops changing pixels,
     which reads as "that module is broken" rather than as a fight. ]]--
Stub.loadedAddons = { ["DragonflightUI-Reforged"] = true }

--[==[ **Every module this addon is registered against, read from the
     registry rather than listed here.**

     It was four names written out, and the list went stale the moment a fifth
     entry was added -- which is exactly the failure the entry itself was added
     to fix: the comment beside `supersededAddOns` records that the data once
     said "unit frames" while the sentence beside it said "unit frames and
     action bars", so nothing was ever said about the bars.

     A test that hand-copies that list inherits the same fault one layer up. It
     is derived now, so a sixth entry is covered the day it is written. ]==]
for GLOBAL_i = 1, table.getn(OB.supersededAddOns) do
    GLOBAL_entry = OB.supersededAddOns[GLOBAL_i]

    if GLOBAL_entry.addon == "DragonflightUI-Reforged" and GLOBAL_entry.feature then
        OB.profile.modulesEnabled[GLOBAL_entry.feature] = false
    end
end

OB.BindSlots()

eq(table.getn(OB.ConflictingAddOns()), 0,
        "nothing is said while every module it would fight is off")

OB.profile.modulesEnabled.actionbars = true
OB.BindSlots()

GLOBAL_barClash = OB.ConflictingAddOns()
eq(table.getn(GLOBAL_barClash), 1, "switching the bars on is a clash of its own")
eq(GLOBAL_barClash[1] and GLOBAL_barClash[1].label, "Action Bars",
        "named as the bars rather than as the addon in general")

--[[ **Both at once are two warnings**, because turning one module off does not
     settle the other and a single line could only name one of them. ]]--
OB.profile.modulesEnabled.map = true
OB.BindSlots()

eq(table.getn(OB.ConflictingAddOns()), 2, "two modules fighting is two warnings")

GLOBAL_labels = {}
GLOBAL_found = OB.ConflictingAddOns()

for GLOBAL_i = 1, table.getn(GLOBAL_found) do
    GLOBAL_labels[GLOBAL_found[GLOBAL_i].label] = true
end

check(GLOBAL_labels["Action Bars"] and GLOBAL_labels["Map"],
        "each naming the part of ECO being fought over")

--[[ **A modular neighbour is asked which parts are switched on.**

     ShaguTweaks is a bundle of small mods, and one of them -- "Movable Unit
     Frames" -- watches for Shift and Control held together and makes
     `PlayerFrame` and `TargetFrame` draggable while they are.

     That collides with this addon twice: ECO's edit mode gesture is
     Control-Shift-Alt, which *contains* Control-Shift, and ECO owns whether
     those frames are movable, so their `StartMoving` lands on a locked frame
     and throws.

     Warning about the whole of ShaguTweaks would be wrong for everybody who has
     already turned that one piece off -- and a warning that is wrong is a
     warning people stop reading. ]]--
Stub.loadedAddons = { ShaguTweaks = true }
OB.profile.modulesEnabled.unitframes = true
OB.BindSlots()

ShaguTweaks_config = nil
eq(table.getn(OB.ConflictingAddOns()), 0,
        "a bundle whose settings cannot be read is not accused")

ShaguTweaks_config = { ["Movable Unit Frames"] = 0 }
eq(table.getn(OB.ConflictingAddOns()), 0,
        "nor one whose conflicting mod is already switched off")

ShaguTweaks_config = { ["Movable Unit Frames"] = 1 }
GLOBAL_shagu = OB.ConflictingAddOns()

eq(table.getn(GLOBAL_shagu), 1, "but the mod being on is a real conflict")
eq(GLOBAL_shagu[1] and GLOBAL_shagu[1].addon, "ShaguTweaks", "named so it can be found")

--[[ And it is still gated on ECO's own module: somebody who has deliberately
     left unit frames to ShaguTweaks has made a choice, not a mistake. ]]--
OB.profile.modulesEnabled.unitframes = false
eq(table.getn(OB.ConflictingAddOns()), 0,
        "and nothing is said when ECO's own module is off")

OB.profile.modulesEnabled.unitframes = true
ShaguTweaks_config = nil
Stub.loadedAddons = {}
OB.BindSlots()

OB.profile.modulesEnabled.actionbars = false

--[[ Unit frames back on, which is how this section was found. The block above
     turned three modules off to test them one at a time and put only two back,
     and the warning test below -- three thousand lines into the file and
     nothing to do with any of them -- reported that a conflict it had set up
     itself was not a conflict. ]]--
OB.profile.modulesEnabled.unitframes = true

OB.profile.modulesEnabled.map = false
Stub.loadedAddons = {}
OB.BindSlots()
eq(table.getn(OB.ConflictingAddOns()), 0,
        "and an addon that is merely installed is not fighting anybody")

--[[ Once a session. PLAYER_ENTERING_WORLD fires again on every loading screen,
     and a warning that reprints each time you zone is one people learn to
     scroll past. ]]--
Stub.loadedAddons = { EquadisUnitFrames = true }
OB.conflictsWarned = nil
check(OB.WarnConflicts(), "the warning is given")
check(not OB.WarnConflicts(), "and not given again on the next loading screen")

Stub.loadedAddons = {}
OB.profile.modulesEnabled.unitframes = true
OB.BindSlots()

end

conflictTests()

-- 46. the names the panel answers to
--
-- The addon was Equadis' OmniBars and is Equadis' Classic Overhaul. Both sets
-- are kept, because nobody should have to relearn a slash command because a
-- title changed.
-- ---------------------------------------------------------------------------

function slashNameTests()

context = "slash names: "
--[[ **Every name is named here individually**, including the historical ones.

     A sweep that rewrote `/eqob` to `/eq` across the addon rewrote it in this
     list too, and the assertion went on passing while the alias it was meant to
     protect no longer existed. A list that edits itself alongside the thing it
     checks is not a check. ]]--
wanted = { "/eq", "/eco", "/eqob", "/ob", "/omnibars", "/co", "/eqco",
           "/equadis", "/classicoverhaul" }

--[[ The two current names, kept apart from the historical ones because these
     are what the addon actually says in its own messages. ]]--
current = { "/eq", "/eco" }

registered = {}

for i = 1, 20 do
    local name = _G["SLASH_EQUADISOMNIBARS" .. i]
    if name then registered[name] = true end
end

missing = {}

for i = 1, table.getn(wanted) do
    if not registered[wanted[i]] then table.insert(missing, wanted[i]) end
end

eq(table.getn(missing), 0, "every name opens the panel",
        table.concat(missing, ", "))

--[[ **Numbered without a gap**, which is not a style point: the client stops
     reading at the first missing index, so `SLASH_X1` and `SLASH_X3` registers
     one command and silently drops the third. ]]--
gap = false
seenEnd = false

for i = 1, 20 do
    if _G["SLASH_EQUADISOMNIBARS" .. i] then
        if seenEnd then gap = true end
    else
        seenEnd = true
    end
end

check(not gap, "and the numbering has no hole for the client to stop at")

--[[ The handler is registered under the same key the names point at. A name
     with no handler is a command that silently does nothing. ]]--
check(SlashCmdList["EQUADISOMNIBARS"] ~= nil, "with a handler behind them")

--[[ **The two current names come first.**

     Not cosmetic: the client resolves a collision by keeping whichever addon
     registered a name last, and the order here is the order they register in.
     The names the addon tells people to type are the ones worth putting first. ]]--
for GLOBAL_i = 1, table.getn(current) do
    eq(_G["SLASH_EQUADISOMNIBARS" .. GLOBAL_i], current[GLOBAL_i],
            "the name it tells people to type is registered early")
end



-- ---------------------------------------------------------------------------
-- OB.Trim, which two commands called before it existed
-- ---------------------------------------------------------------------------

--[==[ **A defensive guard that quietly became the behaviour.**

     Both callers spelled it `OB.Trim and OB.Trim(msg) or msg` -- the shape that
     is meant to survive a helper being absent. It was absent, so the guard did
     not survive anything: it fell through to the untrimmed string every time
     and nothing said so.

     `/way clear ` with a trailing space did not match "clear". `/addfriend `
     with nothing after it would have written a friend whose name is a space.
     Neither is visible from reading the call, which is exactly the trouble with
     that idiom around a function nobody defined. ]==]
eq(OB.Trim("  Sylvie  "), "Sylvie", "spaces come off both ends")
eq(OB.Trim("Sylvie"), "Sylvie", "a clean string is left alone")
eq(OB.Trim("   "), "", "and whitespace alone trims to nothing")
eq(OB.Trim("a b"), "a b", "the space in the middle stays")
eq(OB.Trim(nil), "", "nothing at all is the empty string, not an error")
eq(OB.Trim(42), "", "and so is something that is not a string")

--[==[ **One return value, not two.**

     `string.gsub` answers the string *and* the number of substitutions it made.
     Returning the call directly hands back both -- harmless in
     `local x = Trim(s)` and not harmless at all in `table.insert(t, Trim(s))`,
     where a second value in the final argument position becomes a third
     argument and turns an append into an insert-at-index.

     Asserted by counting what comes back, because every other assertion here
     reads only the first one and would pass with the count trailing it. ]==]
GLOBAL_trimmed = { OB.Trim("  x  ") }
eq(table.getn(GLOBAL_trimmed), 1, "it answers with one value and no count")

-- ---------------------------------------------------------------------------
-- /addfriend
-- ---------------------------------------------------------------------------

--[==[ **The client has this and never says so.**

     1.12 ships `/friend` and mentions it nowhere: not in the social panel, not
     in the help, and the panel's own button opens a box to type into instead.
     Named for what it does rather than what it is called, because that is the
     word somebody reaches for. ]==]
eq(SLASH_EQUADISOVERHAULADDFRIEND1, "/addfriend", "the command is registered")
check(SlashCmdList["EQUADISOVERHAULADDFRIEND"] ~= nil,
        "with a handler behind it")

Stub.friends = {}
Stub.chat = {}

check(OB.AddFriendByName("Sylvie"), "a name given is added")
eq(GetNumFriends(), 1, "and lands on the list")
eq(GetFriendInfo(1), "Sylvie", "under the name that was typed")

--[[ Said out loud, because `AddFriend` is silent in both directions -- it
     answers nothing when it works and nothing when it does not. ]]--
GLOBAL_said = table.concat(Stub.chat, " ")
check(string.find(GLOBAL_said, "Sylvie", 1, true) ~= nil,
        "and the command says so", GLOBAL_said)

--[==[ **Twice is not an error, and that is the problem.**

     `AddFriend` on a name already on the list does nothing at all, which looks
     exactly like it having failed -- so somebody types it a third time. The
     match is case-insensitive because the typing will be, and the reply uses
     the spelling the *list* holds rather than the one typed. ]==]
Stub.chat = {}
eq(OB.AddFriendByName("sylvie"), false, "adding somebody twice does not")
eq(GetNumFriends(), 1, "the list is left alone")

GLOBAL_said = table.concat(Stub.chat, " ")
check(string.find(GLOBAL_said, "already", 1, true) ~= nil,
        "and it says they are already on it", GLOBAL_said)
check(string.find(GLOBAL_said, "Sylvie", 1, true) ~= nil,
        "spelled the way the list has it, not the way it was typed",
        GLOBAL_said)

--[==[ **A bare command means the target**, which is the case this gets typed
     in: somebody helpful in a group, already selected. ]==]
Stub.friends = {}
Stub.chat = {}
Stub.player.hasTarget = true
Stub.target = { name = "Grimtusk", isPlayer = true, friendly = true }

check(OB.AddFriendByName(""), "typed bare, it takes the target")
eq(GetFriendInfo(1), "Grimtusk", "and adds them")

--[[ Only a player: `AddFriend` on a mob's name writes a friend who can never
     come online, and nothing ever removes it. ]]--
Stub.friends = {}
Stub.chat = {}
Stub.target = { name = "Ragged Timber Wolf", isPlayer = false }

eq(OB.AddFriendByName(""), false, "a mob is not somebody to befriend")
eq(GetNumFriends(), 0, "and nothing is written")

--[[ And with nothing selected it asks rather than failing silently. ]]--
Stub.chat = {}
Stub.player.hasTarget = false
Stub.target = nil

eq(OB.AddFriendByName("  "), false, "nothing to go on is not an add")

GLOBAL_said = table.concat(Stub.chat, " ")
check(string.find(GLOBAL_said, "addfriend", 1, true) ~= nil,
        "and it says what it wanted", GLOBAL_said)

Stub.friends = {}

--[[ **Every command the handler advertises reaches something that exists.**

     `/eq perf` shipped pointing at `OB.ToggleProfile` on a build where the file
     defining it was newly added to the TOC -- and 1.12 does not reliably load a
     newly added file on `/reload`, so the command existed and the function did
     not. Typing it threw rather than saying so.

     The lesson is not about that one command. Anything the dispatcher calls
     through `OB.` is worth confirming is really there. ]]--
GLOBAL_entryPoints = {
    "ToggleProfile", "StartProfile", "StopProfile", "ReportProfile",
}

for GLOBAL_i = 1, table.getn(GLOBAL_entryPoints) do
    check(type(OB[GLOBAL_entryPoints[GLOBAL_i]]) == "function",
            "a command's target exists: " .. GLOBAL_entryPoints[GLOBAL_i])
end

--[[ **A command's target is never nil, whatever failed to load.**

     Guarding the one call site was not enough, and the reason is worth keeping:
     `/eq perf` threw on a build where `profiler.lua` had just been added to the
     TOC, because **1.12 does not reliably load a newly added file on
     `/reload`**. Adding a guard fixed that call and left the shape of the bug --
     the next command pointing at a file that did not load fails the same way.

     So core.lua defines every one of these up front and profiler.lua overwrites
     them. Load order changes the message, not whether it throws. ]]--
GLOBAL_fallbacks = {
    "ToggleProfile", "StartProfile", "StopProfile", "ReportProfile",
}

--[[ **A full boot proves nothing here**, which is the trap this test was
     written into once already: profiler.lua overwrites all four, so after a
     normal boot they are functions whether core.lua defines them or not. The
     assertion passed for a reason that had nothing to do with what it claimed.

     So the file is left out, and what boots is the build the player is actually
     sitting in. ]]--
GLOBAL_bare = boot("ROGUE", 3, { skipFiles = { ["profiler.lua"] = true } })
OB = GLOBAL_bare

check(not OB.profilerLoaded, "a build with profiler.lua missing knows it")

for GLOBAL_i = 1, table.getn(GLOBAL_fallbacks) do
    check(type(OB[GLOBAL_fallbacks[GLOBAL_i]]) == "function",
            "and still has: " .. GLOBAL_fallbacks[GLOBAL_i])
end

--[[ **And typing the command says so rather than throwing**, which is the whole
     point: a missing file is one restart away from working, and that is worth
     saying out loud. ]]--
GLOBAL_threw = false
GLOBAL_ok = pcall(function() SlashCmdList["EQUADISOMNIBARS"]("perf") end)
if not GLOBAL_ok then GLOBAL_threw = true end

check(not GLOBAL_threw, "and typing it explains itself rather than erroring")

--[[ `/eq doctor` says which file is missing, because the version string will
     not: the version lives in a file that did load. ]]--
Stub.chat = {}
SlashCmdList["EQUADISOMNIBARS"]("doctor")

GLOBAL_named = false
for GLOBAL_i = 1, table.getn(Stub.chat) do
    if string.find(Stub.chat[GLOBAL_i], "profiler", 1, true) then
        GLOBAL_named = true
    end
end

check(GLOBAL_named, "and doctor names the file that did not load")

--[[ Back to a whole addon, or every test after this one runs against a build
     with a file missing. ]]--
OB = boot("ROGUE", 3)
check(OB.profilerLoaded, "and a whole build records that the file loaded")

end

slashNameTests()

-- 47. the Escape menu button
--
-- Where somebody looks for settings when they have forgotten the slash command,
-- which is most people most of the time.
-- ---------------------------------------------------------------------------

function gameMenuTests()

context = "game menu: "

OB = boot("ROGUE", 3)

--[[ The button is already there -- logging in installs it -- so what is checked
     is the result rather than the transition. ]]--
menuButton = OB.InstallGameMenuButton()
check(menuButton ~= nil, "a button is added to the game menu")
eq(menuButton:GetText(), OB.addonName, "carrying the addon's name")

--[[ **Under Options**, which is where it was asked for and where anybody
     looking for settings looks second. ]]--
local _, anchoredTo = menuButton:GetPoint(1)
eq(anchoredTo, GameMenuButtonOptions, "directly under Options")

--[[ **A second button, for the addon list.**

     1.12 has no addon list once you are in the world -- the client's own is on
     the character-select screen -- so removing whichever addon was supplying one
     leaves a hole where people expect a button.

     Under the settings button rather than under Options, so ECO's pair stays
     together however many times this runs and whatever else has inserted itself
     into the menu meanwhile. ]]--
check(OB.gameMenuAddOns ~= nil, "and a second button for the addon list")
eq(OB.gameMenuAddOns:GetText(), "AddOns", "which says what it opens")

local _, addonsAnchor = OB.gameMenuAddOns:GetPoint(1)
eq(addonsAnchor, menuButton, "sitting directly under the settings button")

--[[ **And whatever was under Options moves below the pair**, or buttons sit on
     top of each other. Found by asking rather than by name: which button is
     there differs between clients, and a server may have added its own. ]]--
local _, keysAnchor = GameMenuButtonKeybindings:GetPoint(1)
eq(keysAnchor, OB.gameMenuAddOns, "and what was there moves below both")

--[[ Run twice on purpose. The namespace is rebuilt on a reload and the menu is
     not, so a guard that checked a field on `OB` would add a second copy of
     each button every time -- and the re-anchor would find nothing to move,
     because the first insertion already moved it. ]]--
local firstSettings, firstAddOns = OB.gameMenuButton, OB.gameMenuAddOns
OB.InstallGameMenuButton()
eq(OB.gameMenuButton, firstSettings, "installing again reuses the settings button")
eq(OB.gameMenuAddOns, firstAddOns, "and the addon list button")

local _, keysAgain = GameMenuButtonKeybindings:GetPoint(1)
eq(keysAgain, OB.gameMenuAddOns, "leaving the menu in one piece")

-- ---------------------------------------------------------------------------
-- and the addon list it opens
-- ---------------------------------------------------------------------------

--[[ Built from the client's own manifest rather than from a list of ours, so it
     is right about addons ECO has never heard of -- which is the whole job. ]]--
GLOBAL_addons = OB.AddOnRows()

--[[ Counted against the manifest rather than against a number written here, so
     adding an addon to the stub does not fail three assertions that are not
     about counting. ]]--
eq(table.getn(GLOBAL_addons), table.getn(Stub.addons),
        "every addon the client knows about is listed")

--[[ Sorted on the plain name, not the decorated title: a title beginning with a
     colour escape would sort under the escape rather than under its letter.
     Checked as an ordering over the whole list, which is the actual claim --
     naming the addon that happens to be last only tests the fixture. ]]--
eq(GLOBAL_addons[1].name, "Bagshui", "alphabetically by name")

GLOBAL_sorted = true
for GLOBAL_i = 2, table.getn(GLOBAL_addons) do
    local before, after = GLOBAL_addons[GLOBAL_i - 1], GLOBAL_addons[GLOBAL_i]
    --[[ Lowercased on both sides, because that is what the module sorts on:
         a raw comparison puts every capitalised name ahead of `pfUI`, which is
         the client's ordering rather than an alphabet anybody reads. ]]--
    if not before or not after
            or string.lower(before.name) > string.lower(after.name) then
        GLOBAL_sorted = false
    end
end
check(GLOBAL_sorted, "from end to end")

--[[ `enabled` is a *number* on 1.12, not a boolean, so it is read as truth
     rather than compared to `true`. ]]--
eq(GLOBAL_addons[1].enabled, true, "an enabled addon reads as enabled")

GLOBAL_off = nil
for GLOBAL_i = 1, table.getn(GLOBAL_addons) do
    if GLOBAL_addons[GLOBAL_i].name == "ShaguPlates" then
        GLOBAL_off = GLOBAL_addons[GLOBAL_i]
    end
end
eq(GLOBAL_off.enabled, false, "and a disabled one as disabled")

--[[ Searching matches the plain name *and* the title, because people remember
     either: "questie" and "Questie-Octo" are the same addon to everybody except
     the sort. ]]--
eq(table.getn(OB.FilterAddOnRows(GLOBAL_addons, "")), table.getn(GLOBAL_addons),
        "an empty term filters nothing")
eq(table.getn(OB.FilterAddOnRows(GLOBAL_addons, "questie")), 1, "a name is found")
eq(table.getn(OB.FilterAddOnRows(GLOBAL_addons, "shagu")), 1, "case does not matter")
eq(table.getn(OB.FilterAddOnRows(GLOBAL_addons, "nothing at all")), 0,
        "and an unknown term finds nothing")

--[[ **Toggling writes to the client's list**, which is the same list the login
     screen reads -- so a change here is the change the next load sees. Nothing
     loads or unloads now, which is why the window says so. ]]--
GLOBAL_bag = GLOBAL_addons[1]
eq(GLOBAL_bag.enabled, true, "an addon that starts enabled")
OB.ToggleAddOn(GLOBAL_bag)
eq(OB.AddOnRows()[1].enabled, false, "is disabled by toggling it")

OB.ToggleAddOn(OB.AddOnRows()[1])
eq(OB.AddOnRows()[1].enabled, true, "and enabled again by toggling it back")

--[[ The window itself draws without error, which is the part that has to work
     before any of the above is visible. ]]--
GLOBAL_list = OB.CreateAddOnList()
check(GLOBAL_list ~= nil, "the window builds")
check(not GLOBAL_list:IsShown(), "closed until asked for")

OB.ToggleAddOnList()
check(GLOBAL_list:IsShown(), "and the command opens it")
check(GLOBAL_list.rows[1]:IsShown(), "with rows drawn in it")

--[[ Not focused on open, the same rule the item database follows: stealing the
     keyboard sends the next thing typed into the box rather than into the
     game. ]]--
check(not GLOBAL_list.search.focused, "without taking the keyboard")

OB.ToggleAddOnList()
check(not GLOBAL_list:IsShown(), "and closes again")

--[[ **Made once, and this is the assertion that matters.**

     The guard is on the *frame* rather than on the namespace, because the
     namespace is rebuilt on a reload and the frame is not. A guard that checked
     only the namespace would add a second button every reload -- and the
     re-anchor above would find nothing to move, because the first insertion had
     already moved it. Two buttons on top of each other, and a menu taller every
     time. ]]--
menuHeightBefore = GameMenuFrame:GetHeight()

eq(OB.InstallGameMenuButton(), menuButton, "asking again gives the same one")
eq(GameMenuFrame:GetHeight(), menuHeightBefore,
        "and does not grow the menu a second time")

--[[ And the menu did grow once, or the bottom button is outside it -- which
     reads as the menu being broken rather than as one button being added. ]]--
check(GameMenuFrame:GetHeight() > 200,
        "the menu grew to hold it",
        "height: " .. GameMenuFrame:GetHeight())

end

gameMenuTests()

-- 48. one naming convention, everywhere
--
-- Twelve modules written over many sessions, each one reasonable on its own.
-- Consistency between them is the thing that decays quietly: nothing breaks,
-- the panel just reads like four people wrote it. Asserted rather than
-- reviewed, because a review is a thing somebody has to remember to do.
-- ---------------------------------------------------------------------------

function namingTests()

context = "naming: "

OB = boot("ROGUE", 3)

--[[ Every option row in the addon, gathered once. ]]--
allRows = {}

for i = 1, table.getn(OB.generalOptions or {}) do
    table.insert(allRows, { "general", OB.generalOptions[i] })
end

for id, m in pairs(OB.modules) do
    for i = 1, table.getn(m.options or {}) do
        table.insert(allRows, { id, m.options[i] })
    end
end

check(table.getn(allRows) > 200, "there are enough rows for this to matter",
        "rows: " .. table.getn(allRows))

--[[ **A switch is named for the thing, with the verb in front.**

     `showHotkeys`, not `hotkeyShow`. Both read fine alone and the second is
     wrong the moment there are two of them: a list sorted by key puts every
     `show*` together and scatters the `*Show`s through the alphabet, which is
     exactly what the slash prompt's generated help does. ]]--
badPrefix = {}

for i = 1, table.getn(allRows) do
    local key = allRows[i][2][2]

    if type(key) == "string" then
        if string.find(key, "Show$") or string.find(key, "Hide$") then
            table.insert(badPrefix, allRows[i][1] .. "." .. key)
        end
    end
end

eq(table.getn(badPrefix), 0, "the verb goes in front of the noun, not behind",
        table.concat(badPrefix, ", "))

--[[ **American spelling**, which is a standing instruction and the sort of thing
     that slips in one caption at a time. Checked on what the player reads
     rather than on the code, because a key nobody sees is not the point. ]]--
british = {}

for i = 1, table.getn(allRows) do
    local caption = allRows[i][2][1]

    if type(caption) == "string" then
        for _, word in ipairs({ "Colour", "Centre", "Grey", "Behaviour",
                                "Organise", "Customise" }) do
            if string.find(caption, word) then
                table.insert(british, caption)
            end
        end
    end
end

eq(table.getn(british), 0, "and the spelling is American throughout",
        table.concat(british, ", "))

--[[ **A colour setting is keyed `<thing>Color` -- unless it is the only one.**

     The rule exists to stop `headerColor` and `headerColour` living in
     different modules, and to make a module with four colours name them the
     same way. It does not apply to a module with *one*: `color` is the bar's
     colour and `bg` is the background, and `barColor` would be saying the same
     word twice.

     So three shapes are allowed and everything else is a slip: suffixed,
     indexed (`colors.1` for a combo point), and the two whole-subject names. ]]--
badColor = {}

for i = 1, table.getn(allRows) do
    local row = allRows[i][2]

    if row[3] == "color" and type(row[2]) == "string" then
        --[[ The name, with everything that is not the name taken off.

             A row can carry a scope in front -- `@variant:color`, which is how
             the power bar offers one swatch for a druid's three resources -- and
             a path behind, as `windows.1.bg` does. Neither is the name, and a
             rule that judged either would be judging the addressing rather than
             the naming. ]]--
        local leaf = row[2]

        local colon = string.find(leaf, ":")
        if colon then leaf = string.sub(leaf, colon + 1) end

        local dot = string.find(leaf, "%.[^%.]*$")
        if dot then leaf = string.sub(leaf, dot + 1) end

        local ok = string.find(leaf, "Color$")
                or string.find(row[2], "^colors%.")
                or leaf == "color" or leaf == "bg"

        if not ok then
            table.insert(badColor, allRows[i][1] .. "." .. row[2])
        end
    end
end

eq(table.getn(badColor), 0, "a colour setting says so in its key",
        table.concat(badColor, ", "))

--[[ **Every caption is Title Case**, which is the panel's own voice. Checked on
     the first letter of the first word, which is where it actually goes wrong --
     a lowercase caption in a column of capitals is visible from across the
     room. ]]--
lowerStart = {}

for i = 1, table.getn(allRows) do
    local caption = allRows[i][2][1]

    if type(caption) == "string" and caption ~= "" then
        local first = string.sub(caption, 1, 1)
        if first == string.lower(first) and first ~= string.upper(first) then
            table.insert(lowerStart, caption)
        end
    end
end

eq(table.getn(lowerStart), 0, "and every caption starts with a capital",
        table.concat(lowerStart, ", "))

--[[ **No two rows in one module share a key**, which is not a naming rule so
     much as the thing bad naming eventually causes: two settings that look
     different on the page and are the same value underneath. ]]--
dupes = {}

for id, m in pairs(OB.modules) do
    local seen = {}

    for i = 1, table.getn(m.options or {}) do
        local key = m.options[i][2]

        --[[ Section and header markers carry made-up keys that are allowed to
             repeat across modules but not within one. ]]--
        if type(key) == "string" then
            if seen[key] then table.insert(dupes, id .. "." .. key) end
            seen[key] = true
        end
    end
end

eq(table.getn(dupes), 0, "and no module names one key twice",
        table.concat(dupes, ", "))

end

namingTests()

-- 37. no row is built twice
-- ---------------------------------------------------------------------------

local function duplicateTests()

--[[ **A row built on two pages is one bug wearing three faces.**

     The Bars page builds every bar module's rows and lets visibility decide
     which are shown. Features have pages of their own, so building them there
     too built them twice -- and the second build claimed the same generated
     frame names, which took the first copy's caption away.

     In game that looked like three separate faults: the threat meter's settings
     appended to the Bars page, its sliders and checkboxes with no labels, and
     the damage meter's own tab coming up empty. ]]--
context = "no duplicate rows: "

EquadisClassicOverhaulDB = nil
OB = boot("ROGUE", 3)
OB.TogglePanel()

--[[ Counted across every page rather than checked on one, because the failure
     is precisely that a row exists somewhere it should not. ]]--
local seen, duplicated = {}, {}

for c = 1, table.getn(OB.settings.categories) do
    local cat = OB.settings.categories[c]

    for r = 1, table.getn(cat.page.rows) do
        local widget = cat.page.rows[r]
        local w = widget.w

        if w and w.key and w.key ~= "" then
            local key = OB.WidgetKey(w)

            if seen[key] and seen[key] ~= cat.name then
                table.insert(duplicated, key
                        .. " (" .. seen[key] .. " and " .. cat.name .. ")")
            end

            seen[key] = cat.name
        end
    end
end

eq(table.getn(duplicated), 0, "no row is built on two pages",
        table.concat(duplicated, ", "))

--[==[ **And not twice on one page either**, which the sweep above could not
     see: it recorded a page name per key and only complained when the *second*
     page differed.

     The Action Bars page had two controls onto `fontOutline` -- `Text Outline`
     written by hand and `Font Outline` generated from `styled` -- with different
     captions, in different columns, writing the same setting. Move one and the
     other is wrong until the panel is reopened, and nothing in the suite had an
     opinion. ]==]
local twice = {}

for c = 1, table.getn(OB.settings.categories) do
    local cat = OB.settings.categories[c]
    local here = {}

    for r = 1, table.getn(cat.page.rows) do
        local w = cat.page.rows[r].w

        if w and w.key and w.key ~= "" then
            local key = OB.WidgetKey(w)

            if here[key] then
                table.insert(twice, cat.name .. ": " .. key
                        .. " (" .. tostring(here[key])
                        .. " and " .. tostring(w.caption) .. ")")
            end

            here[key] = w.caption
        end
    end

end

eq(table.getn(twice), 0, "and no setting has two controls on one page",
        table.concat(twice, ", "))

--[==[ **And every page finished building.**

     `buildPage` wraps each builder in a `pcall` and reports what threw through
     `fault`, so a page that dies halfway leaves the rest of the panel working --
     which is right, and is also why nothing here noticed when eighteen of the
     twenty-one pages came out holding a single header row. The suite was green
     against a settings window with no settings in it.

     One removed constant did it. Whatever does it next, this is the assertion
     that says so. ]==]
local faults = {}

for i = 1, table.getn(OB.panelFaults or {}) do
    local f = OB.panelFaults[i]
    table.insert(faults, tostring(f.label) .. ": " .. tostring(f.err))
end

eq(table.getn(faults), 0, "and every page built without throwing",
        table.concat(faults, " | "))

--[==[ A page holding nothing but its own header is what a half-built one looks
     like from outside, and `fault` above is only reached by a *throw*. A builder
     that returns early leaves the same wreckage quietly. ]==]
local empty = {}

for c = 1, table.getn(OB.settings.categories) do
    local cat = OB.settings.categories[c]

    if table.getn(cat.page.rows) < 2 then
        table.insert(empty, cat.name .. " (" .. table.getn(cat.page.rows) .. ")")
    end
end

eq(table.getn(empty), 0, "and no page came out holding only its header",
        table.concat(empty, ", "))

--[[ Specifically: a feature's settings belong to its own tab and nowhere else.
     The Bars page is where this went wrong, so it is named rather than left to
     the sweep above. ]]--
local barsPage
for c = 1, table.getn(OB.settings.categories) do
    if OB.settings.categories[c].name == "Omni Bars" then
        barsPage = OB.settings.categories[c].page
    end
end

local strays = {}
for r = 1, table.getn(barsPage.rows) do
    local w = barsPage.rows[r].w
    if w and w.module then
        local m = OB.modules[w.module]
        if m and m.feature then table.insert(strays, w.module .. "." .. w.key) end
    end
end

eq(table.getn(strays), 0, "and no subsystem's settings sit under Bars",
        table.concat(strays, ", "))

--[[ The threat meter's own tab still has them, so the fix removed a copy rather
     than the row. ]]--
check(OB.widgets["module:threat:width"] ~= nil, "the threat meter keeps its rows")
check(OB.widgets["module:damage:windows.1.width"] ~= nil,
        "and so does the damage meter")

--[[ **Every caption survives.** A label is a font string this file creates, not
     one the template names after the frame -- so two controls can no longer
     share one by generating the same name. Colour swatches always built their
     own, which is why they were the only kind that kept their labels. ]]--
local unlabelled = {}

for c = 1, table.getn(OB.settings.categories) do
    local cat = OB.settings.categories[c]

    for r = 1, table.getn(cat.page.rows) do
        local widget = cat.page.rows[r]
        local w = widget.w

        if w and w.caption and w.caption ~= "" and widget.label then
            if widget.label:GetText() ~= w.caption then
                table.insert(unlabelled, cat.name .. ":" .. w.key)
            end
        end
    end
end

eq(table.getn(unlabelled), 0, "and every control still carries its caption",
        table.concat(unlabelled, ", "))

end

duplicateTests()

--[==[ **Line of sight, now that something on this client can answer it.**

     The check has existed for a long while and shipped switched off, on the
     reasoning that it needs UnitXP SP3 and most installs do not have it. Both
     halves of that were wrong: UnitXP is not the only source, and the check
     works without any extension at all -- the reactive latch reads the client's
     own refusal message, which is a real signal and the only one a stock 1.12
     client has.

     So it ships on, and what differs between clients is how quickly it answers
     rather than whether it does. ]==]
function sightTests()

context = "line of sight: "

OB = boot("HUNTER", 60, { hasTarget = true, ranged = "Guns", nampower = true })

eq(OB.profile.modules.distance.losCheck, true, "the line of sight check ships on")

--[==[ **The capability is not UnitXP's alone**, and this is the bug that was
     hiding in it. `OB.InSight` asks a native `IsUnitInSight` first and UnitXP
     second; the probe behind `OB.Can("sight")` asked only about UnitXP. So a
     Nampower build extended with the sight query reported "no line of sight"
     while the function providing it sat there answering -- and the distance
     module told that player their check was reactive, continuously, while the
     continuous check was running. ]==]
Stub.SetUnitXP(false)
Stub.SetLineOfSight(false)
Stub.SetNampowerSight(true)
OB.RecheckCapabilities()

eq(OB.Can("sight"), true, "a native IsUnitInSight is a line of sight check")
eq(OB.InSight("target"), true, "and it is what answers")

Stub.player.inSight = false
eq(OB.InSight("target"), false, "a wall is a wall")
Stub.player.inSight = true

--[[ SP3's own, which was the only source this ever recognised. ]]--
Stub.SetNampowerSight(false)
Stub.SetUnitXP(true)
Stub.SetLineOfSight(true)
OB.RecheckCapabilities()

eq(OB.Can("sight"), true, "so is UnitXP's own")
eq(OB.InSight("target"), true, "and it answers when nothing else is loaded")

--[==[ **The distance query without the sight one**, which is a real build and
     the reason these are two capabilities rather than one. "Cannot tell" has to
     stay distinguishable from "blocked": treating the first as the second would
     put a wall in front of every target on a client with no opinion. ]==]
Stub.SetLineOfSight(false)
OB.RecheckCapabilities()

eq(OB.HasUnitXP(), true, "SP3 is still there for distances")
eq(OB.Can("sight"), false, "and cannot be asked about walls")
eq(OB.InSight("target"), nil, "which is nil, and nil is not false")

--[[ Back to a bare client for whatever runs next. ]]--
Stub.SetUnitXP(false)
Stub.SetNampowerSight(false)
Stub.player.inSight = true
OB.RecheckCapabilities()

eq(OB.Can("sight"), false, "and a stock client cannot be asked at all")

end

--[==[ **A predicate in the reload slot**, which is what one `nil` too many buys.

     The positional row ends `dependsOn, greyWhen, requiresReload`, so a slider
     that pads with three nils instead of two pushes its greyWhen one place along
     into `requiresReload`. Two things then go wrong at once and neither names
     itself: the row never greys, and every change to it demands a reload -- with
     the predicate printed back as the reason, so the notice reads
     "!showAuraTimers".

     Eight rows had it. Three shipped in the last two versions, three had been
     there since the action bars got their own scale sliders, and no two of them
     would ever have been reported as the same bug.

     The rule is that `requiresReload` is a sentence for a person to read, so it
     may not look like a predicate and may not name a setting. ]==]
function optionRowTests()

context = "option rows: "

local strays = {}

for id, m in pairs(OB.modules) do
    local rows = m.options
    local defaults = m.defaults or {}

    if type(rows) == "table" then
        for r = 1, table.getn(rows) do
            local opt = rows[r]
            local reload = opt and opt[10]

            if type(reload) == "string" then
                local first = string.sub(reload, 1, 1)

                if first == "!" or first == "@" or defaults[reload] ~= nil then
                    table.insert(strays, id .. "." .. tostring(opt[2])
                            .. " -> " .. reload)
                end
            end
        end
    end
end

eq(table.getn(strays), 0,
        "no row's predicate has landed in the reload slot",
        table.concat(strays, ", "))

--[==[ **And no navigation entry leads to a page with nothing on it.**

     A section marker is a tab in the second column, and one whose rows have all
     gone -- removed, moved to another section, or never written -- is a button
     somebody clicks to be shown an empty panel. That is indistinguishable from
     the addon being broken, and it is what "no options in ui" looks like from
     outside.

     Driven the way a person drives it: select the category, click each entry,
     count the rows the panel then decides to show. Headers do not count -- a
     page holding only its own title is the thing being looked for.

     A raw sweep of the option tables cannot answer this. The appearance block is
     injected into whichever section a module names, so `map`'s General reads as
     empty in the source and is not: a probe in `.eco-work` said so and cost a
     detour. ]==]
local barren = {}

for c = 1, table.getn(OB.settings.categories) do
    local cat = OB.settings.categories[c]
    OB.SelectCategory(cat.name)

    for b = 1, table.getn(OB.settings.subButtons or {}) do
        local button = OB.settings.subButtons[b]

        if button:IsShown() and button.value then
            if OB.settings.subPick then OB.settings.subPick(button.value) end
            OB.RefreshPanel(true)

            local shown = 0

            for r = 1, table.getn(cat.page.rows) do
                local w = cat.page.rows[r]

                if w.visible and w.w and w.w.key and w.w.key ~= ""
                        and w.w.kind ~= "header" then
                    shown = shown + 1
                end
            end

            if shown == 0 then
                table.insert(barren, cat.name .. " :: "
                        .. tostring(button.label and button.label:GetText()))
            end
        end
    end
end

eq(table.getn(barren), 0, "no section leads to a page with no settings on it",
        table.concat(barren, ", "))

end

optionRowTests()

--[==[ **One column that scrolls, rather than two that do not.**

     Rows used to be assigned a column at build time, and any that would have run
     off the bottom of column one spilled into column two. That produces a page
     read in two directions -- the tail of one list continuing at the top of the
     next -- and it still runs out: the Action Bars page is eighty-five rows and
     two columns hold about twenty-four, so everything past that was drawn below
     the panel where nothing could reach it. ]==]
function scrollTests()

context = "panel scrolling: "

EquadisClassicOverhaulDB = nil
OB = boot("ROGUE", 60)
OB.TogglePanel()

--[==[ **Nothing is ever placed in a second column.** `widget.column` is still
     what a row asked for -- the appearance block asks for two -- and
     `placedColumn` is where it ended up, which is now always one. ]==]
local spilled, tallest, shortest = {}, nil, nil

for c = 1, table.getn(OB.settings.categories) do
    local cat = OB.settings.categories[c]

    for r = 1, table.getn(cat.page.rows) do
        local widget = cat.page.rows[r]

        if widget.visible and (widget.placedColumn or 1) ~= 1 then
            table.insert(spilled, cat.name .. ":" .. tostring(widget.w
                    and widget.w.key))
        end
    end

    local range = cat.page.range or 0

    if range > 0 and (not tallest or range > tallest.range) then
        tallest = { cat = cat, range = range }
    end

    if range == 0 and not shortest then shortest = cat end
end

eq(table.getn(spilled), 0, "no row is placed in a second column",
        table.concat(spilled, ", "))

--[==[ **And there is no `ScrollFrame`.** One was tried and hid the whole
     interface: `SetScrollChild`, the child's anchoring and the clipping
     rectangle are three separate pieces of engine behaviour, none of which a
     harness that models frames as tables can see, and getting any one wrong
     draws a page of controls nowhere with nothing to say so.

     The page is a direct child of the panel, exactly as it was before any of
     this, and the scrolling is `SetPoint` on rows that were being placed
     anyway. ]==]
check(tallest ~= nil, "some page is taller than the panel")

GLOBAL_page = tallest.cat.page
eq(GLOBAL_page:GetParent(), OB.settings, "a page is a child of the panel")
eq(GLOBAL_page.view, nil, "and there is no scroll frame between them")

OB.SelectCategory(tallest.cat.name)
check(GLOBAL_page:IsShown(), "selecting a section shows its page")

--[==[ **The wheel is on the panel**, not on the page: a page is exactly the
     rectangle its rows sit in, so a handler there would stop working in the
     margins -- including over the scrollbar, which is where somebody expects it
     to work most. ]==]
eq(GLOBAL_page.scroll, 0, "a page opens at the top")

GLOBAL_argWas = arg1
arg1 = -1
OB.settings.scripts.OnMouseWheel()

check(GLOBAL_page.scroll > 0, "one notch down moves it",
        tostring(GLOBAL_page.scroll))

for GLOBAL_i = 1, 300 do OB.settings.scripts.OnMouseWheel() end

eq(GLOBAL_page.scroll, tallest.range,
        "and it stops at the last row rather than past it")

--[==[ **The last row is reachable**, which is what the range is measured
     against: at the bottom of the scroll the final row has to be drawn, or the
     page has a setting nobody can get to. ]==]
GLOBAL_lastShown = nil
for GLOBAL_r = 1, table.getn(GLOBAL_page.rows) do
    if GLOBAL_page.rows[GLOBAL_r]:IsShown() then GLOBAL_lastShown = GLOBAL_r end
end

GLOBAL_lastReal = nil
for GLOBAL_r = 1, table.getn(GLOBAL_page.rows) do
    if GLOBAL_page.rows[GLOBAL_r].visible then GLOBAL_lastReal = GLOBAL_r end
end

eq(GLOBAL_lastShown, GLOBAL_lastReal,
        "the last row on the page is drawn at the bottom of the scroll")

--[==[ **And the rows that scrolled off the top are hidden**, which is the job a
     `ScrollFrame`'s rectangle would have done and the only part of it this panel
     needed. Drawn instead, they would sit over the tab list. ]==]
check(not GLOBAL_page.rows[1]:IsShown(),
        "a row scrolled off the top is hidden rather than drawn over the tabs")

arg1 = 1
for GLOBAL_i = 1, 600 do OB.settings.scripts.OnMouseWheel() end

eq(GLOBAL_page.scroll, 0, "and at the first, coming back")
check(GLOBAL_page.rows[1]:IsShown(), "with the first row back on screen")
arg1 = GLOBAL_argWas

--[==[ **The bar is only there when it does something**, and never over a page
     that is not on screen -- it is a sibling of the page, so it does not follow
     it out of sight on its own. ]==]
check(GLOBAL_page.bar:IsShown(), "a page that scrolls has a bar")
eq(GLOBAL_page.bar:GetParent(), OB.settings, "which belongs to the panel")

check(shortest ~= nil, "and some page fits")
check(not shortest.page.bar:IsShown(),
        "one that fits does not", shortest.name)

--[==[ **A row taller than the page is drawn anyway.**

     "Whole rows only" is right for a control and wrong for a paragraph. A
     `lines` row measures its own height and the font it measures at is a
     setting, so a description that is two hundred pixels at ten point is past
     the height of the page at eighteen -- and requiring it to fit would make it
     vanish entirely at the size that made it big, which is the one moment
     somebody is looking at it.

     Nothing in the panel is that tall today -- the worst is a little over two
     hundred against a page of four hundred and seventy-eight -- so this is
     asserted by making one, because the failure it prevents is silent. ]==]
OB.SelectCategory(tallest.cat.name)
OB.ScrollPage(GLOBAL_page, 0)

GLOBAL_tallRow = nil
for GLOBAL_r = 1, table.getn(GLOBAL_page.rows) do
    if GLOBAL_page.rows[GLOBAL_r].visible and not GLOBAL_tallRow then
        GLOBAL_tallRow = GLOBAL_page.rows[GLOBAL_r]
    end
end

check(GLOBAL_tallRow ~= nil, "there is a row to make tall")

GLOBAL_advWas = GLOBAL_tallRow.advance
GLOBAL_tallRow.advance = 900
OB.LayoutPage(GLOBAL_page)

check(GLOBAL_tallRow:IsShown(),
        "a row taller than the whole page is still drawn")

GLOBAL_tallRow.advance = GLOBAL_advWas
OB.LayoutPage(GLOBAL_page)

OB.SelectCategory(shortest.name)
check(not GLOBAL_page.bar:IsShown(),
        "and a page's bar goes when the page does")

end
scrollTests()
navigationTests()

--[==[ **Edit mode's own interface, which it did not have, and the one place a
     notice goes now.**

     Edit mode unlocks every frame in the addon, outlines each of them and takes
     the mouse from everything underneath -- and it said so in a chat line.
     Somebody who scrolled past it is looking at an interface where nothing
     clicks, which is what bind mode was reported as before it got a banner.

     Notices had a frame of their own for the single case of "this needs a
     reload": a red strip with its own backdrop and its own close button. Two
     frames saying "something you should know" in two visual languages, and none
     of it under test -- which is how eight rows that demanded a reload by
     accident went unnoticed until a sweep found them. ]==]
function editPanelTests()

context = "edit panel: "

EquadisClassicOverhaulDB = nil
OB = boot("ROGUE", 60)

OB.pendingNotice = nil
GLOBAL_edit = OB.EditPanel()

check(GLOBAL_edit ~= nil, "there is an edit mode panel")
check(not GLOBAL_edit:IsShown(), "and it is not on screen doing nothing")

eq(_G["EquadisClassicOverhaulReloadWarning"], nil,
        "and the notice's own separate frame is gone")

--[==[ **The mode says it is on**, which is the whole reason for the banner. ]==]
OB.SetEditMode(true)

check(GLOBAL_edit:IsShown(), "entering edit mode puts it on screen")
eq(GLOBAL_edit.title:GetText(), "Edit Mode", "titled for the mode")
check(string.find(GLOBAL_edit.help:GetText(), "Drag", 1, true) ~= nil,
        "and it says what to do", GLOBAL_edit.help:GetText())
check(not GLOBAL_edit.reload:IsShown(),
        "with no Reload UI button under it to throw the arrangement away")

--[==[ **A notice wins the panel**, because it is the answer to something you
     just did and edit mode is a state you are already in. ]==]
OB.RequireReload("the chat font")

check(GLOBAL_edit:IsShown(), "a notice shows the panel")
eq(GLOBAL_edit.title:GetText(), "Reload Required", "under its own title")
check(string.find(GLOBAL_edit.help:GetText(), "chat font", 1, true) ~= nil,
        "carrying the reason it was given", GLOBAL_edit.help:GetText())
check(GLOBAL_edit.reload:IsShown(), "and the button that acts on it")

--[==[ **And dismissing it hands the panel back**, rather than leaving edit mode
     with nothing on screen saying it is on. ]==]
OB.DismissNotice()

check(GLOBAL_edit:IsShown(), "dismissing gives the panel back to edit mode")
eq(GLOBAL_edit.title:GetText(), "Edit Mode", "which is still on")
check(not GLOBAL_edit.reload:IsShown(), "and the button goes with the notice")

OB.SetEditMode(false)
check(not GLOBAL_edit:IsShown(), "leaving the mode puts the panel away")

--[==[ **A notice outside edit mode still shows.** It is not an edit mode
     feature that happens to be reachable; it is the addon's one notice
     surface. ]==]
OB.RequireReload("something else")

check(GLOBAL_edit:IsShown(), "a notice with the mode off still shows")
OB.DismissNotice()
check(not GLOBAL_edit:IsShown(), "and dismissing it puts the panel away again")

end

--[[ Last, because it boots a client of its own and leaves `OB` pointing at it.
     Anything after this would be testing a hunter with a gun. ]]--
sightTests()
editPanelTests()

--[==[ **The one tooltip that never asked for a default anchor.**

     Placement is applied by wrapping `GameTooltip_SetDefaultAnchor`, and a
     handful of frames never call it: they own the tooltip themselves with
     `SetOwner(this, "ANCHOR_RIGHT")` and keep the client's anchor. The need
     /greed roll popup is the one that gets looked at, because it appears in the
     middle of a fight and is the only tooltip on screen at the time.

     So every tooltip in the game obeyed the position settings except those, and
     with the default placement -- fixed, screen centred -- that is one tooltip
     behaving visibly unlike all the rest. ]==]
function lootRollTooltipTests()

context = "loot roll tooltip: "

EquadisClassicOverhaulDB = nil
OB = boot("ROGUE", 60)

GLOBAL_tip = GameTooltip
GLOBAL_tipMod = OB.modules.tooltip

Stub.lootRolls[7] = { name = "Krol Blade", price = 12345, count = 1, quality = 4 }
Stub.ShowLootRoll(1, 7)

GLOBAL_rollIcon = getglobal("GroupLootFrame1IconFrame")
check(GLOBAL_rollIcon ~= nil, "the popup has an icon to point at")

--[==[ Hovered the way a person hovers it: the client's own `OnEnter`, which
     owns the tooltip against the icon and then asks for the roll's item. ]==]
GLOBAL_tip:Hide()
GLOBAL_thisWas = this
this = GLOBAL_rollIcon
GLOBAL_rollIcon.scripts.OnEnter()
this = GLOBAL_thisWas

eq(GLOBAL_tip:Line(1):GetText(), "Krol Blade",
        "hovering the roll shows the item")

--[==[ **And it is placed where this addon places tooltips.** Before, the point
     was never set at all: the client anchored it beside the icon and every
     setting on the Tooltip page passed it by. ]==]
GLOBAL_rollPoint, GLOBAL_rollRel = GLOBAL_tip:GetPoint(1)

eq(GLOBAL_rollPoint, "CENTER", "and the tooltip is placed by the addon",
        tostring(GLOBAL_rollPoint))
eq(GLOBAL_rollRel, UIParent, "against the screen, like every other tooltip")

--[==[ **The owner is still the icon**, which is what the client reads to decide
     the tooltip belongs to that frame. Placement is ours; ownership is not
     ours to take. ]==]
eq(GLOBAL_tip:GetOwner(), GLOBAL_rollIcon,
        "while the popup still owns it")

--[==[ **`ANCHOR_NONE` is left alone**, which is the terminating condition as
     well as the right rule: it is the anchor this addon's own placement uses,
     and a caller asking for no anchor has said where it wants the tooltip. ]==]
GLOBAL_tip:Hide()
GLOBAL_tip:SetOwner(UIParent, "ANCHOR_NONE")
GLOBAL_tip:SetBagItem(0, 1)

check(true, "a tooltip owned with no anchor does not recurse")

--[==[ **This addon's own windows keep their anchors.** A damage meter row, a
     bag slot, the reputation bar: each anchors its tooltip beside the thing it
     describes on purpose, and the policy written for the client's frames swept
     them up too -- ten deliberate anchors moved to the screen's fixed spot. They
     go through `OB.OwnTooltip` now and the wrapper leaves them alone. ]==]
GLOBAL_tip:Hide()
GLOBAL_tip:ClearAllPoints()
OB.OwnTooltip(GLOBAL_rollIcon, "ANCHOR_RIGHT")

GLOBAL_ownPoint = GLOBAL_tip:GetPoint(1)
eq(GLOBAL_ownPoint, nil,
        "a tooltip this addon anchored itself is not moved by the policy")
eq(GLOBAL_tip:GetOwner(), GLOBAL_rollIcon, "and keeps its owner")
eq(GLOBAL_tip.eqEcoOwnAnchor, nil, "and the flag does not outlive the call")

--[[ While a client frame doing the same thing still is. ]]--
GLOBAL_tip:Hide()
GLOBAL_tip:ClearAllPoints()
GLOBAL_tip:SetOwner(GLOBAL_rollIcon, "ANCHOR_RIGHT")

eq(GLOBAL_tip:GetPoint(1), "CENTER",
        "while the client's own frames still follow the placement")

end

lootRollTooltipTests()

--[==[ **Tank mode: the same threat table read from the other side.**

     Every nameplate threat colour answered the damage dealer's question -- "it
     is on you" was the bad news. A tank asks the same question and wants the
     opposite answer, and reading the colours in reverse in a fight is a
     translation nobody should be doing.

     Three states, not four reversed: "no target" and "casting" are the same for
     everybody, and the middle one -- about to lose it -- has no counterpart on
     the other side. It is a number, and the number is the meter's. ]==]
function tankModeTests()

context = "tank mode: "

EquadisClassicOverhaulDB = nil
OB = boot("WARRIOR", 60)

GLOBAL_plates = OB.modules.nameplates
GLOBAL_pcfg = OB.profile.modules.nameplates
GLOBAL_threat = OB.modules.threat

eq(GLOBAL_pcfg.threatMode, "dps", "the plates ship on the damage dealer's side")
check(not GLOBAL_plates:TankMode(), "which is not tank mode")

--[[ And in that mode nothing above has changed. ]]--
eq(GLOBAL_plates:ThreatStateColor("me"), GLOBAL_pcfg.threatColor,
        "on you is still the damage dealer's red")
eq(GLOBAL_plates:ThreatStateColor("other"), GLOBAL_pcfg.noThreatColor,
        "and on somebody else is still green")

--[==[ **Switched to tank, the two client-only states swap sides.** No packet
     has arrived, so there is no middle state yet -- and that is the honest two,
     not orange for "no data". ]==]
GLOBAL_pcfg.threatMode = "tank"
GLOBAL_threat.entries = {}

check(GLOBAL_plates:TankMode(), "the mode can be switched")
eq(OB.RunnerUpThreatRatio(), nil, "with no packet there is no runner-up reading")

eq(GLOBAL_plates:TankThreatState("me"), "holding", "on you is holding")
eq(GLOBAL_plates:TankThreatState("other"), "lost", "on somebody else is lost")
eq(GLOBAL_plates:TankThreatState("none"), "none",
        "no target is the same for everybody")
eq(GLOBAL_plates:TankThreatState("casting"), "casting", "and so is casting")

eq(GLOBAL_plates:ThreatStateColor("me"), GLOBAL_pcfg.tankHoldingColor,
        "holding is the tank's green")
eq(GLOBAL_plates:ThreatStateColor("other"), GLOBAL_pcfg.tankLostColor,
        "lost is the tank's red")
eq(GLOBAL_plates:ThreatStateColor("none"), GLOBAL_pcfg.threatNoneColor,
        "and no target keeps its grey")

--[==[ **The middle state needs the meter**, and it is read against *my* raw
     threat rather than the packet's percent -- which is measured against
     whoever the server calls the tank, and that may not be me. ]==]
GLOBAL_me = UnitName("player")
OB.profile.modulesEnabled.threat = true

GLOBAL_threat.entries = OB.ParseThreatPacket("TWTv4=" .. GLOBAL_me
        .. ":1:10000:100:1;Rogue:0:7000:70:1;Mage:0:3000:30:0")

near(OB.RunnerUpThreatRatio(), 0.7, 0.001,
        "the runner-up is read as a fraction of my own threat")
eq(GLOBAL_plates:TankThreatState("me"), "holding",
        "seventy percent is holding at the default threshold")

GLOBAL_threat.entries = OB.ParseThreatPacket("TWTv4=" .. GLOBAL_me
        .. ":1:10000:100:1;Rogue:0:8500:85:1")

eq(GLOBAL_plates:TankThreatState("me"), "losing",
        "eighty-five percent is about to lose it")
eq(GLOBAL_plates:ThreatStateColor("me"), GLOBAL_pcfg.tankLosingColor,
        "in the tank's orange")

--[[ The threshold is a setting, and it is read. ]]--
GLOBAL_pcfg.tankLoseAt = 90
eq(GLOBAL_plates:TankThreatState("me"), "holding",
        "raising the threshold to ninety makes eighty-five holding again")
GLOBAL_pcfg.tankLoseAt = 80

--[[ Losing it is a fact about *me*; once it is on somebody else the number no
     longer matters. ]]--
eq(GLOBAL_plates:TankThreatState("other"), "lost",
        "on somebody else is lost whatever the numbers say")

--[==[ **Nought of my own is not a reading.** There is no fraction of nothing,
     and "holding" a mob I have not touched is not a state anybody wants
     painted. ]==]
GLOBAL_threat.entries = OB.ParseThreatPacket("TWTv4=" .. GLOBAL_me
        .. ":1:0:0:1;Rogue:0:500:100:1")
eq(OB.RunnerUpThreatRatio(), nil, "with no threat of my own there is no ratio")

--[==[ **The rows grey with the mode**, rather than vanishing: the colours still
     mean what they say, and a row that disappears reads as a setting this addon
     does not have. ]==]
GLOBAL_pcfg.threatMode = "dps"
check(OB.predicates.plates_dps_mode(), "the tank rows grey in damage mode")
GLOBAL_pcfg.threatMode = "tank"
check(not OB.predicates.plates_dps_mode(), "and come alive in tank mode")

GLOBAL_pcfg.threatMode = "dps"
GLOBAL_threat.entries = {}

end

tankModeTests()
